/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20080417-14","meetingId":"h20-cm04","date":"2008年4月17日","dateIso":"2008-04-17","committee":"行財政改革特別委員会","time":"午後１時０２分～午後３時２３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件整理しています。","topics":[{"id":"topic-01","title":"の財政（歳入）に関すること","agenda":"の財政（歳入）に関すること","exchanges":[{"speaker":"山内委員","kind":"質問","question":"品川区の歳入ということで考えていきますと、例えば品川区ということだけで考えますと、非常に施設が限られてしまうということは事実だと思うんです。行政のほうで何カ所ぐらいあるのかと、もちろん具体的な数字は出てこないかと思うんですけれども、もし教えていただければと思うんです。","respondent":"日下部企画財政課長","answer":"ご説明申し上げましたが、区立の施設で考えられるのはそのぐらいかなと、そんなふうに考えております。","id":"exchange-001"},{"speaker":"阿部委員","kind":"提案","question":"しかし２３区ということですし、競馬場側から提案する話ではないので、品川区からも提案という形でやっていけるのではないかと。以上の三つの点について、それぞれお考えを伺えればと思いますとの意見を述べました。","respondent":"日下部企画財政課長","answer":"予定しているものは、これから先を見据えた長期基本計画の中で検討していこうということになっておりますし、またそういう中で。その辺の可能性については、これからまた検討をさせていただきたいと思います。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"命名権というのが活用できるようになった根拠というか、根拠法で何か変わったことがあったのかどうか、その辺をお聞きしたい。この辺で、導入に当たって、どういう経過を経てやってきたのか、その辺でわかるところがあったら、説明を求めました。","respondent":"日下部企画財政課長","answer":"どうしてもやはり使用料収入というのはそれほど多くは見込めないというところがありますので、命名権を活用するという流れです。それから、都道府県、市町村、公共側の導入の経緯ということでありますけれども、それは今お答えしたとおりの流れから出ているものです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"導入をめぐる課題というところで、４点挙がっていて、かなりいろいろ問題点はあるかなと思っているんです。もしその辺がわかったら、教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"公式に検討を進めているというような経過は、特にございません。私どものレベルで、さまざまないろいろな勉強なり、研究は進めているという面はあります。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その研究の中に、ぜひ区民の広い意見を取り入れていってほしいと求めました。これは意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"幾つか伺いたいんですけれども、導入をめぐる課題の中で、(2)で、スポンサー企業としての適格性のところで、ふさわしいかどうかが問われるんだと。なぜこれを重視しているのか、スポンサーがふさわしいかどうかという、もう少しご説明いただけたらと思っています。","respondent":"日下部企画財政課長","answer":"そういうレベルでご答弁申し上げたわけではありませんので、その辺は誤解のないように、ひとつご理解をいただきたいと思います。そういうような点につきましては、やはりしっかりと問題意識を持って取り組むべきだという、このような考え方です。","id":"exchange-006"},{"speaker":"高橋委員","kind":"質問","question":"ちょっとお尋ねしたいのは、例えば、渋谷区で年間８,０００万円というのが入って、５年で４億円ですけれども、そういうのは歳入のどこに入って、税金等というのは、どこにどう支払うのか、ちょっと説明を求めました。","respondent":"日下部企画財政課長","answer":"一般的には、例えば、諸収入の中で広告料収入というような位置付けで収入をしているケースも多いようです。その辺は、最終的には、各自治体によってまた多少違う面があると承知をしております。","id":"exchange-007"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"もう１点言うと、何かそぐわないかなという感じが、実はしたんです。利用者が安くできるためにそういうネーミングライツを使ってみるとか、何かその辺、どうか尋ねました。","respondent":"日下部企画財政課長","answer":"確かに、委員、ご指摘のような考え方というのも一つだと思うんです。そういうようなことも考えられますので、命名権を考えるに当たっての一つの検討課題ではないかと、このように認識をしております。","id":"exchange-008"},{"speaker":"石田（慎）委員","kind":"質問","question":"ほかは全部、例えばスタジアム等の看板等の設置というのは、契約金内で各自治体等が工事を行うのか。それとも、その工事費はまた別に徴収をするのかということを、ちょっと教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"すべてを確認したわけではないんですけれども、やはり大体、そういう看板の付け替えとかに、相当お金がかかるんです。これは契約の中でも別立てで負担をいただくというようなケースが、結構多いようです。","id":"exchange-009"},{"speaker":"高橋委員","kind":"質問","question":"よく企業名を出して、そういうのもあるのではないかなと、さっきちょっと思ったんです。ちょっと議論の場が違うのかなとも思ったんですが、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"現にそういう形を取り入れているようなケースも、私どもも承知をしております。今後とも続けていきたいと考えておりますので、ご指摘があったような点も、今後の一つの課題ではないかと認識をしております。","id":"exchange-010"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"山内委員","kind":"質問","question":"総合評価方式を導入されるということでお話があったということを伺ったんですけれども、学識経験者を３回から１回にすると、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"山内委員","kind":"質問","question":"そうすると、今後は、総合評価方式も含めて検討課題というか、そういう形で、こういう委員会を通していろいろと勉強していくという形になっていくということか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"山内委員","kind":"意見","question":"これはあくまでも案なので、やはりそれは入れていくべきだと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"委員会のまとめなので、やっぱり１年間の議論の中で実ってきたものという言い方ですか、それはやっぱりまとめに反映させるべきだと思うんです。今までの議論のその仕切りの中で進めるべきではないのかなと、私は思ったので、一言。","respondent":"鈴木（ひ）委員長","answer":"報告を受けていないことに対して、今日、このまとめの中に入れていくことはちょっとできないと思います。そういうふうな変更ということはあり得るかなとは思いますので、その点に関しては、５月の報告を受けたところで仕切りたいということです。","id":"exchange-014"},{"speaker":"原委員","kind":"意見","question":"５月ということもわかるんですけれども、正副委員長で、このことについてちょっともう少し踏み込んで話していただくといいかなという気がいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"中塚委員","kind":"意見","question":"まだ報告もされていない中身を、議論もされていない中で、正副委員長に一任と言われても、どうまとめていいのかと察するんですけれども、それはちょっと、私の意見は違いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"原委員","kind":"質問・要望","question":"そういう考えを、ちょっと委員長、副委員長でお話をいただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員長","kind":"意見","question":"５月に改めてきちんとした形でご報告いただきますけれども、昨日、わかる範囲でご報告をいただくことは可能だと思うんです。ここの中身に入っていることですので、わかる範囲で、ご報告いただくということにしますかとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"山内委員","kind":"質問","question":"もう既に、９月２７日の行財政改革特別委員会でも資料も出ているということなんです。ですから、やはり総合評価方式も導入するべきではないかということなので、それは。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"あまり中身に入る話ではないと思うので、総務委員会の試行するというところに、あまり入らないほうがいいのではないかなという気がするんです。３回専門の学識経験者が入っているのが、その概略部分を教えていただくのがこの委員会ではないかなと思うんですけれども、いかがか尋ねました。","respondent":"市岡総務部長","answer":"ご趣旨は理解したように受けとめします。もう一度ちょっと確認するというご説明になろうかと思いますので、担当の課長のほうから、説明させていただきたいと思います。","id":"exchange-020"},{"speaker":"阿部委員","kind":"質問","question":"多分残るのでしょうから、ちょっとそこら辺は、５月１３日に全部できるという日程でのお考えなんでしょうか。これは委員長に伺いたいんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"今日の時点で、今、４項目は充分質疑していってもらって、ここは合意が得られるかどうかというのは、皆さん、これから話し合えば、と思うんです。１回休憩を取って、こんな文言でどうですかということは、そこで検討してもらうという形しか方法はないと思うんです。","respondent":"鈴木（ひ）委員長","answer":"委員会としてまとまったものを行政のほうに提言という形で出していきたいと考えておりますので、総合評価方式のことについては、５月の時点で改めて出するということになると思います。","id":"exchange-022"},{"speaker":"阿部委員","kind":"質問","question":"５月に十分な時間が取れれば、それはそれで構わないと思います。ただ、それまでの間に委員会を開いてはいけないものなんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"武内委員","kind":"確認","question":"今まで３回だったのが１回になって、この部分があるか、ないかの違いだけなんですか。学識経験者に１回だけ意見をいただくと、大きな違いはそこだけなのかどうか、説明を求めました。","respondent":"阿部経理課長","answer":"工事の評価基準は、３月の地方自治法施行令改正からすぐに着手をしまして、今回の契約のときの導入に間に合ったです。委託の場合はさまざまなものがありますので、その辺が、工事と委託の基準をつくるときの大きな違いかなと考えています。","id":"exchange-024"},{"speaker":"武内委員","kind":"質問","question":"入札するわけですから、３番のほうを検討することによって、これを出すことのほうが。もう１日やったほうがいいのではないかというお話があったんですけれども、お話を伺っている限りでは、大丈夫なのではないかなという気はしています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員長","kind":"意見","question":"今、正副委員長でも調整させていただいて、委員長としては、今、武内委員からもご意見がありましたけれども、５月に報告をいただいて、それを受けてまとめに反映をさせていくということで進めていきたいと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"阿部委員","kind":"意見","question":"委員長、副委員長のご決定でしたら、それに従います。そこの論点も、しっかり５月１３日の中では議論できるように、よろしくご配慮ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"中塚委員","kind":"意見","question":"４番目なんですけれども、議会への報告という視点が、なかなかわかりにくいかなと感じているんです。４の一番最後に、総括シートの中身も具体的に落とし込みたいところはあるけれども、そういうことを盛り込んだらどうかなと思いましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"原委員","kind":"質問・要望","question":"それが与える影響ですとか、その辺まで加味しなくてはいけませんので、これは慎重に扱っていただきたい。その辺をもう少し、ただ単純に全部出せばいいではないかということに関しては、ちょっと反対の意見もあります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"１点指摘すると、企業自身は公のものですから、隠しようがない。公の事業を担うわけですから、やっぱり大事なのかなと、ちょっと意見だけ述べします。","respondent":"福田企画部長","answer":"そのとおりだろうと思います。隠匿するとかということは毛頭考えておらないんですけれども、そのような表現につきましては、避けていただければありがたく思います。","id":"exchange-030"},{"speaker":"原委員","kind":"質問・要望","question":"私どもの仕事というのは、やっぱり監査という意味合いなので、今のご意見は非常にわかりますので、文言的には、当然に行政側から出てくる。我々は、それを区民にわかりやすく普通の言葉で説明をしていかなくてはいけませんので、そこの形になるようなご協力をいただきたいということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のは、その資料をもっと改善していただきたいという話なのかなと。それについての意見もありますけれども、私は、そういうふうに感じます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"原委員","kind":"質問","question":"ですから、いろいろな、こういう委員会ででも答弁をされればいいのではないかなと。その辺も、委員長、副委員長でお考えを入れていただくと助かります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"ですから、議会の報告のためにやれというのは、ちょっと流れが違うのではないかなと考えております。私、中塚委員のおっしゃったところまで踏み込むのはちょっと違うのではないかなというふうに判断した上で、この案を検討しています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"中塚委員","kind":"意見","question":"指定管理者の実態というのが一体どうなっているのか、今まで委員会で、私は述べさせていただいたんです。もう１回言いますと、議会が指定管理者の実態を把握できるものに改善すること」、そういう形で盛り込んだらいかがかなと思ったんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"阿部委員","kind":"質問","question":"積極的に情報公開するように、区側として積極的に促していくということもあっていいのではないかというつもりで、こちらに書かせていただいたんです。その辺を、どちらでもいいんですけれども、ご意見を伺えれば。","respondent":"福田企画部長","answer":"自己情報をできるだけ開示をする、とりわけご議決を仰ぐわけでありますから、そのご議決に耐えられるような自己情報をきちんと積極的に開示をすると。これは原則だろうと考えていますし、そのことを、さらに指定管理者に働きかけてまいりたいと思っています。","id":"exchange-036"},{"speaker":"武内委員","kind":"意見","question":"４番だけ個別に議会側、４番の中で、私どもは思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"阿部委員","kind":"質問","question":"それ以前の大前提としてなのか、そういったことをあえて明文化しておいたほうがいいのではないかと思うのですが、いかがでしょうか。それとも、いや、品川区は随意契約中心でやるんだという強い意思があってやっていることなのか、ちょっとその辺をお伺いできればと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"それをあえて書くかどうかという、むしろ判断の問題になるかと思いますが、どうでしょうか。ただ、役所の契約は入札がベースということは、これはもう基本の「き」なので、どうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"その言葉をこのまま残してしまっていいのか、どうか、ちょっと非常に疑問に思うんです。それは委員長に仕切ってもらいますけれどもとの意見を述べました。","respondent":"阿部経理課長","answer":"委員のお言葉で、随意契約中心ということですけれども、随意契約は限られた場合にできるですので、随意契約を中心にやっているというわけではございません。","id":"exchange-040"},{"speaker":"武内委員","kind":"意見","question":"前文の記書きの４行上に、こういう形でありますが、ここに含まれるのかなと。それをこの１年かけて、あえて書くかどうかというのは、なかなかちょっと疑問かなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"阿部委員","kind":"意見","question":"ただ、そういう書き方をすると、逆に大仰になってしまうので、「記」より下で１項目あってもいいのかなと考えております。より流れのよいように後でできると思いますので、むしろ入れていただけるかどうかというところで、ご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"原委員","kind":"質問","question":"品川区は行政ですから、「もう少し活発な自由な競争」とか、その程度の言葉ぐらいでいいのではないかなという感触を持っております。ですから、正副委員長にお任せをしたいと、私は思っております。","respondent":"鈴木（ひ）委員長","answer":"この提言というのは、この委員会として、全会で一致できる中身ということで、正副委員長で検討させていただいた結果の文言なんですね。あえて入れなくもいいのではないかというご意見もありましたので、そういうところで仕切らせていただきたいと思います。","id":"exchange-043"},{"speaker":"阿部委員","kind":"質問","question":"ですから、最終的に書くかどうかは別として、ちょっと違うのではないかと思います。どう言ったらいいんですか、今のところはまだ出ていないと思いますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問","question":"さっき、原委員のほうからあった、「より活発な自由な競争」というのがどういう意味合いだったのかなと思います。そういう意味では、どういう意味なのか、もしよければ教えていただけたらと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"原委員","kind":"質問","question":"ですから、制度的に随意契約なのか、一般競争入札なのか、その辺ということよりも、公明正大にという意味合いで、先ほど、申し上げたです。もう少し活発な入札制度があったらいいということを、正副委員長で言葉は考えていただけると助かるなというのが、私の意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問","question":"最後にこれをつけたらどうかということに対するご意見の中で、私たち、それぞれの委員が目にするわけですよね。そちらに対する注文ですから、そういう意味で、私は必要なのかという思いで述べさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"ですから、私の段階では、ちょっとそこら辺に疑問があるのが現状です。ですから、急に皆さんでやっている中ですから、また文言が全然変わってくると思うんです。","respondent":"市岡総務部長","answer":"考え方だけではなくて、法律上も、競争入札が原則であるということは共通の認識があろうかと思います。我々の認識としては、私どもの立場を、ちょっとご説明させていただきました。","id":"exchange-048"},{"speaker":"阿部委員","kind":"質問・要望","question":"ぜひ、他の自治体がどうこうということではなくて、品川区として不断に意識していただきたいという思いです。不断に見直しの努力を行っていくべきだと、ぜひ明記していただきたいという、正副委員長にお任せいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"提案","question":"どうかわってくるのかなというところにおいて、このような文言をというところでご提案をいただいたほうが、よろしいのではないか。ここで、どういう具体的なものなのかというものを示していただいて、論議をしたほうがいいのではないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"ですからまだ、もう１回正副委員長でまとめるんでしたら、ちょっとしますけれども。ご意見があれば、ほかの方に聞いたほうがいいと思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"武内委員","kind":"意見","question":"やっぱり総括シート１枚でわかるというのは、こういう表現でいってもらいたいと、重ねてお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"中塚委員","kind":"提案","question":"そこまでは提案しているわけではなくて、ぜひ、反映していただきたいと思っています。この文言を追加してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"山内委員","kind":"質問・要望","question":"４番の最後のほうに、そこまで具体的なことを言ってしまうときりがないと思うんです。ですから、やはり、こういう形での表現というものが一番的確であると思うので、私は、これで、あとは正副委員長で決めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"中塚委員","kind":"意見","question":"もし、よろしければ、ほかの会派の方々のご意見が聞けたらなと。終わりにしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"ですから、さらにまた充実を図っていくという言葉以上、言いようがないのではないかなという気はするんです。ですから、この４項目をまとめた中でご理解をいただければ、まとめさせていただければと思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"}]},{"id":"topic-03","title":"行財政改革特別委員会を再開いたします。 次に、財政（歳入）に関すること","agenda":"行財政改革特別委員会を再開いたします。 次に、財政（歳入）に関すること","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"４番のところで、ちょっと足しておいたほうがいいのではないかなと思うんですけれども、皆様のご意見はいかがでしょうか。私はあったほうがいいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"阿部委員","kind":"意見","question":"どうしても区内在住者の家計みたいなイメージがあるんですけれども、そういう意味では、少々言葉のニュアンスとして無理があるかなと。むしろ、経済の停滞を招かないような形の範囲でのということであれば、というニュアンスをちょっと加えたほうがいいのではないかなと思いましたとの意見を述べまし…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"都に来る方にホテル税ということで１万円以上の場合に、１００円か２００円かけているけれども、そういうつもりです。言葉としてちょっとどこまで理解されたかわからなかったので、まださっと説明を聞いただけなので、今のところには納得はいかないところですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"原委員","kind":"質問","question":"ですから行政を含めて向上していきたいという意味合いを含めて、基本的、個人的には賛成です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"武内委員","kind":"意見","question":"産業とか入れずに、抜いてしまうということも、一つの考えかなと。正副委員長にお任せしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"質問の中でも、拡充をしていく意味も含められているというか、その思いがこもっているところで受けとめていただきたいなと思います。これは意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"人々の暮らしの懐に手を突っ込んで、新たな課税をするというのは絶対に認められません。それだけは、はっきりと言わせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"阿部委員","kind":"質問","question":"やはり区内業者ではないというんでしょうか、そんなに簡単に、例えばホテルだからいいんだということではないです。間接的に区民利益に反するということもあると思いますので、そこら辺は、ほんとうに慎重に議論が必要なところだと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"ですから、何かそういうことも考えられないかなという意味で、検討しておいてもらいたいと。こういう形でどうかなということで、一応、こういう原案にしてあるんです。","respondent":"鈴木（ひ）委員長","answer":"ここはあくまでも慎重に、「引き続き研究するよう努めること」という文言になっておりますので、一致して出せたらと思っているところです。","id":"exchange-065"},{"speaker":"武内委員","kind":"意見","question":"９月ぐらいまで考えますという話があったんですけれども、区民生活だけ入れてしまうと、というような意味です。この文言を軽視しているということではないので、これは先ほど言ったように、正副委員長にお任せしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/817079?Template=document&Id=5836#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":39917,"voices":127}},{"id":"h20-20080418-16","meetingId":"h20-cm04","date":"2008年4月18日","dateIso":"2008-04-18","committee":"街づくり特別委員会","time":"午後１時０３分～午後３時２５分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"八潮まちづくり検討委員会からの提言","agenda":"八潮まちづくり検討委員会からの提言","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そこに議会側の主体的な運営の中で入っていくのかどうかということは、関係部局との関係でどういうふうになっていくのか、行政の部分の考え方を教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"内容につきましてはいろいろな連絡調整をこの間も進めてきておりますので、この辺を１つベースにいたしまして、今後の検討をさらに進めていくということになろうかと思います。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"スポーツなんかに関しては区内全体を考えると、それはそれなりの団体があって、全体を見ながら呼びかけるというところがありますよね。そういう関係をどういうふうに調整していくのかなというところがあるんですが、そこのところの調整の仕方、考え方はいかがか尋ねました。","respondent":"日下部企画財政課長","answer":"今回の八潮の検討会は、そういう意味では地域の思いがこういう形で取りまとめられたというふうに私どもは受けとめてあります。いずれにしましても、それを我々行政が受けとめて、その辺は今後また検討の中で十分に私どもは留意をしてまいりたいと考えております。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひいろいろ調整を図っていただきたいんですが、「わがまち」という形で非常に熱心にいろいろ考えられて、こういうふうにしようと思っているので。そういった意味で、将来のイメージを持つといいなと思っていますので、そこは意見としてお願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"資料の１枚めくったところの、今度は提言も出たということなんですけれども、今後の検討委員会の活動の方向性について今つかんでいることをお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"いわば集中的に検討いただいたわけでありますけれども、せっかくこういう形で検討委員会がスタートしたわけでありますので、今後もいろいろな地域の意見交換をしたりという形で進めていきたいとおっしゃっておりました。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"再生のために「学」とこれからどのようなかかわりを持っていくのか、もし、ご見解があったら教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"この間、ただ、いろいろな形でのそういう大学とかも一応入っての再生・活性化に向けた検討・研究がいろいろな形で進められておりますので。ただ、特にそういう大学が直接的にかかわってきているというような状況ではございませんので…","id":"exchange-005"},{"speaker":"石田委員","kind":"質問・要望","question":"そのときに、これはもちろんご意見を伺いながらやっていくんだろうけれども、じゃあ、他の地域からの集客をどうするんだ。いろいろお話を伺うと、どうにも地域としては議論ができないということで、それもやっぱり無理がある。","respondent":"日下部企画財政課長","answer":"そうすると、じゃあ、高齢化に対応した形で、例えば施設をどうやって整備したらいいかと、どうしてもそういう面がかなり中心になってあります。今後とも地元のほうともいろいろな意見の調整の場を持っていきたいと考えていますので…","id":"exchange-006"},{"speaker":"石田委員","kind":"質問","question":"一緒に質問すればよかったんだけど、皆さんが思っているなら、それをお聞きしたい。","respondent":"日下部企画財政課長","answer":"それがもとになって、自治会が中心になってこういう検討会も組織された。夜とか、自分の時間を割いて一生懸命検討されたということに対しまして、ことにこれは区としてもしっかりと受けとめていかなければならないと。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、まちをどういうふうにつくってきたか、きちんとした体制で対応していっていただきたいということを改めてお願いしたいと思います。進めていけないと思いますので、その辺についてはどういうふうに考えているかということだけ１点伺っておきたいと思います。","respondent":"日下部企画財政課長","answer":"それから検討会とも密接な連携を図って、今後の八潮の活性化に向けて私ども行政もしっかり努力をしていきたいと考えておりますし、積極的に進めていきたいと考えています。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"意見の調整もそうなんですけれども、例えば、私も以前、一般質問で紹介させていただきましたけど、専門家の講習会の設定だとか、そういうことも含めて、ぜひ支援をしていくべきだと思いますので、その点については改めて要望としてお伝えして、時間の関係もありますので終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]},{"id":"topic-02","title":"特定事件調査の新・水とみどりのネットワーク構想","agenda":"特定事件調査の新・水とみどりのネットワーク構想","exchanges":[{"speaker":"南委員","kind":"確認","question":"今日は４０分に視察ということなので、行政としては２回のパブコメをやって、いろいろな形で区民から意見を聴取している。１４日のときは最終案として提示されるということですから、その辺で委員長に確認したいんですけど、４０分に視察に出ちゃいますよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"終わってから、また再開してやる予定なんですか。なかなかちょっと意見を……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"要するに、いろいろな緑あるいは水、こういうものができるだけ面積を多くとることが大事なんだということなんですか。私はそういうふうに理解したんですけど、本当はどうなんか尋ねました。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"ある程度目標の数値を示す中で、今後も取り組んでまいりたいということで、この前ご説明したところです。そう言う点で、今回新たにみどり率というとらえ方をしていきたいと考えたところです。 若干補足しますけれども、全体の流れの中のみどり率はやはりきちんと出していきたいと思っています。加えまして、今までカウントしてきた緑被率については当然…","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"単純に水辺、沼にしても、池にしても、水を入れるというのが、みどり率という言葉の関係でよくわからないんです。そういうふうに聞いたんですけれども、いろいろな緑があるのはそれは当然知っていますけれども、その辺を説明を求めました。","respondent":"岩田まちづくり事業部長","answer":"こういった自然的なものがどのぐらいのボリュームがあるのかというのが考え方で、今、流れが来ている。こういうことです。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"そういう緑が与える人間生活への影響ということを考えたときに、もっと緑を増やすという方向で、このみどり率というのを考えていくのかどうか。そういう方向を目指しているというふうには、なかなか今までの説明ではちょっととらえられなかったので、その辺についてはどうなんか尋ねました。","respondent":"松代管理工事課長、家壽田下水道河川課長","answer":"そういう中では、国も都も進めているようなこのみどり率というとらえ方でやっていますので、国や都の中でも品川区はどうなのか。その品川区の自分たちの身近なところの緑はどうなっているのかというようなところをお示しできるようなも… 総体としてみどり率を上げていくということは、やはりこれは自然界に近くするという意味では、大変重要なことだと私なんかは考えています。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"一定の新しい建物を計画するまでの間の裸地にしか過ぎないんじゃないかと、いい悪いは別として、そういうふうに思うんです。ですから、やっぱり緑をどういうふうに増やしていくかという、意見として。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"今後もわかるように区民のほうに同時に紹介されるのかということを確認したいのと、現在の緑被率とみどり率というのを教えてほしいと求めました。中間発表と合わせて２回やったということなんですけれども、今回は２０日間にしたという考え方を、担当部局のほうからその考えをお伺いしたいと。","respondent":"松代管理工事課長","answer":"区のホームページにも掲載をしていく予定です。今回の２回のパブリックコメントもホームページで掲載をしてお知らせをしましたが、順次更新等を進めて、広く周知を図っていきたいと考えております。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"１点だけいいですか。先ほどのそのやりがいで顕彰するのも１つだろうけど、そういうことも含めて、これをやっていくなら考えていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"このパブコメですけれども、この７通というのはどこから来た７通なのかということと、それは全部どういう方から得られたものなのか。パブコメのレベルとしてはどういうふうに考えたらいいのかということで、お願いします。","respondent":"松代管理工事課長","answer":"まだ始めて２回目、少ないと言うのかもしれませんけれども、現状としてはこんなような形になっております。今後もご意見を聞く、または周知をする方法等については今後も研究してまいりたいと、このように思っています。","id":"exchange-018"},{"speaker":"西本委員","kind":"意見","question":"告知のほうのやり方はどういう形に、パブリックコメントでこういうのをくださいという投げ方はどういう形にされていますかとの意見を述べました。","respondent":"松代管理工事課長","answer":"前回のときにもご説明しましたが、広報紙にこのようなカラー刷りで入れ、お示しをしております。これが基本でございまして、次に、ホームページで原案の内容等をすべてご覧いただけるような形で掲載をしております。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"それが今回は７通という、そこの検証もいろいろ考えていただきたいなと思っているので、そこのところは企画のほうもいろいろと検討していただきたいなと思うんです。","respondent":"福田企画部長、松代管理工事課長","answer":"もう１つはそのパブリックコメントの目的物を広く宣伝する。こういう目的がありますので、これらのことを勘案しながら、ご意見の趣旨を十分生かしてまいりたいと思います。 最後に、品川南ふ頭公園が３月の末に完成し、４月１日からオープンをしています。それをぜひご覧いただければということでご案内申し上げたいと思います。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/183026?Template=document&Id=6362#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":18989,"voices":64}},{"id":"h20-20080512-6","meetingId":"h20-cm05","date":"2008年5月12日","dateIso":"2008-05-12","committee":"区民委員会","time":"午後１時０４分～午後３時４４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件整理しています。","topics":[{"id":"topic-01","title":"の１番、報告事項","agenda":"の１番、報告事項","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"これは既に設置されているのかどうかということと、こういう場所というのはすごく地域の方も望んでいると思うのですばらしい活動じゃないかなと思いますけれど、今回設置するに当たってどんな要望があったのかというところを伺いたいと思います。","respondent":"中山地域活動課長","answer":"２点目のご要望というのは、これは掘り起こしも含めてスペースを設けていくという、ある意味では積極的な姿勢の中で考えたものです。やはり申し上げたような地域の活動の活性化、そういうものについて団体の声を聞きながら…","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"特に政治活動というのは保障されているわけですから、とりわけそこで対象外とする根拠というのか、何か法律とかあるんでしたっけ。集会所の法律とかあるのかなとちょっと心配になってきまして。","respondent":"中山地域活動課長","answer":"集会所の利用の規定ですと、そういう意味では必ずしも政治・宗教活動が最初から利用できないということではないです。ですから、その中で実際のご要望であるとか運用する中で、当初から政治・宗教活動についてＰＲする趣旨ではございませんので除いてあるです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"それがこの掲示板にふさわしいかどうか、対象内か対象外かという判断ですとか、何かお考えがおありになるのかなというのが聞きたいんですけれど。今のお話ですと、そこら辺の具体的な、そういう要望があったときの受け付けてからの運用方法をもう少し詳しく教えてほしいと求めました。","respondent":"中山地域活動課長","answer":"掲示対象団体を登録するという考えはありません。基本的には例えば同じ時期に出ているからといって、貼れるにもかかわらずどちらかを除いてしまうというようなことは考えておりません。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"具体的な、そういった掲示を希望して窓口に申し出た後の流れを教えていただきたいのと、そういうところを判断する方というのはだれになるのか聞きたいと思います。","respondent":"中山地域活動課長","answer":"現在ではまだ把握していない部分も含めての掘り起こしにもつながるというふうにも考えておりますので、ある意味では望ましい状況だと考えています。その段階で、冒頭に申し上げたとおり…","id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問","question":"設置形態のところだけ伺いたいと思います。その人にしか目に触れないのと、あるいはふれあい掲示板のように簡易なボードで、加工することを検討できるかどうかだけ伺いたいと思います。","respondent":"中山地域活動課長","answer":"間もなく移転を考えているものに一定のコストをかけて構造物を設置するのがいいのかというようなケースも含めてあります。例えば移転だとか施設の改修等にあわせて、可能性があればできる限りいつでも見られるような場所に張れる可能性は探っていきたいと考えております。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"意見","question":"すぐじゃなくても、またやり方とかいろいろな問題もあると思うし、期間の拘束もあるから。活動の紹介みたいなものも何か入れられたら検討できないかなとの意見を述べました。","respondent":"中山地域活動課長","answer":"ボードの進捗も見ながら、ご質問にもありましたけれどちょっと検討の課題とさせていただきたいと思います。今後こういうことも含めて、なるべく地域センターのホームページそのものを見れば幅広い情報がわかるような工夫は、考えていきたいと考えています。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"意見","question":"どの程度の人が、利用者はあるけれど一般的にどの程度見られるかなというのはこれからの課題だと思うので。やり方等、さっき言った人の問題だとか大変だと思うのでその辺よく検討してもらって、何かいい方法をつくってもらえればと思いますねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"川西委員長","kind":"質問","question":"私から質問します。例の1)の「ふれあい掲示板に載っていないもの」というのはどういう意味かということを、先に１つ伺います。","respondent":"中山地域活動課長","answer":"ふれあい掲示板はもともと区の広報情報として設置してまいったわけですが、ポスター等整理する中で、一定の余裕のあるスペースの中では。内容を切り分ける、対象を切り分けるという意味ではございません。","id":"exchange-008"},{"speaker":"山路委員","kind":"質問・要望","question":"特に新しい訓練項目があったら教えていただきたいことと、参集訓練について、職員の参加率は非常にいいんでしょうか。その辺の実態について教えてほしいと求めました。","respondent":"斉藤防災安全担当課長","answer":"６月のこの時期には秋に参加しますと言っているんですけれど、必ずしも１００％というわけにはまいらないと思います。ただいずれにしても、ほぼ９０％に近い数字の参加率ということでは把握をしております。","id":"exchange-009"},{"speaker":"山路委員","kind":"質問","question":"それで関係者の人がほとんど来ている、毎年来ていらっしゃるんですけれど、一般区民の方というのは呼びかけたりはしないんですか。もっと多くの人が知識を得て、いざというときに役に立つんじゃないかと思うんですけれど、その辺はどのように考えていらっしゃるのか。","respondent":"斉藤防災安全担当課長","answer":"したがいまして、あそこに訓練に伴ういろいろな想定的なものをつくったり、消防車両的なものがどんどん入ってまいります。今のご指摘の話につきましては、今後は消防署のほうとも相談しながら、そのような形で進めていきたいと考えております。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"大田区内の各消防署の職員がいらっしゃるということですけれども、これは毎年なんですか。聞かせてください。","respondent":"斉藤防災安全担当課長","answer":"したがって品川区で１年おきにこの規模の訓練だという形になっております。したがいまして、大田区で実施されるときには当然、品川区内の消防署から応援隊という形で訓練に参加しています。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"提案","question":"今後のいろいろな形の中で、あまり無理に来賓の紹介ということを考えなくても、ほかの部分でも考えていかれるんじゃないかなと思いますので。そういう提案があったということもまた踏まえて、ほかの分にもうまく活用してもらえばと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"安藤委員","kind":"意見","question":"テーマを絞るにしても、重点支援ということで国とか都の考え方もあると思うんですけれど、そういったこともかかわりがあったのかなと。今回の事業は国とか都からの補助みたいなものはあるのかなということを聞きたいと思いますとの意見を述べました。","respondent":"金子産業振興課長","answer":"この重点化のテーマのところでご説明申し上げたところの疑問ということですけれども、やはり創業支援施設、かなり充足率が高いものであります。聞いているところによれば東京都も、今後こういう創業支援の施設に関して補助を考えているということは、情報としてはつかんでありま…","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"この施設自体が集客というよりもビジネスの起業を支援する施設ということですから、ちょっとそこら辺がよくつながりがわからないと思うんですけれど。そこら辺の経緯を伺いたかったもので、もう一度お伺いしたいと思います。","respondent":"金子産業振興課長","answer":"こういったことが要素として考えてきたことだろうと考えています。これこれこういう理由で子育てにしようというのは、委員会の中で理由として明示されたことがないので、こちらとしてはそういうふうに推測しています。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"この２階、ちょっとわからなかったのでお伺いしたいのと、子育てビジネスというのは要するに保育園の運営とかになるわけですか。そこら辺もちょっとわからないので。","respondent":"金子産業振興課長","answer":"創業支援の中では例えば子どもをここに預けて、ここで預けることによってさまざまな創業に関しての支援もしていけるだろうと考えているところです。そういう意味では保育施設そのものの機能…","id":"exchange-015"},{"speaker":"稲川委員","kind":"質問","question":"平成２０年度に基本設計・実施設計とあるんですけれど、実際３４ページにいろいろ出ているのは、どうなのかなと。これからスタートで、もう既にある程度決まっているのかどうかお伺いします。","respondent":"金子産業振興課長","answer":"私どもとしましては、商業・サービス系についての初めての創業支援施設と考えておりますので、拠点にしていこうと考えているところです。ですので、他地区については今後の検討課題になろうかと考えているところです。","id":"exchange-016"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういう意味では何か１つ事をやろう、行事をしようとしたとき、こういった会議施設というのはすごく求められていると思いまして。施設外も含めて検討の中ではどのように触れられたのか、あるいは今後という点で説明があればお願いします。","respondent":"金子産業振興課長","answer":"検討委員会の議論の中では、駐輪場は必要だろうという話はありましたけれども、どのぐらい必要かという具体的なところまでは出ておりません。ここの駐輪場についてはあくまでも施設に出入りする関係の方の最低限だけを確保するというふうに考えていくものと考えています。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問・要望","question":"１階のチャレンジショップなのか、もしくは一般の人が４階、５階を使うという意味なのかをお伺いしたいのと。ショップ系が多いように伺えるんですが、こういう行政でこういう例があるとか、何かあれば教えてほしいと思います。","respondent":"金子産業振興課長","answer":"そういう意味ではこの集会室についてもかなり利用率が見込まれるところ等々、この施設については。もう１つ、私どもも見にまいりましたが、機能を集大成していくというふうにお考えいただくのが早いかなと思います。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問","question":"たしか大阪だったでしょうか、障害者の方への創業とか就業とかは別問題で、創業というとすごく幅が広いと思うんです。講習会ですとかいろいろ参加できて、「よし、一丁やってみよう」というような意気込みを持たせられるような施設になってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"短時間お子さんを預かるような機能は、このスペースでは無理かなと思うんですけれど、その辺の考え方があるのかどうか。その３点を説明を求めました。","respondent":"金子産業振興課長","answer":"もちろんこの創業支援の相談であるとか情報提供であるとか、能力が高くてこの施設に向かれる方を探していきたいと考えているところです。買い物に来た方たちの預かりとかさまざまなことは、これからの検討、実際の運営に当たっての検討すべき課題かなと考えています。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そこら辺でどういう、指導のほうでよく見ていきながら……。ここのシステム、施設の運営主体になるべき団体は、主体はどこが運営していくと考えたらいいんか尋ねました。","respondent":"金子産業振興課長","answer":"創業支援に関しての非常に知識の高い方から、そういった運営について任せられる団体というのも、この２年間で区としては探す必要があると考えているところです。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今の説明はわかりました。これから２年、まずこれが成功するような形でやっていってもらいたいというか、その辺よく検討をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"どういったところで活躍をされている方なのかということと、その辺どのようにこのメンバーを選ばれたのかお聞きしたいのと。ちょっとその辺を説明を求めました。","respondent":"金子産業振興課長","answer":"創業に関しても非常に見識の高い方で、東京商工会議所の品川支部でも幾つかのテーマについて検討あるいは研究をお願いしていたとお聞きしています。立正大学のほうでは五反田商店街と連携して学生のさまざまな勉強等々も実施しているので…","id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そういうことがあったのかどうかという点と、先ほどの質問をちょっと聞き漏らしちゃったんですが、もう１回聞かせてほしいと求めました。","respondent":"金子産業振興課長","answer":"委員会の成果というお話かもしれませんけれども、これについてはこの報告書をもって今までの検討の成果であるとご理解いただければと考えています。今後２年間の中で鋭意検討していきたいと考えているところです。","id":"exchange-024"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今年度は６００万円でしたっけ、予算がついていたと思うんですけれど、今後の建設費用とかその辺はどういうふうに増えていくのか。わかっている部分で説明を求めました。","respondent":"金子産業振興課長","answer":"今年度で言いますと、平成２０年度に関しましては基本設計・実施設計あわせて約２,０００万円の予算を計上しています。さまざまな付帯設備等々でどれぐらいになるかというのはまだ計算ができておりませんので、これは平成２１年度予算のところで計上するものです。","id":"exchange-025"},{"speaker":"飯沼副委員長","kind":"意見","question":"今回は商業系ということですけれども、今までの西大井の創業支援センターの取り組みとか、天王洲のところは二次ということで、これは３つ目と思っていますけれども、今までにおいての総括というものはどこかでされて何か出ているのかどうか、その辺も聞かせていただいたいとの意見を述べました。","respondent":"金子産業振興課長","answer":"ご指摘のとおり西大井と天王洲で創業支援センター施設を運営してまいりましたので、今回の創業支援施設におきましては、今までの経験を踏まえながらも違いというものを充分に検討していって今後の運営に生かしたいと思っているのが。","id":"exchange-026"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今回をきっかけとして以前のものを読んだりもしたんですけれど、従前のところも何らかの形で目に見えるような報告をぜひしてほしいと求めました。これは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"２点目の件なんですけれど、国が短縮したという考え方は区としてどうとらえているのかということと、証券税制の政策転換の内容をちょっとご説明いただきたいんですけれど。","respondent":"武内税務課長","answer":"その他につきましては今後２定あるいは３定でご審議いただく予定ですけれども、ベンチャー企業のさらなる投資を目指すということで行われております。今回は、所得税絡みのほうでは逆に取得した時点で寄付金控除と同じような扱いをするというような形が新規につくられたというふ…","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"なかなか難しい話なんですけれども。２３区すべて共通で行っているということですけれども、独自の考え方を持って行うものなのか、区はこうしたいという考え方があるんじゃないか尋ねました。","respondent":"武内税務課長","answer":"ご案内のとおり地方税法は国で定めているものでありまして、この地方税法の枠組みの中で品川区の条例というのも制定されております。一部法定外の新税の設置とかいうものについてはそれぞれの自治体にゆだねられて、特段するとかできますけれども、ご理解いただければと思います。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１番の住宅借入金特別税額控除申告書の提出期限の拡張ですけれど、この対象者としてはどのぐらいを見込まれるのか。これは基本的に３月までにやった人と、３月以降やらなかった人たちも含めて、その辺は区として数字をつかめているんか尋ねました。","respondent":"武内税務課長","answer":"２,６５１人の方から申請を受付しております。数百人の方は漏れているのではないかとこちらでは予定しておりまして、ご本人にご連絡を入れる、手紙を郵送して申請を促すという形をとる予定です。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"意見","question":"その人も新たにやらなきゃいけなかったんですよね。そういう方が今年出てきたという判断でいいわけですねとの意見を述べました。","respondent":"武内税務課長","answer":"そうしますとローン控除を本当はもっと引けるという方は、年末調整でそういう金額が入力されるようになっています。１月１日現在品川区に住民登録がある方については品川区のほうで課税をしますので、品川区のほうに確定申告をしていただくというのが原則です。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"確認","question":"住宅ローンの関係で所得税がゼロになっている人は申告したほうがいいんじゃないですかというような、そういう呼びかけというのはしているんですか。その確認だけ。","respondent":"武内税務課長","answer":"もちろん広報またはホームページ等で何回も周知しておりまして、先ほど説明したとおり６月の賦課決定後、７月ぐらいに漏れている方を抽出しまして、ご連絡するという事務手続で、漏れのないようにしてまいります。","id":"exchange-032"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"少しだけ説明があったんですけれど、税源移譲の所得税と住民税の変わってきたあたりの説明をもうちょっと詳しくしていただきたいんです。この住民税にかかわってくるあたりの説明をもうちょっと詳しくしてほしいんですけれど。","respondent":"武内税務課長","answer":"そうしますと３０万円のローン控除を受ける方が、所得税から５万円引き切れなくなってしまうという形になります。１月１日現在品川区に住んでいる方については品川区のほうに確定申告、この５万円を住民税のほうから補てんしますよという、そういうシステムです。","id":"exchange-033"},{"speaker":"飯沼副委員長","kind":"質問","question":"今のご説明とすると、申告漏れした方もちゃんと通知をしてくださるということなので、不利益になるような方はいらっしゃらないと受けとめてよろしいんか尋ねました。","respondent":"武内税務課長","answer":"ご本人が申告していただかないとこちらは何ともできませんので、そういうことを知らなかったとかいうことがないように。忘れていたとか申告をしていなかったという方について、該当すればその時点で申告していただければ受付すると、そういう改正です。","id":"exchange-034"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"それを今回１年間またもとに戻すというあたり、どう理解していいのかなと。もうちょっとその中身を、どこがどう変わってここをやめたのかというところを、もうちょっと詳しく教えてほしいと求めました。","respondent":"武内税務課長","answer":"それを廃止したということについては、要するに買った時点で優遇措置をとるという制度が国の方で行われるようになったです。先に優遇措置をするのか、後に優遇措置をするのかということで考えていただいて、すべてベンチャー企業に対する住民税の優遇措置はなくなりました。","id":"exchange-035"},{"speaker":"飯沼副委員長","kind":"質問","question":"今度は先にということは、ベンチャー企業株式を取得した人に対しては、いい中身に変わったという理解でよろしいんでしょうか。質問がよくないかもしれないですけれど説明を求めました。","respondent":"武内税務課長","answer":"株というのはベンチャー企業ということで今ご説明させていただいているんですけれど、そのほか上場株というのがあるんですね。それが優遇措置として１０％に措置されているのが年内で終了という税制改正も、２定あるいは３定のほうで提案しますので、よろしくお願いいたします。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"1)のところで「参加者の交流の場の設定」、そういう方がそういう場所に来て、この交流の場というのはどういうふうになるのかと。2)で相談事業を行うことになっていますけれども、具体的にはどこになるのかなというのをまずお伺いします。","respondent":"小野区民課長","answer":"今回委託を予定しております業者では、これはこの事業者の１つの特徴ある事業なんですが、それから相性分析みたいなものもこういう中でやっていく。今度、五反田にもそういう支社を開設する予定になっているということを含め、アドバイザーから相談を受けるという形になっていま…","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"「結婚はどう考えていますか」と聞いたら、結婚なんて考えられるわけないじゃないですか」というのを聞くんですよね、生で。ですから、そういったことをぜひ考えていただきたいんですけれど、いかがか尋ねました。","respondent":"宮地区民生活事業部長","answer":"日ごろの安藤委員のお話を聞いていれば当然のことかなと思いますが、本日は結婚サポート事業の業者選定に関するご報告ですので、そういったことはまたの機会に改めましてお答えさせていただきたいと考えております。","id":"exchange-038"},{"speaker":"安藤委員","kind":"意見","question":"すごく難しい問題だと思うんですが、３番目のところで入会金の割引というふうになっちゃうと、確かに安く具体的にパートナーを紹介していただくのが核と言えば核なのですごく大事なところなんですが、ここら辺がすごく難しいところだなと考えちゃうんですけれどとの意見を述べました。","respondent":"小野区民課長","answer":"最後のパートナー紹介事業ですね。これに参加するというか紹介支援を受けて企業の提供する会員になるか、今回３つ目の事業として実施をすることにしているものです。","id":"exchange-039"},{"speaker":"稲川委員","kind":"質問","question":"５番の周知方法で「広報しながわ、ホームページ、窓口用チラシ」と書いてあるんですが、委託業者は株式会社オーネットと書いてあるんですが、そのオーネットの名前というのはそういった窓口のチラシとかそういうところにも出てくるんか尋ねました。","respondent":"小野区民課長","answer":"これは最後のパートナー紹介支援事業も入ってまいりますので、チラシの中に、これはオーネットの宣伝をするわけではございませんので、大きく書くということではないかと思いますけれども、必要な部分に入ってくると考えております。","id":"exchange-040"},{"speaker":"稲川委員","kind":"質問","question":"「私たちにも何かないのか」という話になったとき、その苦情対応とかいうのもちゃんと、今後窓口はつくるんですか。先ほどから話がある「入会金の割引等の特典」と書いてあるんですが、実際にどのぐらいお金がかかるんか尋ねました。","respondent":"小野区民課長","answer":"苦情の対応ですけれども、当然企業のほうにいく分についてはそこで対応するということですけれども、区にきたものについてはきちっとお答えする。ただセミナーの中で先ほどちょっとご説明をしましたように、食事…","id":"exchange-041"},{"speaker":"安藤委員","kind":"確認","question":"特定健診ということ自体も、今までの普通の健診からメタボかどうかということで、どういうものなのか心配されている方も多いんですけれども。なくなった項目はないということでよろしいですかという確認と、「必要に応じ、これは前と変わらない状況なのかということをお伺いしたいと思います。","respondent":"本城国保年金課長","answer":"こちらにつきましては平成１９年度まで行っていました区民健診の項目を引き継いでいるものでございまして、なくなった項目は特にございません。「必要に応じて」というのは、今までの検査結果とかを見まして…","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"先ほど申し上げた７５歳以上の方なんですが、７５歳以上の方々の後期高齢者健康診査というものがちらっとこの資料にも書いていますけれども。今年実施される内容だと、来年以降の見通しというのはどういうふうになっているんか尋ねました。","respondent":"本城国保年金課長","answer":"今回ご説明させていただきました特定健診につきましては、４０歳から７４歳までの国保の対象の方の健診です。７５歳以上の方についてはいわゆる後期高齢者での健診ということでございまして、また別枠となっております。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"おれ７５歳以上だけど、おれはどうなっちゃうんだ」という心配が当然あると思うので、何とか心配を払拭する必要はあると思うんですけれど。このご案内を見ると何か全然わからない感じになっているので、それはやはり説明をされていく必要があると思うんですが、いかがか尋ねました。","respondent":"本城国保年金課長","answer":"今回の健診については各医療保険者に分かれての実施ということになりますので、全体像がわかりづらいとご本人はさらにわかりづらいということで、今回あわせてパンフレットを同封させていただきまして、各健診の全体像がわかるようにということで同封させていただいたところです。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際問題、主体が違いますけれどもそれは当然つかむべきだと思いますけれども、そこはつかんでいる範囲でいいのでお伺いしたいのと。今回の特定保健指導の中身とかかる費用ですとか、そういったことで今わかる範囲でいいんですけれど、教えてほしいと求めました。","respondent":"本城国保年金課長","answer":"７５歳以上の後期高齢者につきましてはちょっと所管が違うんですが、伺っている範囲では６月から実施予定だと伺っているところです。保健指導の実施主体といたしましては、区から事業者に委託して、そこが中心となって実施する予定になっているところです。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"同居している７５歳以上の方からすると「おれはどうなっちゃうんだ」というところに対する説明が全然ないですし、もう少し、そういうことを考えると。ですから、問い合わせや苦情に対してどのように対応しようと考えているのか。","respondent":"本城国保年金課長","answer":"今回、特定健診としても初めてのことですので、今まで以上にＰＲしていかなければいけないと考えています。実際、４月からケーブルテレビ品川を活用して、可能な限り利用者にとってわかりやすいやり方でお知らせしたいと考えているところです。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"意見","question":"じっくりもう１回見直したんだけど、特定保健指導という言葉が出てきて、一般の区民の方から聞かれました。それは後ろのいろいろな紙の中に、この白いがん検診のご案内にも、逆にここにはもう特定健診のことは出ていないから、理解できなかったみたいねとの意見を述べました。","respondent":"本城国保年金課長","answer":"無料ということを明示していなかったと思うんですね。今お配りしたものの中で……。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問","question":"受診券の中を見て、受診した医療機関で約１週間後に血液検査等の結果を聞くことができますと。何か異常があったとき、受診機関から直接２カ月もたたないうちにこういうところが問題がありますよというのは出ないものなんか尋ねました。","respondent":"本城国保年金課長","answer":"きちんとしたご通知書ということで品川区のほうから受診者の方にお伝えするのが２カ月後ということで、従来同様１週間程度後に検査結果が出次第、ご本人様にお伝えするような形です。","id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"質問","question":"すると、「聞くことができます」というのは、本人が聞きなさいよという雰囲気に見えるじゃないですか。答えはわかりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"渡部委員","kind":"質問","question":"やはりこれが着きましていろいろな質問をもらったのが、治療が必要な人とかいう分類って、だれが決めるんですかね。あわせて教えていただきますか。","respondent":"本城国保年金課長","answer":"これにつきましては２カ月後に区のほうからお知らせをするときに、詳しい内容について改めてご通知するところです。だれが判定するかという問いにつきましては、データに基づいた判定ということになっているところです。","id":"exchange-050"},{"speaker":"渡部委員","kind":"質問","question":"だけれどそれとは別立てでデータが見られるわけですから、もしくは治療を始めなさいよという連絡が来てしまうのかどうなのか。それだけもう１回教えてほしいです。","respondent":"本城国保年金課長","answer":"今回お配りさせていただきましたご案内が、今までの区民健診から移行したというものでお知らせするという設定にさせていただいたものです。その後の判定につきましては、その中にどこのお医者様ということで判断したかということで、お医者様の判断を併わせて書くかたちになりま…","id":"exchange-051"},{"speaker":"飯沼副委員長","kind":"質問","question":"今回、８月までに健診の期間が定められて、もしこの期間に受けられなかった人はどういうふうになるのかというのをお伺いしたいのが１点です。特定保健指導のところもたくさんご質問が出たんですけれども、管理栄養士が対応するということなんですけれども、これってどこかに行くんか尋ねました。","respondent":"本城国保年金課長","answer":"そういう意味で前倒しになっていまして、８月までに受診していただいて、継続してその後の指導の期間につなげるです。ご通知の仕方ですが、区からデータ等に基づきまして受診結果通知というものを区からご本人様に文書でお出しするということになっています。","id":"exchange-052"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"漏れた方については対応をぜひしてほしいと求めました。もう４月になって既に決まっていると思うんですが、結局どういうような仕様というか中身で委託をしているかという中身を説明を求めました。","respondent":"本城国保年金課長","answer":"保健指導の実施受託事業者についてですが、東京都港区に本部があるところですが、そちらに委託して実施する予定です。ただ金額等最終的に、実施内容について調整しているところでございまして、今後、最終的な契約をする予定です。","id":"exchange-053"},{"speaker":"飯沼副委員長","kind":"質問","question":"保健教育センターがどういうところなのかということと、実績というのがあったら教えてください。やりとりが何回も６カ月にわたって行われるということでは、実績的にはどういうことをやっているところなのか、わかる範囲で説明を求めました。","respondent":"本城国保年金課長","answer":"実績につきましては、全国でいろいろ、特定健康診査自体は今回がもちろん初めてですが、その前段の事業で、国保ヘルスアップ事業と類似の事業がございまして、そういったところも全国的に担って、その実績も含めてあるところです。","id":"exchange-054"},{"speaker":"飯沼副委員長","kind":"質問","question":"こういった特定保健指導は新しい事業ですけれど、こういうのを受けることのできる受け皿というか企業というのは幾つかあるんですか。まあ、ここで決まったということですけれどね。","respondent":"本城国保年金課長","answer":"全国的にどれぐらいの企業が実施体制を持っているか等につきましては、ちょっと把握していないので、これ以上詳しくお話しできないんですが。今回、数社についてはプロポーザルで、提案があったです。","id":"exchange-055"},{"speaker":"飯沼副委員長","kind":"質問","question":"社保の扶養家族の受け皿というのがはっきりしていなかったような気がするんですけれども、健康診査なんですけれど。国保のところでの受け皿というのはあるんか尋ねました。","respondent":"本城国保年金課長","answer":"あくまでも各保険者対応ということになるんですが、個別的に契約するとなかなか煩瑣であるということで、今。ただ、各健康保険組合というのが基本的には実施主体ということになるわけですが、実施形態については今調整中ということで伺っているところです。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/798229?Template=document&Id=2514#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":46579,"voices":138}},{"id":"h20-20080512-7","meetingId":"h20-cm05","date":"2008年5月12日","dateIso":"2008-05-12","committee":"厚生委員会","time":"午後１時０３分～午後４時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"内容のことではないけれども、表紙に「平成２０年３月」と記載されていて、配られたのが５月ですね。なぜ議会への報告が５月なのか、４月１５日にも委員会があったのにという思いがあるんだけれども、その辺はどうか尋ねました。","respondent":"小林保育課長","answer":"実際にご配付、ご報告が遅れましたことは、お詫び申し上げたいと思います。調製等に１カ月ほど時間を要してしまったということで、印刷の上がりが４月末、お許しをいただきたいと思います。","id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"発行は４月になりました、５月になりましたという、基準の考え方が決められているのですか。今まで３月に出たものは２月いっぱい検討して、３月に発行したという印象もあるけれども、その辺はどうか尋ねました。","respondent":"小林保育課長","answer":"何月何日に施行という場合には、その日付が大きな要素になる場合もあると思います。現年度の中できちんと取りまとめ、新しい年度の４月からはきちんとその成果を周知しながら、平成２０年３月という表示にさせていただいたところです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、幼稚園教育要領も改定されているということを聞きましたけれども、これとの関係はどうなっているのか一つお聞かせほしいと求めました。具体的に現場では何がどのように変わっていくのか、どのように活用されていくのか、イメージできるような形で教えてほしいと求めました。","respondent":"小林保育課長","answer":"今後取り組みますが、保護者に対する支援の観点を明確にした等の特色が今回の改定にはありますので、てびきも調整をさせていただいたところです。子どもの状況に応じてつくっていただくという意味では…","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"具体的に保育の中身をどうするかということを、保育所保育指針が改定されて、品川区でも実践の計画の参考にしていくという考え方でいいのでしょうか。それから、具体的なところですけれども、講演会を年間４回程度実施ということですけれども、全保育者向けの講演会ということになるのか尋ねました。","respondent":"小林保育課長","answer":"年間４回程度実施というのは講演会も含めた研修で、これとは別に何か技術的な研修を行うということは、今のところ予定していません。より深める必要があるということであれば、通常の研修計画の中で別途対応していきたいと考えています。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"子どもたちにとっても大変な状況が出てこないだろうかと心配なんですけれども、その辺のところを教えてほしいと求めました。４番の専科講師の派遣で、就学を控えた区立保育園の年長児に、具体的にはどのぐらいの体制になるのかということも教えてほしいと求めました。","respondent":"小林保育課長","answer":"専科講師と保育士が子どもたちに対応していくという形ですので、子どもにしてみれば週１回程度、専科講師が来て教えてくれる。専科講師が来ないときはカリキュラムの延長線上に立って、保育士が責任を持って通常の保育、教育に対応していくという内容になっております。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国がそのようなことを出したということで、これから他でもつくられるのかもしれませんが、品川区が先進的にやっていると考えていいのでしょうか。さらにもっといい中身に変えていくという評価、改善の検証も含めて、そのようなことはどのようにされていくのかお聞かせほしいと求めました。","respondent":"小林保育課長","answer":"対応、指導上の点があれば、子どもにあわせて当然年齢ごとの着眼点も変わっていくものと思います。今後、保育教育の課程を作成することが求められていくかと思いますので、それぞれの自治体でしかるべき対応は今後検討されていくものと思います。","id":"exchange-006"},{"speaker":"宮崎副委員長","kind":"質問","question":"文部科学省のものとは違い、品川区独自ということなので、そこの点を一つ伺いたい。連動性といいますか、その辺をどのように考えているのか、位置づけはどのようになっているのか伺いたいと思います。","respondent":"小林保育課長","answer":"特に年長クラスでは学校との連携を強めて、その環境に体験的に対応していくとか、無理なくの意味です。基礎を培うという役割に立って、小学校、十分に相互理解を図っていくということが幼児教育施設と小・中学校との基本的な連携になろうと考えています。","id":"exchange-007"},{"speaker":"宮崎副委員長","kind":"質問","question":"冊子の４６ページの５歳児の４期では、かなり具体的な目標が出てきて、そうなるとかなり小中一貫との関係も出てくるのかなと思います。そうすると、言葉や文字を使ったりというのは、普通の保育士が担当してやっていくようになるのか尋ねました。","respondent":"小林保育課長","answer":"しかも、当然品川区が進めております小中一貫の流れを視野に入れて、４歳児・５歳児の位置づけを考えているという意味です。それから、ほかの分野についてはどうなのかというお尋ねですけれども、それにつきましては従前どおり保育士が対応していくです。","id":"exchange-008"},{"speaker":"宮崎副委員長","kind":"確認","question":"連続性を持っていくということで、そのようなねらいだということでいいのかどうか、もう１回確認したいと思います。しっかりした考え方がないと流れていくのではないかという気がするんですけれども、今度始めるにあたっての思いを聞いておきたいと思います。","respondent":"小林保育課長","answer":"それに対応して、ということではなくて、それは必要な時期に必要な内容を学習していけばいい。難しい漢字が書ける、読めるということではなくて、読み書きが人よりもできるということをもって幼児教育というふうには考えてはおりません。","id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"ですから、今の説明はここに書いてある内容と少し違うのではないかという思いがします。そこのところが置き去りにならないような対応をしていただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"堺委員","kind":"質問・要望","question":"いまだに児童虐待があるわけですから、未然に防ぐためにも、なお一層ありがたいという気がします。その辺はよくわかりませんが、子どもに興味をもたせるという意味からいくと、その辺のご見解を教えてほしいと求めました。","respondent":"小林保育課長","answer":"具体的に５歳でやっていることを４歳ないしは年齢に応じたという点ですけれども、３歳は３歳なりに、４歳は４歳なりの対応が十分に可能だろうと。その結果、得られたノウハウを活用して、それを背景とした指導ができるように資質の向上に引き続き努めてまいりたいと考えておりま…","id":"exchange-011"},{"speaker":"堺委員","kind":"質問・要望","question":"乳幼児期の教育では、何を大事にするべきかを真剣に考え、時代を見据えた保育・教育内容にしていく必要がありますと。ですから、大変なことがいろいろあるかもしれませんが、なお一層の取り組みを要望して終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"高橋委員","kind":"質問・要望","question":"一つ目は、３の保幼小の交流事業ですけれども、平成１９年度はモデル実施ですけれども、今年度は全園で実施されていくのでしょうか。体験というレベルでしょうか、保育園・幼稚園では小学校に行ってみるというモデル実施みたいなものはいかがでしょうかということです。","respondent":"小林保育課長","answer":"平成１９年度は交流事業をモデル実施という形で取り組みましたが、小学校は２１校が幼稚園・保育園３３園とカップリングをして実施したところです。やりたいというご回答をいただいておりますので、今までの小学校とのおつき合いといいますか経過がございまして…","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回の調査が１０年ぶりということですけれども、なぜ１０年ぶりに行ったのか、そのことを教えてほしいと求めました。それから、今回のサンプリング６,０００人の根拠を教えてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"第一期から第三期までの介護保険の基本的な区の考え方はそれほど変わっていないということで、１０年も経つということと、今回実施したものです。今後第四期介護保険事業計画を策定するときの資料として、当然この回答をもとに考えてまいりたいと、活かしていこうと考えています。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"第四期介護保険事業計画をつくって、具体的にはいつ頃までにどのような形で計画がつくられていくのか、１点教えてほしいと求めました。２人世帯、３人以上の世帯がどのぐらいあるかというのは、その辺もあわせて説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"あわせてパブリックコメントにもかけていくという流れで進めてまいりたい。それから、家族の数ですけれども、８１ページの表に出ているような数値の調査の仕方をしておりますけれども、ほかにはいたしておりません。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"９月頃に骨子をつくり始めて、１月にパブリックコメントをかけていくことになると、議会には１２月ぐらいに報告があるという感じになるのでしょうか。それから、高齢者２人世帯が何世帯いるとか、このパーセンテージから推し測る以外のところで把握されているのかどうかお聞きしたんですけれども。","respondent":"冨岡高齢福祉課長","answer":"それから、スケジュール関係ですが、委員会での報告の予定は１月の厚生委員会かあるいはその前ぐらいを予定しています。それから、８月に課題整理をしまして、それから最終的には１２月あるいは１月ぐらいに策定の部分でご審議をいただくという予定をしております。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０月に介護保険制度推進委員会に骨子案の紹介をされるということであれば、議会にもぜひお願いしたいと思います。パブリックコメントとあわせて区民に対しての説明会を開いていただきたいということを要望させていただいて終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"それから、今年度もいろいろ予算化をしているけれども、どのような方向性を出すのかということをお聞きしたいと思います。７時間ぐらいがいいということを言われているけれども、実際にはどうなのか説明を求めました。","respondent":"冨岡高齢福祉課長、倉橋品川区保健センター所長","answer":"さまざまな課題をどのように整理していくかですが、さまざまな住まい方についても、今後長期基本計画等を策定する中で検討していかなければいけない。今後は、特に引きこもりがちな高齢者の方には出てきていただくようなことも含めて… 充分な睡眠時間というのは、大変難しい問題です。今、委員がご指摘のように、７時間ぐらいが標準的な答えになるかと思いますが、もともと必要な睡眠時間というのは個人差が大きいものです。","id":"exchange-018"},{"speaker":"須藤委員","kind":"質問・要望","question":"それから、先ほどいただいた「しながわいきいきガイド」の中にある７項目が、元気でという一つの考え方だと思います。その辺を上手にやりながら、介護予防の施策を考えていかれたらと思うんですが、いかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"ただ事業を展開していく符丁というような意味ですので、今後もより参加しやすいような雰囲気づくりなり、そのようなネーミングも考えながら進めてまいりたいと考えています。","id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"質問","question":"１０年前から今回まで１０年間あるんですけれども、前回の質問との関係で大分内容は変わっているのでしょうか。要するに、普通は前回と今回の比較があるんですけれども、今回はそのような比較がないんですけれども。","respondent":"冨岡高齢福祉課長","answer":"前回と基本的には同じで、むしろ質問数が増えているところがあります。ご覧いただきますとほとんどの部分で１９９８年度と比較しておりますので、ある程度の比較がおわかりいただけるかと理解しています。","id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"質問","question":"今回は回答数の中で例えば比率１のところですと、１の回答が３５.２％、２のところが２６.３％となっています。とりわけ福田内閣も、少しこのような設問がずれているのではないかという感じがして仕方ないんですけれども、その辺の考えをお願いしたいと思います。","respondent":"冨岡高齢福祉課長","answer":"「わからない」という答えは想定していないこともありますけれども、「わからない」プラス無回答が一番多くなっているという事実もあります。そのようなことを踏まえながら、今後はサービス計画あるいは介護保険料の設定を考えていかなければいけないと理解しています。","id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"そういう意味では、調査をされるときには、設問のところももう少し配慮が必要だったのではないかと思います。ちなみに、最後のところは意見・要望が自由記入になっているんですけれども、特徴的な意見・要望はどのような内容があったのか聞きたいと思います。","respondent":"木下福祉高齢事業部長、冨岡高齢福祉課長","answer":"４９ページに戻りますけれども、７５歳以上の方になると、「保険料が高くてもサービスの充実を」という方が増えるんです。具体的なサービスの恩恵を受けている方々になると、このような声はより強くなるということも… 報告書の５０ページに傾向が出ておりまして、その部分については十分分析しながら、今後介護保険事業計画改定に向けてまいりたいと考えているところです。","id":"exchange-022"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"自由意見の施設のところは一番要望の高い部分ですので、やはり区民の実感というか要望と区の考えていることはかなりずれがあると。これは非常に高い要望なので、第四次長期基本計画の中でも早期に実施する計画にしていただきたいということを言っておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、施設とか事業所に対するアンケートもぜひやっていただいて、そのようなところも踏まえて第四期介護保険事業計画にしていただきたいと思うんです。実際に介護を受けている方の実態、その辺のところの実態調査、アンケートをぜひしていただきたいと思うんですがいかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"区内に１９カ所あります在宅介護支援センターでは、絶えず認定者の方と連絡を取り合いながら、十分状況については把握しています。事業所につきましても、また連絡を取っているところですので、日常的に区では十分ご意見等については把握できる状況にあるです。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実際に介護を受けられている方の困っている実態を、データとして把握していただきたいと思うんです。改めて実態をデータとして、また声として把握するということで、ぜひ調査・アンケートをやってほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"在宅介護支援センターのケアマネジャーからは、今後の第四期介護保険事業計画をまとめていく中で、何らかの形で聞いていきたいと考えています。そういうことも含めまして、検討をさせていただきたいと思います。","id":"exchange-025"},{"speaker":"高橋委員","kind":"質問","question":"「ご存知ですか」と聞いて「いいえ」と答える方が３０％、５０％いるんですが、この事業は何かという説明をした文書は入っているのでしょうか。「参加・利用したいですか」という質問があるので、何かアンケートの対象の方にお知らせする内容の文書が入っているといいかなと思ったんですが。","respondent":"冨岡高齢福祉課長","answer":"おっしゃるとおり、「ご存知ですか」と「参加・利用したいですか」と聞いておりますので、利用したい方は把握しておりますので、今後どうするか検討します。","id":"exchange-026"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"後期高齢者医療制度の健康診査についてお聞きしたいんですが、後期高齢者の健康診査は国民健康保険と同じような形になっていくのかということと、それは後期高齢者にお知らせをしているのかということについて説明を求めました。","respondent":"永尾高齢事業課長","answer":"すぐに医者に行かれてしまいますので非常に混雑しまして、かなり待たされてしまうという状況が予想されますので、２カ月ずらして予定しているです。受診券を送付するときに、受診の仕方等のお知らせを同封する予定です。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993548?Template=document&Id=3202#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":28387,"voices":74}},{"id":"h20-20080512-8","meetingId":"h20-cm05","date":"2008年5月12日","dateIso":"2008-05-12","committee":"建設委員会","time":"午後１時０１分～午後２時５９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"に入ります。 (1)の都市高速道路中央環状品川線南品川換気所下部工事説明会","agenda":"に入ります。 (1)の都市高速道路中央環状品川線南品川換気所下部工事説明会","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"前回の説明会なんかでも意見交換会の場か、何らかの場所でこういうご意見が上がったのかなと思うんですけど、それについてどういう状況だったのかをご説明ほしいと求めました。","respondent":"梶都市計画課長","answer":"ただいまは配布漏れとかの話についてだと思うんですけれども、今回の説明会につきましては、各戸へ自宅のポストに入れていったという形です。この説明会のほかにも４月２７日には一般の方々で意見交換会を行ってございまして、例えば、連絡漏れのないようにという形です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"お伺いしたかったのは、その前回の漏れがどういう状況だったのかなというのが１点と、納得が得られない部分がたくさんある部分ですから。半径５０ｍ、各戸で５,０００枚、その点もご意見を聞かせてください。","respondent":"梶都市計画課長","answer":"この説明会のほかにも意見交換会がたびたび開かれているとお話ししたこともあるんですけれども、そのときは、１月の意見交換会の中でどういった形で。それから、今までこういったチラシが届いていないとか…","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"この３番目のところに南品川換気所については、そのことについて品川区として、現実に予想されているわけですか。改築工事が始まって３４回ですか、ここにも書かれているので、働きかけをしていくのかというところを実際にお伺いしたいと思います。","respondent":"梶都市計画課長","answer":"この３０ｍの高さなんですけれども、ここの部分の空気を換気で送って、いわゆるファンによって上に押し上げる。建物につきましては３０ｍということなので、現在ぎりぎりの高さでございまして、それが３０ｍという形だと聞いております。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"建てて道路が進めれば、首都高のほうで管理をしていく、対応をしていくということになると。まちづくり事業部としてどういうふうに考えて、品川区としてどう考えていくのかということをお聞きしたいので、そういう話ではないんですけど。","respondent":"梶都市計画課長","answer":"半年後、交通調査等がありますけれども、事後も影響調査をすることになってあります。その時代にですね、最善の方法と申しますか、十分な要望を出しているです。","id":"exchange-004"},{"speaker":"井上委員","kind":"意見","question":"今回、この環境アセスのことでメッセージを２００４年４月に出したことで、対策を講じられたいということが幾つか出されているんですが、そのことについても東京都の回答はどういうふうになっているのかわかりますかとの意見を述べました。","respondent":"梶都市計画課長","answer":"平成１６年４月の段階で環境課のほうから東京都のほうに、そのことについて文書という形の回答があったかどうかというのは、かなり低い。山手通りより低い騒音しか発しないと、そういった話を説明会では回答が出ておりますので…","id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"たまたまこの品川区が議会の構成というか、ここのところについてはしっかりと共通認識として持たれていただきたいということを要望しておきますので。もう１つ、そのことについてきちんと対策をとっていくという指針というか、その辺の区の考え方をはっきり示してほしいと求めました。","respondent":"梶都市計画課長","answer":"住民説明の場につきましては、十分な対応を、対応というのが説明会だけではなくて。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"２つだけなんですが、最新技術を用いた脱硝装置や除塵装置をつけて導入してくださいと要望しているんですけれども、質の確認です。３階建て、６階建てぐらいの高さの建物になると、教育委員会ではどういう調整をされているのかということを確認だけさせてください。","respondent":"梶都市計画課長","answer":"東京都の方で、平成２２年の供用開始までに結論を出すということで、そちらのほうは検討していただくという形でお話を伺ってあります。私どもはこちらの改修のときに地域の方に不安のないような、丁寧な対応をしていただきたいという形の要望を続けて行っているです。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっと確認だけさせてください。何かここら辺のことはどう思ってこの地図でＯＫしたのかも教えてもらいたい。","respondent":"梶都市計画課長","answer":"そういった答えをしてしまったけれども、全体の中で話しているときは教育委員会のほうとは話を詰めていくということは聞いてあります。これにつきましては要望という形でなくて、意見、そういった状況も含めながら説明していきたいと考えています。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここら辺は東京都に言うのもしたいんだけれども、それは品川区でもしっかりそこら辺のところを答弁できるように情報収集をしているんでしょうか。そこら辺をちゃんと理論武装を準備しているんですかということを聞きたい。","respondent":"梶都市計画課長、岩田まちづくり事業部長","answer":"いただいているものだけで答えられるものについて答えていくというスタンスでございまして、もちろん、下部工事についての説明会という形です。いろいろな工事の説明会の中で、今の段階では説明会の細かい内容につきましては… こういう説明会だからといって、当然、先ほどの吹き上げたときにどれぐらいの影響が出るかということを含めてきちんとした説明をされると思います。学校関係について、事業説明会の資料をもとに…","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"何か区のほうで建築確認をとって建築説明会、案内状を必ず近隣に配布すると思うんですが、これをつけてくれると非常にいいんじゃないかと。それだけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"阿部委員","kind":"質問・要望","question":"これは１７日までには学校の要望なんかはきちんと伝わるようになっている、都のほうと学校との意見のすり合わせ、学校や保護者等の要望は伝わるような形にはなっているのかどうかについて説明を求めました。","respondent":"梶都市計画課長","answer":"こちらの下部工事の説明会が５月１７日に行われるわけなんですけれども、もちろん、もちろん調整はしているという形です。５５ｍくらい掘り進む工事ですので、そういった意味では、今以上のものは考えていないです。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、４月末までの工台の工事と、それからこれから始まる下部工事で、特に交通量の増減はないというふうに理解してよろしいんか尋ねました。","respondent":"梶都市計画課長","answer":"車両の通行というか、工事車両の通行はもちろん、あるという形で考えているといった状況です。","id":"exchange-012"}]},{"id":"topic-02","title":"の大崎駅西口Ｃ地区都市計画素案","agenda":"の大崎駅西口Ｃ地区都市計画素案","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"私からは日影のことと風のことをお伺いしたいんですけれども、１５枚目の資料を見ると、ちょうど朝方に芳水小学校にかかってきますよね。いずれ、複合的な日影が芳水小の太陽を奪うのかなと思っているんですけど、そういう影響はどういうふうに把握されているのか教えていただけますか。","respondent":"青木都市開発課長","answer":"この計画を検討するに当たりまして、それほど大きな影が増えるような位置にはないだろうということで、こういった配置を決めてあります。基本的には日が昇ってくれば、シンクパークタワーが落としている影の中におさまるだろうというところで、こういった配置をつくらせたもので…","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"一緒に風の影響のほうですけれども、１３ページですね。今回こういう調査をした理由とか背景とか何かございましたら、ご説明いただけますか。","respondent":"青木都市開発課長","answer":"これもそれぞれの開発の中で個別に検討しておりまして、市街地程度の影響を少なくすることは配慮しているものです。都市計画の提案においてはすべて現在こういった予測をした上で、影響を軽減するような対策を施すように指導しています。","id":"exchange-014"},{"speaker":"中塚委員","kind":"意見","question":"風のほうですけど、風影響評価とかそういうことをしているということですけど、この評価をどんなふうに区は分析されているのか。冒頭のざっとした説明の中ではそれを期待していたので、そこをご説明いただけますかとの意見を述べました。","respondent":"青木都市開発課長","answer":"シンクパークタワーが開業してほぼ１年たったころをめどに、いろいろな環境変化についてもフォローする調査をしていこうと考えておるものです。そういうところではないと考えておりますので、こういったまちづくりの方向でいけば…","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"簡単に質問いたしますと、要はこの１３ページの右と左に前と後があるんですけど、この変化をどんなふうに区は評価しているのかという質問です。今のお話ですと、安全性、快適性に影響はないというふうに結論されているのか、それとも、どうなのか、そこをご説明をいただけますか。","respondent":"青木都市開発課長","answer":"端的に申し上げて、このとおりにちゃんとシミュレーションの結果どおりになるなら、問題ないと考えております。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"区のほうがどう思っていらっしゃるかお伺いしたいんですけど、これは予測と実態にずれが起きていると感じるんですよね。ですから、この予測がどういう予測なのか、実際に説明会で使う資料だというならなおさらですけど、これがよくわからないんですよね。","respondent":"青木都市開発課長","answer":"風を検討するのは非常に、口頭で申し上げるのは非常に難しいんですけれども、今。地元で委員もおっしゃるとおり、少なくとも実際の風の強さを計りたいということで、今年度はそれを予定していることは先ほど申し上げたことです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"住民の関心からしても風害に対する対策が強めてほしいと伺えますので、検証を進めていきたいというお話だったので、もう少し中身を教えてください。そもそもこの想定が大崎この地域全体の建物、概要のところもありますけれども、どういう想定なのか伺いたい。","respondent":"岩田まちづくり事業部長","answer":"１年中通じて、全部に対応して、その最大の数値が出るポイントをここに落としているんです。こういったものをどう防ぐかということも、いろいろ建物の構造上で対応をとっていくのが一般的です。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"その具体的な中身にはちょっと触れなかったので、これはもう一遍伺いたいと思うので、ご答弁ください。有名だからという話がありましたけど、もっと風の影響について十分な資料が必要なんじゃないかなと。","respondent":"青木都市開発課長","answer":"あるいは、風速５ｍだとどのぐらいきついものなのか、きつくないのかということは、正直申し上げて、私はうまく説明できません。私どもとしても区民の方々にご説明できるように努力してまいりますので、区民の方々への普及も含めてご協力いただければと考えています。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"大変に不勉強なので教えていただきたいんですが、これは延べ床面積約１２万５,０００m2で、研究開発型オフィスだと書いてある。こういう開発型オフィスだとどれぐらいと見るのか、こういう一般的な話でいいですが、もしわかれば、説明を求めました。","respondent":"青木都市開発課長","answer":"１０万人ぐらいの出入りがあるかなというような想定で、これ、逆に言うと大部分が出入りのお客様ということで計算しています。都内あるいは郊外ということで設定されている数字を面積に当てはめて計算するという格好になります。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"大変不勉強なので、もう少し教えていただきたいのは、こういうのをするときに、共有の部分がありますよね。１人当たり何m2ぐらいが、各企業が持っていると思うんですけど、それくらいの部分はこういうときって何か計算式に出てくるものか尋ねました。","respondent":"青木都市開発課長、片田建築課長","answer":"ですから、９,０００人近くだそうです。建築計画の中では、机と机の間を３.２ｍと想定して、反対側のオフィスの机が並んでいるその中心間隔が３.２ｍだと。 たしか、記憶の中では４m2とか５m2ぐらいまでの幅の中で、想定を考えていくといったことがあります。経済的なスパンがあるので、大体七、八ｍまでが効果的なスパンかなということで計画しております。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"意見","question":"だけど、それは一上場企業であるとするなら、区は職員の方々に平米数があるわけです、必ず１人当たり。説明できるようにするためには、そういうチェックもしておいたほうがいいんじゃないのかなと思って聞いているので、何か考えがあったら聞きたいとの意見を述べました。","respondent":"片田建築課長","answer":"それが庁舎とか事務所とか、それぞれの用途ごとに決められております。会議を行ったりの場でとられる場所もありますので、できるだけ最近の状況の中で計画を進めていくというようなことになろうかなと考えています。","id":"exchange-022"},{"speaker":"三上委員","kind":"意見","question":"このＣ地区の計画は今回わかりましたけれども、西口南地区、要するに区が絡む計画についてはどうなっていますかとの意見を述べました。","respondent":"青木都市開発課長","answer":"都市計画変更、地区計画の変更と、さらに市街再開発事業の都市計画決定というものを昨年平成１９年８月２２日に告示しています。このＣ地区ソニー等が先行する形になりまして、平成２５年ごろの竣工を目指して今、活動中という状況です。","id":"exchange-023"},{"speaker":"三上委員","kind":"質問","question":"そうすると、先ほどちょっと風の問題が出たけれども、この今のソニーの部分だけの風を計算した部分で処理されているのか、それとも、今、中地区それから南地区という部分が、既にそういう建物ができあがったという状態での計算されたような風の流れというふうに読んだらいいのか…","respondent":"青木都市開発課長","answer":"風等につきましても、すべて現在計画がわかっているものについては、その計画が完了したものとして設定しています。そういったものももしかしたら背景にあるのかなということで、検証していきたいということで、そういった問題についても勉強している最中です。","id":"exchange-024"},{"speaker":"三上委員","kind":"質問・要望","question":"最初にそういうことを説明するときに、それをきちんと前提はこうですよということを言っていただいて、説明していただいたほうがわかりいいのかな。もう少し研究してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"平成２１年着手、平成２３年竣工予定とあるんですけれども、交通広場といったものは同時に竣工ということになりますか。これより早くなるのか遅くなるのか説明を求めました。","respondent":"青木都市開発課長","answer":"区のほうで施工することになるだろうというふうな調整をしていますけれども、来年度に設計して、平成２１年度に施行したいと予定しております。公園につきましては、これについては現実的には南地区の完了と同時に都市計画公園としても再整備されるとお考えいただければと思いま…","id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"この最初におっしゃった区画道路は、中地区との間は１号だと思いますけれども、南地区との間の２号というのはいかがでしょうか。そういったお考えがあるかどうか。","respondent":"青木都市開発課長","answer":"南地区の事業に合わせたほうが、きれいなしつらえでお使えいただけるのかなということで今、同時オープンということを検討しております。これにつきましては、地元の声を踏まえて、部分開業することも不可能ではないので、検討してまいりたいと思います。","id":"exchange-027"},{"speaker":"阿部委員","kind":"質問","question":"今、都市部では上昇気流がビルの中から発生して、それが都市型集中豪雨の原因になっているような話も聞くことがあります。例えば、こういった高いビルができることで、そういったリスクが増す、増さないといったような検討というのはされているのか尋ねました。","respondent":"青木都市開発課長","answer":"都市の環境に対する問題というのが現在、クローズアップされておりますので検討しております。対策が検討されておりまして今回の建物では敷地の５０％近くを緑化する対策で何とかヒートアイランドに対するひとつの答えを出していきたいと計画さ…","id":"exchange-028"}]},{"id":"topic-03","title":"の大崎ウェルカム・ビジョン","agenda":"の大崎ウェルカム・ビジョン","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この大崎ウェルカム・ビジョンって、でっかいテレビのことだと思うんですけれども、これは幾らかかるんですか。補助金というんですか、税金が入っているのか、いないのかそこの確認だけお願いします。","respondent":"青木都市開発課長","answer":"運営費につきましては、ケーブルテレビへの委託も含めまして、月々６０万円から７０万円ぐらいかかるのかなと考えています。基本的には、冒頭の説明で申し上げました都市再生ビジョンという大崎のまちづくりについては、どんどん活用していきたいと考えているところです。","id":"exchange-029"},{"speaker":"井上委員","kind":"確認","question":"確認なんですけれども、運営費として６０万７０万を按分するというお話でしたので、どこに効果があるのというところを聞きます。","respondent":"青木都市開発課長","answer":"予定ですと申し上げましたのは、一定の割合で区にバックしてもらいたいということも、今後協定の中に入れていこうと思ってあります。で、あまりにもひどい場合には区が何らかの支援を行えるのかどうか、そういったことも現在検討しています。","id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"その上で、補てんをするとかというのは、どこでどういうふうに協議をして決定される仕組みをつくっていこうとしているのか。協議の段階でこの検討ということもあるかもしれませんけど、区としての考えはどういったものか尋ねました。","respondent":"青木都市開発課長","answer":"行政財産を使用許可する場合には、原則、使用料をいただくというのが、地方自治法上の原則です。その中で今回の設備の趣旨、どのような方法で支援ができるのかについて現在考えている最中、検討して最中ですので。","id":"exchange-031"},{"speaker":"井上委員","kind":"質問","question":"初めは運用開始が平成２０年６月ということは、もう一月ぐらいしかないんですけれども、それまでに今お話をされたことは決定をされていくというスケジュールか尋ねました。","respondent":"青木都市開発課長","answer":"ご指摘のとおりです。","id":"exchange-032"},{"speaker":"阿部委員","kind":"質問・要望","question":"確認させていただきたいんですが、この場所では、これがウェルカム・ビジョンということでよろしいんでしょうか。ちゃんとクオリティーの高いものを提供していかなければ、目障りなだけですから、そこら辺をどういうふうにつくっていくか。","respondent":"青木都市開発課長","answer":"現在そのコンテンツなどの充実が間に合っていないものですから、ハードができ上がったけど、オープニングができないという状況です。区の広報広聴課の支援を仰ぎながら、今、協議の場を区で用意しています。","id":"exchange-033"},{"speaker":"阿部委員","kind":"質問","question":"コンテンツについてもう少し伺いたいんですけれども、これは基本的に静止情報、イベント情報とか、あるいは店舗情報も含めて、それとも、これ専用の番組というものをつくっていくものなのか。","respondent":"青木都市開発課長","answer":"なるべくアイキャッチ的な、１０秒、１５秒とかの内容を繰り返し流せるもののイメージが強くなっています。肖像権とか差し支えなければ、地元に活用いただくということは、まさにそのためのものというふうに期待しています。","id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"これは参考までに書いたということですか。実際この青い品川区の旗は。","respondent":"青木都市開発課長","answer":"既にゲートシティーの敷地内に同じような物があって、時折々に地域的なものを掲げてもらっています。たまたま今回、資料としてまだ具体的なスポンサーはついていませんので、たまたま品川区というものをモンタージュしてあそこにつけたものです。","id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問","question":"間違っていたら、教えてください。どういう方法論でというか、どういう理由づけをしたというか、それを教えて。","respondent":"青木都市開発課長","answer":"道路法の適用を受けないので、屋外広告物条例の適用も入らないということで、こういったことが可能になった。けがの功名という形です。","id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"意見","question":"この線路よりこっち側の道路の上にあるよね。それは道路なのかということも改めてとの意見を述べました。","respondent":"青木都市開発課長","answer":"山手通り、都道環状６号線の上と区道補助１６３号線および、この付属する交通広場の上のデッキ部分については、これは区道。道路法の適用というのは受けないということで、広告等は道路ではないので掲示が可能というところで活用しているものです。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"ソフト面のところをもう少しお伺いしたかったんですけど、という話の中で、品川区のかかわりの形が見えてこないんです。番組の制作とか情報の提供とか、どういう権限でどういう参加をしているのか、そういうことが形が見えない。","respondent":"青木都市開発課長","answer":"この事業のために活用してほしいということで、提供することは、この地域活用の支援という位置づけで品川区からの情報提供があるという。いずれにしましても、地元あるいは民間の方々の工夫でにぎわいをつくっていってほしいという願いを込めて、地域の団体に運営を任せるもので…","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"行政財産を使って行うわけですから、基準というか、それがよくわからない。ここのところをご説明いただけますか。","respondent":"青木都市開発課長","answer":"その１つとしての情報発信ですので、競争力の強化というような、それは広く認めていっていいのかなというふうに現在のところ考えております。企業も含めて、住民も含めて、ある程度の企業広告ということも容認してもいいんじゃないかというふうに考えて進めています。","id":"exchange-039"},{"speaker":"三上委員","kind":"意見","question":"地域情報ボードというのは、ガラス面から少し飛び出して足をつけて取り付ける仕組みになっているのか、それともガラス面のところからそういうところから直接取り付けるような感じになっているのかとの意見を述べました。","respondent":"青木都市開発課長","answer":"全部で３７面ほど用意しているんですけれども、基本的には現在ありますガラスの手すりというのか、ガラス面を支えているステンレスか何かの柱がありますけれども、高欄と言いますけれども、そこに抱かせる形で、設置できているはずです。","id":"exchange-040"},{"speaker":"三上委員","kind":"質問","question":"人の流れがそこにずっとあるということになったときに、ここの場所が適当なのかどうかということについては、どういう判断をされたのか。そうなったときにそういう人の流れの混雑状態に合わせて、事故のもとにならないのかとか、そのあたりはどういうふうに検証されたんか尋ねました。","respondent":"青木都市開発課長","answer":"お越しになる方々に大崎のイメージを強烈にインプットしたい、イメージしていただきたいということで、目立つところに設置しました。極端な話、というイメージがほんの数秒で認識できるものを数多く流したいと考えていまして、これは放送する中身で対応していこうと考えておりま…","id":"exchange-041"},{"speaker":"三上委員","kind":"意見","question":"瞬間かはわからないけれども、人が瞬間的に止まったところでぶつかってしまうというようなことにはならないのかどうかということなんですよね。どうなのかというあたりについて、そういう接触事故みたいなのはありませんよと…","respondent":"青木都市開発課長","answer":"繰り返しになりますが、横目でチラチラ眺めていただくような内容にしていきたいと考えております。直ちに事態が悪くなるというようなことにはならないというふうに考えて、中身についてもそういった運用を図っていくつもりです。","id":"exchange-042"},{"speaker":"阿部委員","kind":"質問","question":"これは音声を出すのかどうかということと、それから、放映時間は何時から何時までと考えているのかということを説明を求めました。","respondent":"青木都市開発課長","answer":"放映時間についても、朝７時ぐらいから午後９時ぐらいまでかなということを今イメージしていますけれども、これは確定したわけではございません。そういったものを地元の声を配慮しながら、運用しながら考えていくことだと考えています。","id":"exchange-043"},{"speaker":"阿部委員","kind":"質問・要望","question":"大勢が集まる場ですから、渋谷の屋外テレビみたいな感じになってほしくないという意味で音声のことを聞きました。それとも貸したんだから、エリアマネージメントが決めることで、区は要望を出すだけという関係にあるのか。","respondent":"青木都市開発課長","answer":"の活用に貸し出しますという考え方ですから、区は積極的に中身に関与するつもりはございません。当然地元からの町会の声とか、エリアマネージメントでも、基本的にはエリアマネージメントが表に立つという形にしていきたいと考えています。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問・要望","question":"ほかの地域のところから、少しだけでも、ちょっとそういう視点も残しておいて計画をしてほしいなというのは要望としてお伝えしておきたい。そういう要望があれば対応できるような、そういう緩みもとっておいてほしいなというところは意見としてお伝えしておきたいということが１つと、ぜひ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"}]},{"id":"topic-04","title":"の区民住宅（あき家）入居予定者登録募集","agenda":"の区民住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"参考までに聞かせてください。この１年間ではどの程度空きが出たんか尋ねました。","respondent":"齋藤住宅課長","answer":"現在の空きの数は３４戸です。今回募集すると、二十二、三ぐらいに毎年のパターンで減ると思います。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759088?Template=document&Id=3908#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":35436,"voices":112}},{"id":"h20-20080512-9","meetingId":"h20-cm05","date":"2008年5月12日","dateIso":"2008-05-12","committee":"文教委員会","time":"午後１時０３分～午後４時１０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"校舎改築事業の進捗状況","agenda":"校舎改築事業の進捗状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ですから、２つも同じような施設をつくるのはなかなか厳しいんだろうなと思うので、住民を含めた検討のときにはしていく必要があると思うんですね。ですから、その辺をどういう考え方をされるのかを、ちょっと伺っておきたいと思います。","respondent":"田村庶務課長","answer":"２５ｍプールとその部分の工事になりますので、その部分の簡易な舗装をする予定ですので、明かりも含めて対応してまいりたいと考えております。先ほどご説明の中で申し上げたとおり、地域との懇談会をやる予定ですので…","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"地域の説明会でも伺っているところなのでそれは承知しているんですけれども、校舎はグラウンドの向こうですから、１００ｍはないですけれども。そういう問題について、どのように区としては認識をしているのかというところを、考え方として伺っておきたいと思います。","respondent":"市川教育次長","answer":"１点目のアスベストの関係ですけれども、区有施設全般の対応策を検討した結果を議会のほうにも報告させていただいてありますけれども、当時の考え方。もう１点、地域全体の施設の利用ニーズとの関係を、当初から検討の視野に入れてやってきているつもりです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"温水プールの件ですけれども、八潮の地域に温水プールをつくってほしいという要求は、そういう意味では２０年前ぐらいからあったんです。あるいはコースは生徒の授業で使うわけですから、今後の教訓として、その辺もちょっと受けとめておいていただきたいと思っての発言です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"山内委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、第三日野小学校の渡り廊下がありますよね。例えば引っ越しの車とかが、そういう車が通るときの安全性とか、そういうのをちょっと説明を求めました。","respondent":"田村庶務課長","answer":"上空通路のところでＢ１、Ｂ２ということですから、約７ｍぐらいの高さになるのかなです。安全性の関係ですが、交通上の安全ということでも、上空の通路ですので、警察との協議をしていますので、大丈夫です。","id":"exchange-004"},{"speaker":"山内委員","kind":"質問","question":"そういう形での環境に対しての対処だと思うんですが、やはり全体的にどの新しくこれからできる校舎というものも、そういう意味での環境に配慮したという理解でよろしいんか尋ねました。","respondent":"田村庶務課長","answer":"これから改築計画だとか一貫校を進めるということで、可能な限り対応とか、環境配慮型の学校建設というものを引き続き心がけていきたいと考えています。","id":"exchange-005"},{"speaker":"金野委員","kind":"質問","question":"２点ほどお伺いしたいと思います。西地区の屋内プールの天井の構造というのは、最上階なんですが、どのようになっているんか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"この部分につきましては、長い期間使えるようにということで、透明の部分がありますが、全部覆わないという形になります。ですから、伊藤学園のようにドームとかいう形ではなくて、固定式の屋根がつく予定になっております。","id":"exchange-006"},{"speaker":"金野委員","kind":"質問","question":"冬場でもものすごく暑くて、日除けが必要だという声を伺ったことがあるんですが、ここに関してはそういうことは心配はないという感じでしょうかね。プールサイドで休むときに日除けの部分というのは、この絵を見るとどこかなという感じなので、夏場はどうなんか尋ねました。","respondent":"田村庶務課長","answer":"第三日野小学校の日除けの関係ですが、この図面上は何もかいてございませんが、今後日除けをつくる形で考えておりますので、今の段階ではない形になっておりますが、今後はあるような形になるです。","id":"exchange-007"},{"speaker":"金野委員","kind":"質問","question":"次に、単純な疑問なんですけれども、八潮の小中一貫校のこの図面で、それぞれ学年のクラスの配置が出ているんですけれども、この配置の根拠というんでしょうか、理由というんでしょうか、教えていただけますか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"八潮南のほうで実践をしておりますが、それに基づきまして、どういう形の配置がいいかというのを再度検討する予定にしています。もうちょっと検討をした上で、具体的な配置は考えてまいりたいと考えております。","id":"exchange-008"},{"speaker":"金野委員","kind":"質問","question":"この配置の仕方によっては、せっかくの小中一貫で１年生から９年生まであるので、何か異学年で交流を持てるような配置だったでしょうか。そういうのがあったんか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"１年から４年までが南小学校、５年から９年までが南中学校の校舎でそれぞれやっておりますけれども、考えてあります。新校舎のその配置も考えており、そういうものを踏まえまして、配置を再度考えてまいりたいと思っているところです。","id":"exchange-009"},{"speaker":"金野委員","kind":"質問","question":"一番左側の下の２階平面図の中に３年生と４年生、その横に８年生と９年生がいるというのは、何となくそういう異年齢交流というのも考えての配置はこんなふうになるという理解でいいんか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"これを実際１年間やってみまして、どういうのが一番効果的な交流になるのかというのを検証した上で、再度配置したいと考えています。あくまでもこれは仮ということでご理解いただきたいと思います。","id":"exchange-010"},{"speaker":"金野委員","kind":"質問・要望","question":"最後、要望で。感じたことがありますので、よりクラスの配置もそういったところも考慮していただくということなので、ぜひその辺もよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"１、２階平面図のところでいうと、どの部分が地下という形になるんですか。せっかく改築をするわけですから、自分たちの学校だという意識づけをすることで、そういう子どもたちの関わりということはあるんか尋ねました。","respondent":"田村庶務課長","answer":"逆に第２体育館のほうも利用できる、あとは連携の話ですので、学校と調整しながら対応をとってまいりたいと考えております。説明を省略しちゃいますが、資料２ページ目から見ていただきますと、このような記載のコンセプトでそれぞれ進めている内容です。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、建築計画はだれが決めたんですかということを聞きたかったんですね。ただ特徴の１つになっているんだろうなと思うんですけれども、その特徴の出し方がどういう出し方をしているんですかということをお願いします。","respondent":"市川教育次長","answer":"一番大切なのは、学校施設ですから、多様な学習活動への対応、これをいかに実現していくかという、そこのところが基本的なコンセプトになっています。決して設計事務所が一方的に打ち出したものではないということは、１つご理解をいただきたいと思います。","id":"exchange-013"},{"speaker":"石田（慎）委員","kind":"提案","question":"同じく提案になってしまうんですが、今後何十年もそこにある学校になるわけですから、そういった意味で共同作業をできないのかなというのが３点目。そうした対応というのはどのように、避難所として、ちょっとほかの所管になるんですが、防災関係で２点、もしわかれば教えてほしいと求めました。","respondent":"田村庶務課長、市川教育次長","answer":"どうも私が聞いている範囲では、名称を懇談会というふうにしたということで、中身的には何らほかと変わるところはございません。現行の下のほうが八潮小学校のグラウンドをそのまま利用するという考え方ですし… これは個々の改築事例に応じて対応しています。単独改築の場合にはそのままというのがあるんですが、工事期間中の対応も含めて、その辺のことについては地域調整をしています。","id":"exchange-014"},{"speaker":"市川委員","kind":"質問・要望","question":"品川地区の小中一貫校は、先ほども説明ではほぼ基本設計がまとまって、改めて報告するというふうに伺ったんですけれども、ほぼまとまった段階で、何階建てで、高さとしてはどのくらいになるのか教えていただきたいんですけれども。","respondent":"田村庶務課長","answer":"まだ最終調整中なんですが、今のところ基本計画では小・中合わせて３２学級で、地上４階建て、塔屋１階というのを予定しています。","id":"exchange-015"},{"speaker":"市川委員","kind":"質問・要望","question":"ここの地域は中央環状品川線の換気塔が計画されている地区かと思うんですけれども、当然学校への環境というところは配慮されていると思うんですけれども、その辺、まちづくり事業部のほうとどういう協議がされているのか、教えていただきたいんですけれども。","respondent":"市川教育次長","answer":"今の時点でまちづくり事業部のほうから、私どもの建設計画の中で特に考慮すべき事項としては、特段の通知が出ていることはございません。環境保全も含めて、一層の学習環境の向上ということで、基本設計を進めてきているところです。","id":"exchange-016"},{"speaker":"市川委員","kind":"質問・要望","question":"換気塔の高さが２５ｍと聞いているので、この地域にとっては、とてもその辺が学校に影響があるんじゃないかという心配の声も聞きますので、ぜひ学校への影響というところはきちんと調査をして、まちづくり事業部のほうと連携をとりながら進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"は外部との接触がどういう設計になっていくのか、幼保だと衛生面も含めてシビアにならないといけないと思うんですね。それからあと給食室のところがあるんですけれども、厨房はとの意見を述べました。","respondent":"田村庶務課長、市川教育次長","answer":"３階の平面図のちょうど真ん中の一番下段のピンク色になっているところが、幼保の厨房スペースということになっております。一番左の１・２階平面図を見ていただきますと、スタジオだとか… 表から入るときには坂を上がってきて、フラットなところでここのところに入れるという、区役所の３階のプラッツアと同じような感じのイメージです。ですから、これで４階と書いてあるとかなり高低差があるように思うんですが…","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"要望として聞いていただきたいんですが、安全も含めて、どういう人の動きになるのかというのをお示しを今後していただきたいと思っているんですね。細かい話になっちゃうんですけれども、地域の方が使うときにはどういう動きになってというのがこれだけだと全然わからないので、お願いします。","respondent":"市川教育次長","answer":"文化センターのほうから入るような方法を考えておりまして、一般開放についてもなるべく学校動線とかぶらないように設計をしております。詳細についてはまた改めて、もう少し細かい図面が出てきて時点でお示しすることになろうかと思います。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"そこをちょっと確認したいのと、その辺はどういう議論でこうせざるを得ないかなという経過になったのかをお聞かせいただきたいのが１つと、この間。だから、一貫校のスタートのときに校歌があっていいんじゃないかと思ったんですけれども、その辺はどういうふうになっているんか尋ねました。","respondent":"和氣小中一貫教育担当課長、田村庶務課長","answer":"先に校歌のご説明を申し上げます。でき上がり次第、練習をして、披露会を催したいと考えています。 あるいは３年、４年と、最終的な判断としてこういうレイアウトにするということになったものです。実はその下の吹き抜け部分のことを光の庭という言い方なので、設計会社のほうで光の庭という言い方をして、通常の吹き抜けです。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"５年生、６年生は、みんな教室の窓そのものは北側にしかないということですよね。１日の大半を過ごすのが学校ですし、今は選択制ですから、どうなんか尋ねました。","respondent":"市川教育次長","answer":"やむを得ないかどうかということよりも、建物というのは立地に規制される部分が大分ありますので、その中でいろいろ検討させていただきました。私どももいろいろな検討をした結果こういう配置になったということで、受けとめていただければと思います。","id":"exchange-021"},{"speaker":"南委員","kind":"意見","question":"そういう考え方をとろうと思えばとれたと私は思うんですけれども、１学年しか日が直接当たらないというのは、非常に残念ですよね。１学年しか南側に面していないというのであれば、いかがなものかなと、残念だなと思うんですがとの意見を述べました。","respondent":"市川教育次長","answer":"ここが一番の検討の難所だったんです。先ほどいろいろな検討の結果といった具体的な検討の比較対象したのが今の点ですので、その上で説明をさせていただきたいと思います。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、やっぱりあくまでも大事にしていただきたいなということを言っておかなくちゃいけないと思ったので、言いました。校庭は今までと比べてどのくらい広くなったのか、この数字だとその辺は私も読み取れないので、そこをちょっと教えてほしいと求めました。","respondent":"市川教育次長","answer":"現在の第１校庭というのは、プールが埋め込み式のプールで、校庭が半分ぐらい使えなくなってしまう。こういったことを含めると、先ほど言った広い校庭の確保ということを実現したと私どもは考えてあります。","id":"exchange-023"}]},{"id":"topic-02","title":"学校給食をめぐる状況","agenda":"学校給食をめぐる状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"２３区の中の教育の関係のところでも、そういう話というのはしているんでしょうか、していないんでしょうか。４区程度しかわからなかったので、どういう区が改定されたのか、もしわかれば教えてほしいと求めました。","respondent":"富田学務課長","answer":"国に対してですが、そういうことについて国に要望する等々ということではないと考えているところであります。８区の内訳は、７年ぶりであるとか、あるいは毎年見直し改定をしているといった区もあります。","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"給食の部分で家計に重たい負担を押しつけるということになるのは、やっぱり一定程度の考慮、配慮があってしかるべきじゃないかなと。値上げを検討する以前の段階で、もしこういうことをしていますみたいな、そういうことが紹介されているのがあれば教えてほしいと求めました。","respondent":"富田学務課長","answer":"４月以降もなお値上がりしてくるといったような状況の中で、食品構成ですとか、年度途中でということになったところであります。その辺のところをご理解のほどよろしくお願いいたします。","id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"もっと、そういうことも考えられないのかなということが１つあるのでさっき伺ったんですが、本当にそういうことでいいのかどうかということは。ですから、その辺を、いろいろな関係機関との調整も含めて、検討していただけるようにお願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"それはどういう調整をしているんでしょうか。そういうのは、どうなっているんか尋ねました。","respondent":"富田学務課長","answer":"肉等々については、おおむね地域の業者から、それぞれの学校が購入をするという形をとっているところです。多古町等々、すべてを産直野菜のところで補うというふうにもしておりませんので、そういったところは学校により若干の違いが出てくるものがあります。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"そうすると、学校の仕入れ先によって、この金額で、価格を変えていくといったときに、それで十分なところもあれば、不十分なところも出てきてしまうということもあり得るんじゃないかと思うんですが、そこの価格の調整というのはどういう形で調整していくんか尋ねました。","respondent":"富田学務課長","answer":"購入にあたっては、各学校の購入という形を継続している方針を持っておりますので、その辺はやむ得ないものかと考えています。といいますのは、もし万に一つ何かあったときのリスク等々という配慮から、共同購入という形を歴史的にとっていないです。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"先生方の負担とかやり繰りなんかも含め、非常に大変な状況になってくると思うので、そこは何かできないものなんですかね。は余ったお金をマンモス校から小規模校に渡すとか、そういう価格的な負担を学校側の差がないような形にはできないものなんか尋ねました。","respondent":"富田学務課長","answer":"２３区の中には学校ごとに給食費を決めている区も実はありますけれども、一般的には、金額というものは区の中で統一の給食費を定めているわけです。は献立等々、運営の工夫の中で、それぞれの学校が運用していくという形をとっています。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"共同してみんなで苦労して考えていこうかという考え方もあるかと思うので、改定をする際に、そこを１つ考慮点に入れていただけないかなと。そうすると、お金のやりとりをすることで２４０円でおさまるとか、考え方としていろいろな方向を考えていただきたいなと要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"金野委員","kind":"質問・要望","question":"１点目が、どんな割合でこれまでは改訂されてきたのかを教えていただきたいのと、また標準の数値というんですかね。例えば０歳から６歳までのお子さんの、例えばカルシウムを幾つ取らなきゃいけないとかという標準があるじゃないか尋ねました。","respondent":"富田学務課長","answer":"ここが大きな変更点であります。ソラマメ２.９、ヒヨコマメ２.９、この食品をこれだけ取りなさいよというものが定められているというものです。","id":"exchange-031"},{"speaker":"金野委員","kind":"質問・要望","question":"こういうものをしてきましたというのが何かあれば、教えていただきたいんですけれども。これを使わなきゃいけないという形なんか尋ねました。","respondent":"富田学務課長","answer":"品川区ともう１区ぐらいと聞いておりますので、そして魅力ある内容というところのために、定められた給食費の中で大変な努力を現場ではしていると。これこれと一つひとつ申し上げられませんけれども、そういうふうに考えております。","id":"exchange-032"},{"speaker":"金野委員","kind":"質問・要望","question":"当然そのようにされているということは承知をしております。どこかに改善を求めたときに、こういったものを１００％網羅、もう少し頑張っていただければというお願いも含めてお聞きいたしました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"山内委員","kind":"質問・要望","question":"そういう意味では、給食費の値上がりというのはいたし方がないことなので、給食費がこれこれこういうわけで上がるんですよと。これはあくまで要望になってしまいますけれども、保護者に説得するということを、あくまでもこれは要望しておきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"市川委員","kind":"質問","question":"２３区の中で給食はとても難しいということは私もわかっているんですけれども、給食費の額というのは全体の中でどのレベルなんでしょうか、説明を求めました。","respondent":"富田学務課長","answer":"文京区については、１２円から２８円の幅を持っているところです。中学年は５番目、高学年は４番目、高いほうから１４番目という状況であります。","id":"exchange-035"},{"speaker":"市川委員","kind":"質問・要望","question":"それからもう１つお聞きしたいのが、年間として滞納するという割合というんですか、教えていただきたいんですけれども。","respondent":"富田学務課長","answer":"平成１６年度の各学校ごとの給食会計、仮集計をしたものでありますけれども、小学校、これは小中一貫校を含みますが、これについては未納率は約０.１％、中学校につきましては０.４％ということで、これはほぼ平成１８年度と同様の割合であります。","id":"exchange-036"},{"speaker":"市川委員","kind":"質問・要望","question":"額がどれぐらいなのかということもあわせて教えていただきたいのと、あと１００％保護者から集めるのは、給食費は１００％食材だと考えると、滞納者への補てんをどこかでしなきゃならないと思うんですけれども、その辺は品川はどのようにやっているのか。","respondent":"富田学務課長","answer":"中学校については１億９,２００万円の中での８０万円を切る額ということで、それぞれ未納ということであります。教育委員会としても１００％徴収をすべく、今後、学校と協力してやっていくという予定にしているところであります。","id":"exchange-037"},{"speaker":"市川委員","kind":"質問・要望","question":"それから、値上げをしている食材は輸入をしているものが多くて、今回の値上げでおさまるというふうには考えられないんですね。そうした場合にはどうやっていくのか、また値上げということになるのか、その辺の考え方を教えていただきたいんですけれども。","respondent":"富田学務課長","answer":"保護者の方々に対しては、時期、金額等が決まった時点で速やかにご案内を申し上げ、学校を通してもご協力のお願いをしてまいりたいと考えています。４月に上げてスタートした区については、ある程度状況を見た上での改定ということで…","id":"exchange-038"},{"speaker":"市川委員","kind":"質問","question":"区全体で８０万円というお金は、この補てんというのはどこから出されるものなんですか。それは税金というか、それが充てられると考えていいんか尋ねました。","respondent":"富田学務課長","answer":"未納の金額については、公費での補てんということはしておりません。","id":"exchange-039"},{"speaker":"市川委員","kind":"質問","question":"公費での補てんがないというのは、どうやって補てんをしているんか尋ねました。","respondent":"富田学務課長、市川教育次長","answer":"各学校の給食会計の中で、まだ未納であるということで会計処理をしているです。 要はいただくべき給食費はいただくという原則で各学校で対応しております、未納者に対して。なおさらいただくべき給食費はいただくんだということで、各学校の担当者たちが未納対策ということで苦労している、これが現状です。","id":"exchange-040"},{"speaker":"市川委員","kind":"質問・要望","question":"最後に要望ということなんですけれども、そういう道筋というものはしっかりつくって検討していただきたいということを、要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、未納の０.１％と０.４％のこの方々というのは、個々はあるけれども、払う能力はあっても払っていないということなんですか。その辺の０.１％と０.４％をどう見たらいいのかなというのがちょっとわからなくなっちゃったので、教えてほしいと求めました。","respondent":"若林委員長、富田学務課長","answer":"給食費の未納の問題ですので、これで質疑を終わりにしますので、簡潔にお答えをお願いいたします。 給食費をお支払いいただけない状況というのは、個別さまざまあろうかと思いますけれども、支払うことが経済的には可能であろうと思われる方々で、お支払いいただいていないという方々も何人かいらっしゃるというのも事実です。","id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"０.１％と０.４％のこの方々は、いわゆる悪質、社会問題になりましたよね。そういう方たちだけで、能力がなかなかなくて払い切れないという方たちは、一定の対策の中でフォローされていると見ていいんか尋ねました。","respondent":"市川教育次長","answer":"こういう保護者に対しては、司法手続によっても払っていただく、こういう対応を今、体制としてはとっております。それからもう１つは、保護者の意向で、生活保護なり就学援助を受けたくないという方がいらっしゃるんですよ。","id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"０.１％といえども、デリケートな部分であることは承知しながら聞きましたので、ちょっとお許しほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"}]},{"id":"topic-03","title":"平成２０年度小中学校新入学者増減","agenda":"平成２０年度小中学校新入学者増減","exchanges":[{"speaker":"南委員","kind":"意見","question":"小学校、中学校とも昨年と比較して、そんなに大きな数ではありませんけれども、減っているというところはどういうふうに見るのかと、あと国公立とか私立への進学について、この数字というのは、この間の受け入れから見るとどういうふうになっているのかという…","respondent":"富田学務課長","answer":"平成１９年度は５.６％で、平成２０年度は５.４％ということで、減少しております。平成１９年度は２７.８％で、平成２０年度は２６.１％ということで、減少しているです。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"何回も聞いてわからなくなってしまうので確認したいんですが、希望申請、指定校変更、区域外就学ですね。これはいつの時点のことなのかとか、そこの数字の定義というんですか、どういう人の数なのかご説明いただきたいんですけれども。","respondent":"富田学務課長","answer":"その指定校ではない学校に行きたいよという方が出た場合に、指定校変更という制度が、さらに希望申請の後でされるということになってまいります。これは例えば行った先の住所に引っ越す予定であるとか、通学距離等々を勘案してというような指定校変更の申請がなされます。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"その学区域の中に住んでいるお子さんについては、そこを希望していれば何もしなくていいわけですね。品川小学校じゃなくて、同じブロックの城南小学校に行きたいといった場合に指定校変更ということか尋ねました。","respondent":"富田学務課長","answer":"希望申請です。","id":"exchange-047"},{"speaker":"西本委員","kind":"意見","question":"希望申請を出した方が、３９人ほかから品川小学校を選んだという形になるわけですね。定員はというか、増えちゃった分の人たちというのはどういう動きになりますかとの意見を述べました。","respondent":"富田学務課長","answer":"指定校変更には基準がありますので、人数内であれば受け入れていくという性質のものではございませんで、一件一件について妥当であるかどうか、学校の受け入れ枠があるかどうかということも含めまして、審査をした上で決定をするということになってまいります。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、指定校変更というところは、ブロックの中とか定数とかということ、もちろん最終的にはそれを踏まえてのあれになるんでしょうけれども、いろいろな事情のある方ということなんか尋ねました。","respondent":"富田学務課長","answer":"学校選択が始まる前までは指定校変更の制度一本でしたので、指定校変更ということで。指定校変更については基準がありますので、先ほど申し上げました転居予定であるだとか、あるいはお子様の個別の教育的配慮の問題だとか。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"その上で、要はそれは決めたんだけれども、途中で変えますという人がこの指定校変更なんですか。選択制だから、もともとそういうものを加味した上で希望申請を出すんじゃないかと思うんですけれども、そうじゃない状況があるんか尋ねました。","respondent":"富田学務課長","answer":"基本的には学校選択は、小学校についてはブロック内での選択ということになりますので、まずはブロック内の方優先に就学指定をいたします。その上で指定校変更の制度を利用していただくということになりますので、基本的にはないということです。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"だけど、その後、一時的にブロックをまたがって申請するという形をするということになるんですか。これは待機の状態、抽選になってしまっている人たちが、抽選になっちゃったからもとに戻すよという方たちの数と認識してよろしいんか尋ねました。","respondent":"富田学務課長","answer":"小学校で言えば６９５人、これはかっちりと固めて、まずはこの学校を希望された方々の数ということで出しています。その方々が抽選後戻りの数ということで、こちらに載っているです。","id":"exchange-051"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（慎）委員","kind":"質問","question":"件数なんですが、五反田文化センターの例えば８,００８件、これは文化センターを使った利用件数ですか。それともこの併設施設を含めたものか。","respondent":"堀越生涯学習課長","answer":"こちらの数字は文化センターのご利用をいただいた数字を載せしています。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"そもそも文化センターの特徴は何でしょうかということなんですけれども、ちょっとわからなくなっているなというのがあるんですね。いろいろな施設が、文化センターである意味とかというところはどういうふうに考えられているのかなということをお聞きしたいと思うんですが。","respondent":"堀越生涯学習課長","answer":"文化センター的な機能も持っていますし、そういった意味で、集会所等においても幅広く使っていただいているです。先ほど説明させていただきましたように、そういった特徴をもう少し持たせるような、そういう展開も検討していきたいと考えております。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"今、いろいろな使い方、文化センターがなぜ区民に対して必要なのかというところが不明瞭になりつつあるなというのを非常に強く感じているんですね。日本の中でとか変わってきつつあるとか、そういう動向というか、傾向はあるんか尋ねました。","respondent":"堀越生涯学習課長","answer":"そういう検討はこれから進めて、またネットワークを進めて、ほかの集会所等ももちろん考えられると思います。これからの検討、今も検討しておりますけれども、またさらに進めていきたいと考えております。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問・要望","question":"そこの中でも特徴がどうなんだろうなというところがありまして、文化センターである意義とか、そういうところをちょっと考えていただきたいなと。今、説明されたように、生涯学習という形で位置づけということであるならば、それなりの役割というのをもう少し考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"南委員","kind":"質問","question":"地域の主体的な活動をどう支援するかというところで見たときに、１０年ぐらい前に、要求に見合った講座を組んでいた。今の質問をさせていただいたんですが、どんなふうに見ておられるのか、それをちょっと知りたいところです。","respondent":"堀越生涯学習課長","answer":"一定程度区として企画をして、展開をしていく事業は当然必要だというふうにも考えてありますので、しっかりと企画をして展開をしていく。貸館という見方という今のご意見だと思うんですけれども、より自主的な、主体的な展開が図られているんじゃないかと考えているところです。","id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"そういうふうには見えない部分が私はあるので、もっともっと地域の声を知り尽くす努力というのは必要なんじゃないかなと思います。この利用状況にどういうふうに出ているのか、この件数はどうなのかというのがよくわからないので、その説明をお願いします。","respondent":"堀越生涯学習課長","answer":"平成１５年度前ぐらいまでは、３万５,０００件という年もありましたけれども、長期的に見て利用の増加は図られているのではないかと考えています。それに対しては一定の対応、いろいろなご要望等については、十分踏まえて上で対応させていただいていると考えております。","id":"exchange-057"},{"speaker":"南委員","kind":"確認","question":"最後に確認だけ。先ほど私が伺いたかったのは、上がってきていると見ていいのかどうか、その辺の確認だけして終わりたいと思います。","respondent":"堀越生涯学習課長","answer":"数字のほうから見させていただいて、非常に上がってきている、そのように私どもはとらえているところです。","id":"exchange-058"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"名称のことでちょっとお伺い、前にもちょっとお伺いしたことがあるんですが、文化センターのあり方も変わってくると思います。それと同時に、現状において文化センターの名前についてどのようなお考えを持っていらっしゃるか、教えてほしいと求めました。","respondent":"堀越生涯学習課長","answer":"いろいろな人材の発掘とか、それがまた地域の活動に展開をしていくような、こういった施設のあり方を考えていかなくちゃいけないと考えております。常に見直しというのは必要であろうと考えておりますので、今…","id":"exchange-059"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"この文面から見ると、今年度から、これはどういったことになるんでしょうか。教育委員会なのか、品川区という言い方しかないのでちょっとわからないんですけれども、これはどういう状況なのかをまずお聞きしたいと思います。","respondent":"富田学務課長","answer":"現在、準備を進めております校務システムというものの中で、学校からの保護者への一斉メール配信のシステムの導入を予定しています。スタートの予定は９月の運用開始を予定しておりますが、校務システムの検討メンバーがおり、６月中旬から運用開始する予定でありまして。","id":"exchange-060"},{"speaker":"西本委員","kind":"確認","question":"メールはメールでそのやり方があると思うのでいいんですが、６月ですから、緊急連絡の体制がとっていないんですよ、伊藤学園では。緊急ですから、確認も必要だし、そういういろいろなことを想定しながら検討をしているのかということですね。","respondent":"富田学務課長","answer":"現在、５カ所まで登録ができるということで、再送信またはその他の対応等々も可能な仕組みということを予定しているものであります。私どもが考えているのは、どういった電話網の検討をされるかというのは、問題もあろうかと考えているところです。","id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"これは要望で終わりたいと思いますけれども、これは学校の中での問題ですから、必要であればつくりましょうという話になるでしょうしね。そこは校長会等々でも主張していただきたいなと、これは要望で終わりたいと思いますけれども、要望したいと考えています。","respondent":"市川教育次長","answer":"当然のことながら、連絡を送る保護者の皆さんのご意見、意向というものもあろうかと思います。改めて文教委員会のほうに説明する機会があろうかと思いますので、ただいまご意見をいただいたことも踏まえて進めてまいりたいと思います。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/612972?Template=document&Id=4632#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":52623,"voices":158}},{"id":"h20-20080512-5","meetingId":"h20-cm05","date":"2008年5月12日","dateIso":"2008-05-12","committee":"総務委員会","time":"午後１時０３分～午後１時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"広報に３回の募集人員が載せられていましたけれども、実際に参加される皆さんにどの程度まで資料としてお示ししていくのかお聞きしたいと思います。それから、５００人、３００人という規模の中で、区長との意見交換等あるようですが、実際にどのような運営を考えているのかお聞きしたいと思います。","respondent":"中川原広報広聴課長","answer":"タウンミーティングは新基本構想の説明会ではありませんが、今後のまちづくりについて区民の皆さんと考え、率直にご意見を伺う場です。なぜかといいますと、当日にどのようにやるか一緒に準備を進めていくということも含めて、今年度は大きな会場でやろうと予定しているものです。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"当然新しく来られる方もいるわけですから、事前になるのか当日になるのかわかりませんけれども、資料の配布なり何なりが必要になると思うんです。皆さんに渡すべき資料は事前配布になるのか、その辺を説明を求めました。","respondent":"中川原広報広聴課長","answer":"区が取り組んできたものについてはビデオで共有化し、区長が今まで長期基本計画の中で説明しているようなデータとか、当日の中でも用意しております。広報紙でも基本構想について経過等を逐次お渡ししておりますし、必要に応じて資料を差し上げていくという形です。","id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"第２回品川区長期基本計画策定委員会で配られた別紙1)の資料は、前のものと中身は変わっていないということでいいか尋ねました。","respondent":"福島長期計画担当課長","answer":"数字が半年前からずれていたり、平成１９年度の結果がわかるものは載せたりですとか、最新のものをということで修正しています。別紙2)につきましては、出されたものをそのままという形です。","id":"exchange-003"},{"speaker":"浅野委員","kind":"質問・要望","question":"別紙3)の長期基本計画体系骨子（案）を拝見させていただきまして、どうしてもそちらのほうに引っ張られるようなことがあると思います。これは要望ですけれども、ぜひとも皆さんの考えを引き出せるような基本計画の論議にしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"武内副委員長","kind":"意見","question":"ほかになければ、との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"簡単なことですけれども、応募者が６９名で委嘱者が５０名、差し引き１９名の方は自己都合か何かで選ばなかったのか尋ねました。","respondent":"中川原広報広聴課長","answer":"区政モニター設置要綱で、区政モニターは５０名以内となっていまして、運営上そのような形で遂行しています。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"つまり、６９名を５０名に絞ったのですね。どのような考え方で絞ったのかということを伺ったんです。","respondent":"中川原広報広聴課長","answer":"地域割、年代割、男女別を考えまして、三つの要件を掛け合わせて、それぞれ別々に書いてありますけれども、そのようなところからバランスを取って選ばせていただいている形になります。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"つまり、地域と年代でバランスを取って、広く区民の意見を反映させるために選んだということですね。次回の応募には、優先されることを検討していただくことをお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"土井委員","kind":"質問・要望","question":"要するに、そのような皆さんはどうしていくのかという施策をしっかりしておかなければいけない、アイデアを提供されているのではないかと思います。ぜひその方向で、あるいはいろいろと区の関係を持っていただけるようにしていただけるようにお図りいただきたいという、お願いです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"原委員","kind":"質問・要望","question":"任期が１年から２年にされた状況を教えてほしいと求めました。長期基本計画の委員も３０名の中の関係も出てくるのかもわかりませんけれども、５０名を選んだときに、その辺を教えてほしいと求めました。","respondent":"中川原広報広聴課長","answer":"区民の声も毎年２,０００通ぐらいいただきますが、まず区の説明とか資料を出しまして勉強をしていただいて、そしてご意見をいただきます。施策への理解とか説明もただ慌ただしく言ってしまいまして、じっくりお付き合いをしていただこうということで任期を２年にいたしました。","id":"exchange-010"},{"speaker":"原委員","kind":"質問・要望","question":"私から要望ですけれども、これは昔から言われていることですけれども、やらせにならないような形を取ってお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"土井委員","kind":"質問","question":"逆の言い方をすれば、私たちがいただくのは暫定税率ではない、国が地方であるべき姿として交付するお金をいただくわけですから、何のあれもない。暫定ですから同じことが起こるわけなので、我々としてはしっかり持っていくべきものではなかろうかと考えていますので、意見を述べて終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問・要望","question":"つまり、この部分は国に何か要請していくとか、いろいろな事業を考えていくとか、対処を具体化していかないといけないわけではないですから。それに対して品川区ではどうするのかというところまで、しかるべきときには報告をしていただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"武内副委員長","kind":"質問","question":"ほかによろしいでしょうか。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"土井委員","kind":"質問","question":"本当に等価なのかどうか、どのような考え方でやられるのかということをお伺いしておきたいと思います。それとこれによって、区が固定資産税とか、要するに区の歳入なり何なりに全く影響がないのでしょうかという話です。","respondent":"伊勢総務課長、日下部企画財政課長","answer":"５月８日に説明に来たときに聞きましたところ、等価であると。解体の関係ですので、交換する土地の面積はもらうほうが大きくて、渡すほうが若干少ないという話でございました。 区民税につきましては、当然のことながら居住される以上は住民税が品川区に歳入されると、今のところはそのような形で見込んでいるところです。","id":"exchange-015"},{"speaker":"土井委員","kind":"質問","question":"少なくとも、ここは駐車場と住まいから商業的な用途に使われるということです。いただけてないとすれば問題ですが、そういうものですから、それがどのように見たらいいですかということも聞かせてください。","respondent":"日下部企画財政課長、市岡総務部長","answer":"それから２３区間で配分される際の算定というのは、収入額で算定されるという仕組みになっておりまして、ここに個別的にここで収入されたものが……。 固定資産税は評価額を基準にして課税されるものですので、間接的ですけれども、財調を通じて大きな税収のアップに寄与するということになろうかと思います。","id":"exchange-016"},{"speaker":"土井委員","kind":"質問・要望","question":"もう一つ、教えていただきたいんですけれども、国の部分と民間の部分が今までと比べると面積が変わるわけですね。例えば、国のところは税金を納めていただいているだろうと思いますけれども、納めていなかったら随分違うわけです。","respondent":"日下部企画財政課長","answer":"それに相当する部分を法律によりまして固定資産税相当分を別な形で交付するという別の法律がありまして、実質的には同額がそれぞれの自治体に収入されるという仕組みですので、その分が宙に浮いてしまうという形にはなってございません。","id":"exchange-017"},{"speaker":"土井委員","kind":"質問","question":"少なくとも大井競馬場のほうには面積的には小さい形で、というように聞こえたのだけれども、そういうことがあるのかなと思ってお伺いをいたしました。区には直接関係ないようなので終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"一部事務組合と東京都競馬株式会社との関係がよくわからないものですから、基本的なところを説明していただけますか。","respondent":"伊勢総務課長","answer":"東京都競馬組合は競馬事業を開催している形になりまして、開催場所が大井競馬場でございまして、大井競馬場の施設を所有しているのが東京都競馬株式会社です。","id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"施設を持っているのが東京都競馬株式会社ということであれば、品川区の資金が入っていて組合が運営されています。それとも全く別枠としてつくり上げられてきたものなのか、もう少しその辺を説明していただけますかとの意見を述べました。","respondent":"市岡総務部長","answer":"はその他の株主がいますが、２３区は競馬一部事務組合を通じて関与しているということで、直接株主ではない形を取っています。十分地元の要望を誠意を持って聞いていただくということを申し入れて、その旨、了解を得たという関係にあります。","id":"exchange-020"},{"speaker":"菊地委員","kind":"意見","question":"株主だとすれば、当然ここで競馬一部組合に入るか、それとも品川区に入るかよくわからないですけれども、そういう関係になっていくでしょうし。の損失が出てくれば、その損失についてもかぶさってくるのかなという気がするんですけれども、その辺をもう少し説明いただけますかとの意見を述べました。","respondent":"市岡総務部長","answer":"直接、２３区も競馬組合を通じて実質的には保有しているわけですから、そういう意味で区との関係が全くないということではありません。ただし、ここは本場所在区の品川区との関係が一番深いので、一番最初に品川区に対する説明があったです。","id":"exchange-021"},{"speaker":"原委員","kind":"質問・要望","question":"等価交換という会話が出てきたものですから、明確にお聞きしておきたいのですけれども、等価交換をしますという説明があったのでしょうか、文書上からいくと土地の交換をということになっているので、そこを教えてほしいと求めました。","respondent":"伊勢総務課長","answer":"品川区に説明に来たときも、等価で交換しますという話をお聞きしました。おおよそですけれども会社が出す平米数が約８,１００m2ぐらいだと、もらうほうが８,３００m2という形になっていまして、電話で話しております。","id":"exchange-022"},{"speaker":"原委員","kind":"質問","question":"国だろうと、区だろうと、民間だろうと、これは等価交換です。金額的に若干の数字の違いはあるだろうけれども、説明自体が金額的に等価なんだという説明で来たのでしょうかということだけを聞きたかったのです。","respondent":"伊勢総務課長","answer":"同じような金額になるということをお聞きしました。","id":"exchange-023"},{"speaker":"浅野委員","kind":"質問・要望","question":"地上６階建てということで、自転車での買い物も多いと思いますが、周囲の道路に車が車が並んでしまうようなことがないようにしていただきたい。それから、自転車が安全に通れるようなこともしっかり道路側を区側としても考えていただけないかなということを要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"武内副委員長","kind":"質問","question":"その他でほかによろしいでしょうか。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325034?Template=document&Id=1782#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":14701,"voices":60}},{"id":"h20-20080513-14","meetingId":"h20-cm05","date":"2008年5月13日","dateIso":"2008-05-13","committee":"行財政改革特別委員会","time":"午後１時０２分～午後２時１８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"の契約のあり方に関すること","agenda":"の契約のあり方に関すること","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"２点ほど教えてください。この必要がある場合というのは、例えばどういった場合を想定されているのか、説明を求めました。","respondent":"阿部経理課長","answer":"それは従来どおり委託等については品川区簡易型総合評価方式になっていくのだろうと考えています。２点目の落札者を決定しようとする時に、従来の法律は、一律にではなくて必要なときに聞くというふうに簡略化されたというものだと認識しております。","id":"exchange-001"},{"speaker":"阿部委員","kind":"確認","question":"工事案件のこれはやはり３,０００万円以上の案件という、そういったようなくくりになるんでしょうか、というのが前半に対して。その決定時にももう一回意見を聞くかどうかということを決めるという手続きでいいのかどうかというのを確認したい。","respondent":"阿部経理課長","answer":"ですから、金額で３,０００万円以上にするとかしないとか、その中身によってどういう総合評価をしていくかという形になろうかと考えています。今回は私どもが今申し上げたとおり、落札者決定基準に対する意見を聴取した時に、あわせて聞いています。","id":"exchange-002"},{"speaker":"阿部委員","kind":"質問","question":"逆に言えば、どんな工事でも必要ないという判断であれば、この先、実績がこの１件だけで終わってしまうということも仕組み上は可能なんですか。その辺の大まかな基準みたいなのは全く設けない中での発進ということになるんか尋ねました。","respondent":"阿部経理課長","answer":"今後は、先ほど申し上げましたけれども、工事につきまして総合評価方式を入れていくという流れは変わらないだろうと考えています。今回の一件だけではなくて、さまざまな工事に対応したものを総合評価方式を試行しながら決めていくということになるというふうに思っております。","id":"exchange-003"},{"speaker":"阿部委員","kind":"意見","question":"は運用で見てくれというようなことなのかなと思うんですけれども、これは今後についても運用の仕方を見ていかなければいけないと考えています。とりあえずそこまでですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つか教えていただきたいと思うんですけれども、そこに沿ってご説明いただけたらなと考えています。この流れの中で、こういうところでこうですよというのを教えていただけますか。","respondent":"阿部経理課長","answer":"もう１つは、今回の４ページ目の技術点の評価項目の公表の時期ですけれども、それはここの１ページの流れ図の３番目に説明会とあります。そのときにこれを公表して、参加している方に対しては公表をしております。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"どういう形で公開されるものなのか、教えてください。そこもご説明いただけますか。","respondent":"阿部経理課長","answer":"その参加者に対して、今申し上げたとおり、説明会で公表しているというものです。今回につきましては、もう既にこういう総合評価方式を行っております東京都建設局第二建設事務所の所長と、区の都市計画審議会の会長です。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"そうすると、この評価項目のほうは、参加者だけに公表するということでよろしいんでしょうか。１ページ目の落札者の決定方法のほうで、ここの考え方を１つ伺いたいのが、ここにどんなふうにかかわっているのか。","respondent":"阿部経理課長","answer":"ここにつきましては、４ページに技術点の評価項目の中に事業者の信頼性、社会性という欄があります。地域の区内業者の方の選択の項目を設けてありますので、こういう点については、区内の方の育成という観点も入れてあります。","id":"exchange-007"},{"speaker":"中塚委員","kind":"確認","question":"区内で頑張っている方々が、結果としてこれではじくような仕組みになってしまうとどうなのかなという思いで、ちょっと伺ったんですね。そこをもう１度確認させていただけますか尋ねました。","respondent":"阿部経理課長","answer":"ですから、これが固定しているということではございませんので、その辺は十分ご理解いただきたいと考えています。区内業者に限って参加をいただいているという場面もありますし、区内の産業の育成については十分配慮していると考えています。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"契約本体のここの違いのところがどういうふうにあらわれているのかと、あと１ページ目のところの流れにおいて、どこでどう変わってくるのかをお聞かせいただきたい。","respondent":"阿部経理課長","answer":"今回は地方自治法施行令に定められたような方式で行いますので、契約の形態につきましては、制限付き一般競争入札になるです。ただ、契約の形態としては随意契約になるというだけの違いです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"意見","question":"５０点、５０点のところの技術的なものも入れたという、もうちょっとそこのところをわかりやすく説明してほしいですとの意見を述べました。","respondent":"阿部経理課長","answer":"今まで行いました品川区簡易型総合評価は、委託契約について行ってきたというものです。簡単に言えばそういう委託契約か工事かという違いが一番大きいところと思います。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"それが１点。２ページのところにおいて、指名型もここの中に入っていくのかどうか、ちょっとその点を説明を求めました。","respondent":"阿部経理課長","answer":"あくまでも今回は試行ですので、何度か試行を重ねながら、本格的な実施に入っていくんだろうと思っています。まだはっきりはしてございませんけれども、かなり試行を重ねながら、工事についてはやっていく必要があるだろうと思っています。","id":"exchange-011"},{"speaker":"阿部委員","kind":"確認","question":"大変基本的な質問で恐縮なんですけれども、ここで工事総合評価方式と、これは地方自治法上は総合評価というのは工事に限定されたものなんですか。ちょっとそこを確認させてください。","respondent":"阿部経理課長","answer":"地方自治法施行令については、工事とか、あるいは委託とか、そういう区別はございません。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"工事総合評価方式と、あえて持ってきているのは、とりあえず品川区では工事案件にしか総合評価方式を入れないのだという意思であるのか。その後、また工事以外のものについても仕組みをつくっていくのだということなのか、ちょっとその辺を説明を求めました。","respondent":"阿部経理課長","answer":"今回が第１回目ですけれども、当面その試行を重ねながら、具体的に工事について本格的に導入できるのかどうか検討していくということになるというふうに思っております。","id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"これを区側に聞くのがいいのかどうか、前回の具体的検討事項のまとめの中で、学識経験者の意見を聞くなどというような提言をしているんですね。この提言というか、学識経験者の意見を聞いた簡易型総合評価方式と工事総合評価方式というのは、何か違いがそれでもあるものなんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"阿部委員","kind":"質問・要望","question":"今のは、純粋にその仕組みの説明を求めたものであって、文言をこれからどうしましょうということではないです。学識経験者の意見を聞いた簡易型総合評価方式というものは、何かそれでも違いがあるものなのでしょうかという、仕組みの質問です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"鈴木（真）副委員長","kind":"確認","question":"二、三点確認をさせてください。これは今度のケースも、前回の随意契約のときの委託に伴う契約のときの簡易型と一緒の点数配分ということでよろしいんか尋ねました。","respondent":"阿部経理課長","answer":"ちょっと説明が抜けましたけれども、合計１００点で、基本的には簡易型総合評価と考え方は同じです。簡易型については試行をしております。","id":"exchange-016"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"さっきのは価格点の点数配分の意味だったんですけど、要綱の中には、例えば８０％未満というのと、価格点５０点とかそういう項目がありましたね。今度の工事の総合評価方式、これをやっていく上で、今回は実施要綱をつくらないで試行するということの判断ということでよろしいんか尋ねました。","respondent":"阿部経理課長","answer":"実施要綱ということではなくて、総合評価方式を入れていくという、１件の決定でやっております。簡易型総合評価の委託のときと、形としては同様ですけれども、もう少しきめ細やかな決め方をしております。","id":"exchange-017"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"要するに簡易型のときの実施要綱の５０点、４８点という配分は今回は全く別個だよという考え方でいいということですね。それともう１点、総合評価方式は工事に関しては、簡易型というのはないよと考えていいわけですねとの意見を述べました。","respondent":"阿部経理課長","answer":"副委員長がおっしゃったとおり、簡易型総合評価は、工事については、なかなか適用は難しいだろうと考えています。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"価格点のほうもちょっと伺いたかったので、入札価格の予定価格というんですか、教えていただきたいのと。おそらく積算を積み上げていくんだろうと思うんですけれども、これに変わったことによって変更する点、しない点、そこをご説明いただけますか。","respondent":"阿部経理課長","answer":"予定価格ですけれども、方式としては今委員がおっしゃったように、積み上げをやってあります。予定価格が変わるのかということですけれども、この総合評価を入れたことによって変わるということはございません。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"なぜそう伺ったかというと、どういうふうに積み上げているのかなというのが、実感として疑問に感じるときもあるんです。どういうふうに積み上げているのか、そこが不透明に私は思うんですけれども、ちょっとご説明いただけますか尋ねました。","respondent":"阿部経理課長","answer":"予定価格が従来のものと変わるということはございませんので、それは契約の考え方が価格点だけではなくて、品質を確保していくと。ちょっと私、その辺の資料を持ち合わせておりませんので、どの程度積み上げているのかというのは、明確にはお答えできません。","id":"exchange-020"},{"speaker":"中塚委員","kind":"意見","question":"概略で結構ですので、どういうふうに積み上げていくのか、そこだけご説明いただけますか。どうしてもこの価格点のもとになる予定価格、そこがちょっとよく今までのご説明では見えてこないので、そこをご説明いただけますかとの意見を述べました。","respondent":"阿部経理課長","answer":"それは積算基準という技術的なものがありますので、それを参考にして積み上げていくですので、決して根拠なく積み上げているというものではございません。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"政令に従って、この随意契約のこの問題点を改善していく立場にあるというか、改善をされている中身であるというとらえ方でよろしいんでしょうか。その辺をぜひお聞かせいただきたい。","respondent":"阿部経理課長","answer":"もう１つは、そのときにもあったんですけれども、モニタリングをその後しますので、その中で履行能力、その辺は十分に調査をしていく。もし、十分な履行能力を持ったものについて委託契約を行うという形になりますので、そういう面では競争性は十分担保されているのかなと思いま…","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"随意契約であるけれども、競争性のところも加味をされてきているというふうに受けとめましたけれども、委託に関しての部分において、この簡易型というのがとれるというか、方向的に一般競争入札の方向に行くというか、そういった方向性というのは国のところではどうなんか尋ねました。","respondent":"阿部経理課長","answer":"例えば今回やりましたけれども、学識経験者の意見を聞いて、基準を決めてというのはなかなか難しいだろうと考えています。もう１つは、品川区簡易型総合評価が委託にとっては、今のところ一番ふさわしいものだと考えております。","id":"exchange-023"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"とすると、２番はこの２つの列挙ではなくて、工事総合評価方式を含めた３つの契約方式の列挙でもいいのかなと思うんですけれども、いかがでしょうか。１番についても同じことが言えるんですけれども、こっちにも入れるとなると、もう少しいじる必要があるかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"中塚委員","kind":"意見","question":"ぜひ３は３のより客観性を持った仕組みづくりとその公平性・透明性の云々かんぬんと、これはやっぱり大事な部分ではないのかなと思います。単純にくっつけてしまうと、上のほうにはこの「客観性」というところが、言葉としてはないので、そこだけ述べさせていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"高橋委員","kind":"意見","question":"ちょっとお尋ねしたいんですが、こういう３番みたいな文言があったほうがいいのか、ちょっとそこがわかりませんのでとの意見を述べました。","respondent":"阿部経理課長","answer":"委員、おっしゃったとおり、今後も工事については総合評価方式の試行はしていくと考えております。","id":"exchange-026"},{"speaker":"阿部委員","kind":"提案","question":"１番についても、要は１番と２番のこの課題について、総合評価方式も提言の対象にしてはいかがなものかという提案をさせていただきました。１番などは価格や履行能力については、全く総合評価方式でも同じことですから、１番と２番について提案をさせていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"鈴木（真）副委員長","kind":"提案","question":"阿部委員の提案はわかりました。２番は実施している部分、ご提案いただいたんですが、個人的には３番の試行ということで仕切ったほうがいいのではないかなという気がしておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"中塚委員","kind":"意見","question":"私も今、副委員長からお話がありましたけれども、確かに３番は試行についてで、こうですよということなので、そういう意味では１と２とは違うものになってくるのかなと思うので、さっきははっきり言いませんでしたけれども、別のものではないかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"１年間副委員長を務めさせていただきまして、ありがとうございました。ありがとうございましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/817079?Template=document&Id=5838#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":17698,"voices":72}},{"id":"h20-20080514-16","meetingId":"h20-cm05","date":"2008年5月14日","dateIso":"2008-05-14","committee":"街づくり特別委員会","time":"午後１時０４分～午後３時２２分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"「東京都観光汽船（株）による水上バス運航の終了」","agenda":"「東京都観光汽船（株）による水上バス運航の終了」","exchanges":[{"speaker":"南委員","kind":"質問","question":"そういう認識は区のほうは持っているのかどうかと、そういう依頼をしている、打診をしている。そういうことは来館者の引き上げ、多くする、そこに効果があるというふうに品川区としては見ているのかどうか、その辺の認識を伺いたいと思います。","respondent":"藤田道路公園課長","answer":"多様なお客様が多様なルートを確保することで水族館に来てくれるということもやはり考えられますので、私どものほうからもお願いにも限界があります。私どもとしてはいろいろな形で情報提供をして、お話をして、確保を図っていきたいというふうに考えているところです。","id":"exchange-001"},{"speaker":"南委員","kind":"意見","question":"こういう状況の中でどうこうと言うつもりは全くないですけれども、今の状況のときには難しい状況があるんじゃないかなというのは思いますので、そのことは意見として伝えておきたいと思いますとの意見を述べました。","respondent":"藤田道路公園課長","answer":"すいません、区がこれに対して例えば委託をしてお金を払っていたとか、そういったことは一切ございません。今後の観光協会等への今の打診についても、現段階で区の持ち出しを前提とした検討をしているものとは違うです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"してほしいみたいな、そういう言い方が言下にあったのかなというふうに思って聞いていたものですから、その辺伺ってみたわけですけれども。なかなか社会状況があってのことなので、難しいかなというのは私としても思っておりますということだけ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"これは要望しかないんですが、品川区の魅力は、湾岸から見た品川区の景観も私はすばらしいものがあると思います。ぜひいい形で尽力していただきたいというお願いだけしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"稲川委員","kind":"質問・要望","question":"１点だけお伺いしたいんですけれども、３,０００万から４,０００万ぐらいになっているんですけれども、わからないですけれども。なぜここでこれだけの開きが出ちゃっているのか、もしわかれば教えていただきたいことと、４番の水上バスステーションの利用料の収入。","respondent":"藤田道路公園課長","answer":"設置をしたものを利用するということで、船が着くことに、接岸というんですかね、そのために発生する費用です。１ｔ当たり１３円４０銭ということで、私ども、その船が１日何回着いてもその値段は変わらないというような料金設定で行っているものです。","id":"exchange-005"},{"speaker":"稲川委員","kind":"質問","question":"もしそうでなくて、このためにつくっているのであれば、なぜなのかなというあれがあるんですが。例えば、今後、水上バスステーションの利用というのは、どういう利用が今後考えられるか、説明を求めました。","respondent":"藤田道路公園課長","answer":"ステーションはつくるけれども、どこも利用者が見込めないというような形で着工するというわけにもいきませんので、見込みが立ったということで。これからも水族館である以上はずっとそういった利用も継続していますので…","id":"exchange-006"},{"speaker":"稲川委員","kind":"質問","question":"最後に１点。民間がもし使用したときの使用料だけ説明を求めました。","respondent":"藤田道路公園課長","answer":"昨年も観光協会を通じて屋形船が出たといったようなケースもありますので、そういった利用についてはあります。それから、民間であろうが、どういった施設であろうが、東京都観光汽船も民間会社ですので、１ｔ当たり１３円４０銭という基準は変わりございません。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"５００名の席にスロープをつけて２００名になってしまうという話もありますけれども、これは船自体を取り替えなくちゃいけないという部分が発生するのかどうかということと、わかる範囲でいいんですけれども説明を求めました。","respondent":"藤田道路公園課長","answer":"そのうち旅客船、船については、２０１０年までに船の５０％についてはバリアフリーの対応にしなければいけないというような法律になってあります。全然違う事業者ではルートをやめたり、こういった水上バスの営業から撤退をしてしまったと、そういったような例も聞いてあります。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"住民サービスも含めて、どういう効果を求めてやるか。あんな言いわけみたいなことを言わないでと思うんだけれども、どう思うかということを聞きたい。","respondent":"岩田まちづくり事業部長","answer":"いわゆる足としての重要性を考えていたわけですけれども、やはり東京都民を含め、間違いがございません。こういったせっかくある桟橋をできるだけ広く開放して、利用していただくような方策を今後いろいろ考えていきたいと、こういう意味です。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もちろん競艇場もあるからそんな簡単にはいかないかもしれないけれども、あそこへ行けば、いい入り江になっているじゃないですか。これはお願いだけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"西本委員","kind":"確認","question":"確認だけしたいと思います。東京都観光汽船にお願いをしたということで、品川区の動きは何もなかったのか、何かあったのかなというところが一つ気になるところなんですが。","respondent":"藤田道路公園課長","answer":"平成７年から運航を開始したわけですけれども、それから、周遊便のような形も当時はあったというふうなことで確認しています。修学旅行とかで船に乗りたいというお話があったときに、水族館とセットで動かしたというようなこともあったというようなことで聞いてあります。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"観光という視点で利用するというような動きは過去にあったんでしょうか。それとも全くなかったということの理解でいいんか尋ねました。","respondent":"藤田道路公園課長","answer":"例えば区の皆さんをご案内するとかいったときも、基本的には水上バスに乗っていただくというような形でやられていたのが基本のようです。今後は、観光アクションプランとかもできてありますので、その辺と連携を図っていくことも非常に大切なことだというふうに感じてあります。","id":"exchange-012"},{"speaker":"西本委員","kind":"意見","question":"どういう形で観光協会に。どういう形で今依頼をしているのかとの意見を述べました。","respondent":"藤田道路公園課長、岩田まちづくり事業部長","answer":"その中で、１つは定期運航ができるか、できないか。今のところ、観光協会のほうからは、区内の歴史館などと連携したような形で、プランニングを今進めているようなことは聞いてあります。 先ほどもお答えしましたけれども、これだけ２３区の発達した鉄道網、極めて難しい話なんですね。あるいは天王洲にも地元が設置した桟橋もあるわけですから、観光でもいいですし、こういうふうにご理解いただきたいと思います。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"であるならば、ある程度の経費の負担というのは当然あると思いますので、当然少なくするというのは、削減しながら……。そういうのも必要なのかなというふうに思いますので、有効的に使っていただきたいということで要望をしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"}]},{"id":"topic-02","title":"特定事件調査の「新・水とみどりのネットワーク構想」","agenda":"特定事件調査の「新・水とみどりのネットワーク構想」","exchanges":[{"speaker":"南委員","kind":"質問","question":"とりわけ上流域の自治体の対策というのはどういうふうになっているのか改めてちょっと、不勉強なところがありまして、教えていただければと思うんですけれども。","respondent":"家壽田下水道河川課長","answer":"ただし、これはかなり時間もかかりますし、速効性のある対策がなかなかできない。なかなか速効性がないという状況です。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"処理場での処理の用地が今どうこうということでのお話だったんだけれども、世田谷区自身の、目黒川という名前で呼んでいいんですか。世田谷区自身の対策、とっている対策があれば、どういうものなのかというのを、今の説明ではわからなかったので。","respondent":"家壽田下水道河川課長","answer":"これは２級河川なんですが、晴天日に全部汚水が入ってくる、暗渠化された下水道幹線になっております。目黒川浄化の３区連絡会という中で、検討、必要に応じて協力もしています。","id":"exchange-016"},{"speaker":"西本委員","kind":"確認","question":"ちょっと確認です。それだけ説明を求めました。","respondent":"家壽田下水道河川課長","answer":"５分の１とお考えいただきまして、設置と、この５倍の金額。ですから、１億ちょっとのお金が５年間にかかる総費用というふうにご理解いただければと思います。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"そうすると、これは、毎年毎年の継続して２,５００万ということで、それがずっと続いてくよ。例えばリース期限が伸びると、イニシャルコストがどんどんかかってくるという形になってくるんか尋ねました。","respondent":"家壽田下水道河川課長","answer":"５年間で今回の機械を使い終わるという前提で考えておりまして、耐用年数はあと２年残っておりますから、また改めて検討していきたいというふうになると思います。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"修理費とかいうのは多分、状況によっては、壊れてしまうとかいろいろあると思うんですが、それは、例えばそれも入った値段なのか。それプラスアルファ幾らか、そういう形でかかってくるのか尋ねました。","respondent":"家壽田下水道河川課長","answer":"ただし、立会川、昨年９月にあったような集中豪雨で物が流れてしまったり、壊れてしまうことがあるかもしれません。当方のほうでも若干河川の維持の予算を持っておりますので、業者側と協議した上で必要な対応をとっていきたいというふうに考えております。","id":"exchange-019"},{"speaker":"安藤委員","kind":"意見","question":"来年度あたりにその２つの結果を見て、そのスケジュールのほうもわかったらお願いしたいのと、まずそれをお願いしますとの意見を述べました。","respondent":"家壽田下水道河川課長","answer":"新しくつくるのと違いますので、早くできる予定でして、できれば６月ぐらいにセットをしたいなと。今年度の結果、実験の結果を見た上で、来年度以降判断していきたいと考えております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうものを求める人というのはすごく多いなというふうに感じているんですけれども、これを通してどう良好な緑環境というのを区内に実現していくかというふうなことで、どう利用してほしいかとかいう考え方をお聞かせ願いたいんですけれども。","respondent":"松代管理工事課長","answer":"区の基本の計画たるものは今進めております基本構想、基本計画というもので、実施計画を練りながら具体的な施策をやっております。行政が主体としてやる施策も当然いろいろと今後も進めてまいりますけれども、いろいろと、ここに記述しております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"意見","question":"啓発というか、そういう気運を高めていくような方向でどんどん、恐れずに知らせていってほしいというか。行政にどういうことをしてもらいたいかとか、そういう方向で活用していただければなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"底辺部の汚泥についてどう考えているのかをお聞きしたいのと、ちょっとお聞きしたいんですが、そこから回避していなくなるんですか。それとも、実際、急激に雨でも降って、酸素がゼロ近くになったときには、そこで死んでしまうんですかね。","respondent":"家壽田下水道河川課長","answer":"結局、雨が降るたびにその現象が繰り返されるということで、なかなか汚泥に着目した浄化対策というのは実際のところ難しいと思います。なりますので、年間何十回と雨は降りますので、現実的にはそれがなかなか難しいという状況です。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこら辺のところを再度教えていただきたいのと、この拠点イメージ図はいいんだけれども、これはこれでいいんだ。そこら辺の気持ちがあれば、教えていただきたい。","respondent":"岩田まちづくり事業部長、松代管理工事課長","answer":"予定では五、六年すれば、１滴も落ちてこなくなる。ただ、もう少し抜本的な、海水導入も含めた対策をやはりやらざるを得ないだろうというのが今の段階で考えていることです。 いつごろまでにですけれども、今後、この構想に基づいて、先ほどご説明しましたように、長期基本計画等の中で具体的に施策を打ち出してまいります。計画をつくって、そのためにいろいろな角度から全力を挙げて取り組んでいきたいと…","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"簡単でいいんですが、契約に対してですけれども、５月中に仮契約だということですが、このやりとりは区の中ではどこが担当の窓口か尋ねました。","respondent":"松代管理工事課長","answer":"窓口は都市計画課街路事業担当のところに、４月から新しく用地担当を主に専任する管理職がおりまして、そこのところで今交渉をしています。都市計画課街路事業のところです。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"要は契約の中にはそれが、自由に使ってくださいよという形になっているのか、そこの折り合いというのはどうなって。自由に使える形か尋ねました。","respondent":"松代管理工事課長","answer":"直近で仮契約を結びますので、その仮契約とあわせてこういう整備計画を進めますということは先方にも説明をして、了解を得ております。仮契約を結んだ時点で、整備の準備等を進めさせていただいてよろしいかということで了解を…","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"そう見ると、これも含めてこの全部のやりとりというのは、さっき言った都市計画課が全部やりますよということの理解でよろしいんですね。それで、あと、さっきの部分は、こういう使い方でやっていくよということで了解を得ているという形でよろしいということか尋ねました。","respondent":"松代管理工事課長","answer":"今後こういう計画を持っているということでの話し合いと、あわせて賃貸借契約を結んで管理をするという話と、並行してやってあります。そういった意味では、先方も契約を前提として、了解のもと、承諾を得て進めておるものです。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/183026?Template=document&Id=6364#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":32629,"voices":74}},{"id":"h20-20080520-8","meetingId":"h20-cm05","date":"2008年5月20日","dateIso":"2008-05-20","committee":"建設委員会","time":"午前１１時０１分～午後３時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759088?Template=document&Id=3910#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":1367,"voices":8}},{"id":"h20-20080527-6","meetingId":"h20-cm05","date":"2008年5月27日","dateIso":"2008-05-27","committee":"区民委員会","time":"午後１時１６分～午後１時３７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"の１、議案審査","agenda":"の１、議案審査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"２点目の改正項目についてなんですけれども、確認なんですけれども、いわゆるエンジェル税制の拡充の中での改正ということでよろしいんでしょうか。それから、あわせて確認の意味も込めて、エンジェル税制とは何なのか、エンジェルとはだれを指すのかも含めて、ちょっと教えていただきたいんです。","respondent":"武内税務課長","answer":"１点目については、委員のいわれたとおりです。日本でも、１９９７年からエンジェル税制ということが取り入れられて、ベンチャー企業と言われるところの投資を優遇しているです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一つの確認なんですけれども、改めて、ここで言うベンチャー企業の定義を教えていただきたい。ちょっとその疑問があったもので、お伺いしたいと思います。","respondent":"武内税務課長","answer":"それは上場株を買ったからでしか恩恵を受けることはできないですね。これは所得税の部分だけです。","id":"exchange-002"},{"speaker":"飯沼副委員長","kind":"質問","question":"今、エンジェル税制のことで、エンジェルは個人投資家というお答えだったんですが、個人投資家というのは範囲があるんでしょうかね。それから、付則第１４条に該当するケースであると、区が判断するのは、どこでどのようにするのか説明を求めました。","respondent":"武内税務課長","answer":"どのぐらい減税になったのかということですけれども、区のほうで申告を受け付けているわけではありませんので、把握をしておりません。自動的に国税で幾ら、地方税で幾らという内訳が出ているのと同じように、それは国の機関のほうで取り扱いをしているです。","id":"exchange-003"},{"speaker":"飯沼副委員長","kind":"質問","question":"区のほうで把握をできるシステムになっていないと。この間の質問の中でも、少し中身を教えていただいたんですが、中小企業の資金繰りの応援になっていくというとらえ方でよろしいのか尋ねました。","respondent":"武内税務課長","answer":"３年後の譲渡益というのが、ベンチャー企業に投資するのが、ほかの国に比べて少ないということは聞いております。購入当初に、優遇政策で、ベンチャー企業への投資を個人投資家が利用しやすいような形にしたと聞いております。","id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"確認","question":"一つだけ確認で、国のほうの政策転換というか、その部分はもう既に行われているんですよね。間があくのではなくて、もう既に行われているという理解でよろしいんか尋ねました。","respondent":"武内税務課長","answer":"このシステムは、４月１日から制度として始まっているということです。","id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"前回の委員会の報告で、住宅ローン控除のほうの対象者の数字を伺った際に、４月末で２,６５１人いらっしゃると。数字の変動など等、見込みがあれば、伺いたいと思います。","respondent":"武内税務課長","answer":"６月９日に賦課決定した後、７月に再度コンピュータで申請漏れの方を抽出しまして、その方に申請をすすめるようなことをします。その予測は数百人とさせていただいて、５月からの申請は、まだ１件も受け付けておりません。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"確認","question":"もう一遍確認で、６月９日の賦課決定の後で、なされるという解釈をしてよろしいんでしょうか。確認です。","respondent":"武内税務課長","answer":"購入した年から１０年間の引き続きの控除になりますので、来年また、その年度分を申請することは当然できるわけです。平成１８年度に購入された方については、平成２７年まで続きますので、また手作業なりで漏れのないように抽出していきたいと考えております。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"自民党といたしまして、賛成という表現ですか、それとも承認という表現でしょうか。自民党会派としまして、承認ということでお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとその理由を述べさせていただきたいんですけれども、この改正項目１については、必要であり賛成という立場です。したがって、今回、専決処分された条例の改正に対して承認です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]},{"id":"topic-02","title":"でございますが、委員長報告","agenda":"でございますが、委員長報告","exchanges":[{"speaker":"飯沼副委員長","kind":"質問・要望","question":"１年間を振り返ると、区民の生活実態が、ここでいっぱい論議を戦わせるような議会の活性化がまだまだ求められているのかなと考えています。理事者の皆さんも、１年間、ほんとうにありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/798229?Template=document&Id=2516#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":6377,"voices":31}},{"id":"h20-20080527-5","meetingId":"h20-cm05","date":"2008年5月27日","dateIso":"2008-05-27","committee":"総務委員会","time":"午後１時１８分～午後４時２０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"武内副委員長","kind":"質問・要望","question":"なお、お手元に平成２０年陳情第４号の写しを配付しております。これは、議長より参考送付を受けたものですので、後ほど、各自ご覧ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"武内副委員長","kind":"意見","question":"予定表の１、議案審査に係わる現地を視察に参りますので、委員および同行される理事者は、第３庁舎前のマイクロバスにご乗車ください。○午後１時２０分休憩 1)第三日野小学校改築工事予定地視察場所：2)第一日野小学校・幼保一体施設および（仮称）教育複合施設改築工事予定地…との意見を述べ…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"この辺、どう受けとめればいいのか、まずそこを教えていただきたいんです。この後の流れといいますか、全体でほぼ９６億円ぐらいになりますので、どういうふうに入ってくるのかということを教えてほしいと求めました。","respondent":"阿部経理課長、市岡総務部長","answer":"２カ年の中でやらなければいけない工事ですので、非常に厳しい工期です。後で説明しますけれども、その前の４月には新しい校舎に移るという形になりますので、工期の問題が一番大きいです。 子どもたちの学期、あるいは学年の当初から新校舎を使って学校行事、あるいは授業等を開始したいというのが最大の理由です。子どもたちのことを考えて、なるべく改築時期を早くしたいということで、こういう工程をとったものです。","id":"exchange-003"},{"speaker":"菊地委員","kind":"意見","question":"２年の債務負担行為って、第１回定例会で出すと、そうじゃなくなるというわけではないんですよね。ちょっと、そこをもう少しとの意見を述べました。","respondent":"市岡総務部長","answer":"原則どおりこういうステップをとることが、そこはしっかり堅持した上で、なるべく早く供用開始をしたいという考え方であります。たしか４月の第１週に、それに比べると、若干ですが準備には十分に時間をとれたです。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"そういうことではなくて、かなり大きな工事ですから、今の時期に手をつけていくということそのものをどのように受けとめればいいのか。この辺もちょっと、お聞かせ願えればと思います。","respondent":"日下部企画財政課長","answer":"学事制度審議会は、今検討しておりますけれども、それ以前の規定方針として準備を進めてきたという経過もある。今、検討を進めているということで、少し切り分けてご理解をいただきたいと思います。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"それから、第三日野小学校が全体では２６億円ぐらいでしょうか。新しい公共事業として９０億円余りのお金が流れて行くとすれば、実際には、この辺の辞退の状況というのを教えてほしいと求めました。","respondent":"阿部経理課長","answer":"私どもとしては、建材、鉄鋼関係が値上がりしているという認識しております。辞退が出るということは残念ではありますけれども、私どもとしては、精いっぱい業者の方には努力していただいたと評価しております。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"どういうふうに改善をしていくのかというと、結局、それでも追いつかないという受けとめでいいんでしょうか。もう一度、そこら辺を。","respondent":"宍戸施設担当課長","answer":"予定価格をこちらで算定するんですけれども、５月１日付でも、６月１日付でも変えるというような部分的な改定を加えているところです。やはり予定価格については、こういうふうな物価がどんどん急激に上がっているときには、どうしてもやや追いつかない。","id":"exchange-007"},{"speaker":"浅野委員","kind":"提案","question":"全体で三つの提案が出ているんですけれども、平成１４年５月の計画に基づいて、ほかの市区町村でも計画を立てて行われていると思うんです。そういうようなものがあってずれたとか、そういうことって今まであったのかどうか、ちょっとお伺いしたいんですとの意見を述べました。","respondent":"日下部企画財政課長","answer":"改修ともに、補助金としての弾力性等も含めまして、比較的使いやすい形で補助金が交付されてきている。そして、少し厚みも増しつつあるというような状況です。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"２年のうちに価格がどのようになるのか、前にもこちらの席でも出ていたと思うんですけれども、今回は考慮をしていくのか。それともまた、特に考慮せず、当初の価格どおりやってもらうようになるのか、ここら辺を、ちょっと教えてほしいと求めました。","respondent":"阿部経理課長","answer":"国のほうで、国土交通省を中心として、そういうルールをどうしていくのかというようなことを検討していると聞いております。この契約金額の変更というのは、２３区を含めまして全体の問題ですので、国の検討状況を注視していきたいと考えています。","id":"exchange-009"},{"speaker":"浅野委員","kind":"意見","question":"これからどうなるかと思うんですけれども、業者ともうまくいい関係をつくりつつ、いい物件をつくってもらうように努力してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"土井委員","kind":"確認","question":"どうにもならなかったとかということが、小さい工事なんかにもありますので、ちょっとそこら辺をお伺いしたい。総合的な発想であるかどうかは別なんですけれども、ちょっとお伺いしたいんですが、そういうものはないと見てよろしいんか尋ねました。","respondent":"阿部経理課長、宍戸施設担当課長","answer":"１点目のご質問です。ここには５社というか５組といいますか、その方がＪＶを組んで参加なさって、委員おっしゃったように、結果として、３社が辞退をしたです。 非常に危険性があるという吹き付けアスベストについては、一切ございません。成形板については幾つかあるんですけれども、それも法に基づいてきちっと処理するということで考えております。","id":"exchange-011"},{"speaker":"原委員","kind":"質問・要望","question":"同じような質問になってしまうかもしれないんですけれども、第三日野小学校ということなんですけれども、ちょっと質問させていただきたいんです。これがいい、悪いということではないので、工事発注者としての意見があれば、また、ちょっと感想的なものがお聞きしたいんです。","respondent":"阿部経理課長","answer":"資材が上がっているは確かですので、その辺の関係から、ぎりぎりの価格が出てきてのかなと考えています。ただ、先ほども申し上げましたとおり、業者が辞退されたというのは、私どもとしては非常に残念だと考えています。","id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"私自身が指摘をさせていただきたいのは、やはり区民の税金でやるわけですから、品川区が被害をこうむらないような形で工事をやっていただきたい。そこのところについて、もう１回。","respondent":"本間副区長","answer":"経理課長が説明しているような、いろいろな資材の高騰等厳しい状況の中での、本体工事の応札状況になっているということです。区民の利益になるような、そのような予定価格を公表しているという状況からの面もあるとうことは、ひとつご理解いただきたいと思います。","id":"exchange-013"},{"speaker":"菊地委員","kind":"質問","question":"ちょっとお聞きしておきたいんですけれども、まだ手がつけられていない小学校、中学校が何校かあるように思うんです。小・中学校でどのぐらいあるのか、教えていただけますか。","respondent":"宍戸施設担当課長、市岡総務部長","answer":"小中一貫校ができ始めていますので、どういうふうに数えるのかというのは非常に難しいんですけれども、平成２０年度までに、耐震工事もやっていない、改築予定もないという、平成２１年度以降対応の学校が１２校あります。 品川区の小・中学校の耐震については、かつて、平成１４年のときに耐震化の方針を出しました。優先度の高いところから計画的に、順次、すべての学校の耐震化を進めるという方針です。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"今、おっしゃられたことは、以前にもお聞きしました。ということは、今のお話だと、１２校すべてが、その直前の改修の中で行われたので、現状で残っているんだというふうにとらえていいんか尋ねました。","respondent":"宍戸施設担当課長","answer":"それによる不調というのが、平成１５年度も、ほかの区に見受けられました。平成２０年度は夏休みの耐震改修工事は１１校にさせていただいているんですけれども、そういう形で振り分けさせていただいているというものです。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"地元の要望でずらしているとかというお話があったんですけれども、中国での地震は、ああいう状況が絶対に起きませんという保証はないと思うんです。危ないということで基準が変えられたわけですから、明日そういう地震がくるかもしれないわけですから、そこら辺はどうなんか尋ねました。","respondent":"日下部企画財政課長","answer":"最重要課題として、今、区としても取り組んでいる状況でもあります。区としては、やはり早急に耐震改修を進めていくという基本方針に変わりはございませんので、その辺については十分にご理解いただきたいと思います。","id":"exchange-016"},{"speaker":"武内副委員長","kind":"意見","question":"これより、第３０号議案、第三日野小学校改築工事請負契約について、採決をいたします。ご意見がありましたら、お願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問・要望","question":"やっぱり最後にお聞きした学校耐震の問題で、そこで出ていた地元の要望だとか、きっちりと早急に行うべきものだと思うんです。もう１点は、こういう議案の場合、全体の流れそのものを打ち出しながら出されることが必要なのではないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"武内副委員長","kind":"意見","question":"よって、本案は原案のとおり可決決定いたしました。〔「異議なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"武内副委員長","kind":"意見","question":"よって、本案は、原案のとおり可決決定いたしました。〔「異議なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"武内副委員長","kind":"意見","question":"よって、本案は、原案のとおり可決決定いたしました。〔「異議なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は、原案のとおり可決決定いたしましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"他の会社が辞退をして、ある意味、一つの会社に決まったということになるわけですから。ですから、事実がこうなわけですから、これから庁舎の耐震という大きな工事が出てくるわけですから。","respondent":"阿部経理課長","answer":"副区長からもご答弁申し上げたとおり、厳密な積算を行いまして、その結果の金額を予定価格として公表しているものです。ですから、辞退したかどうか知らないという状況ですので、その意味では、競争性の確保という意味では、十分に確保されているとは思っております。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これだけの大きな工事をやるに当たって、これでいいんですかと、素直に。５社ぐらいあって、結果として１社が辞退をしたということになっているわけですから、ぜひ追求してくださいということをお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"菊地委員","kind":"意見","question":"確かに金額的にも全然違う部分があるんですけれども、その辺の違いはどういうふうに見ていらっしゃるのか。それだけとの意見を述べました。","respondent":"阿部経理課長","answer":"先ほどからご意見が出ておりますけれども、本体工事につきましては、資材の関係のことが、辞退が多いということと関連しているのかなとは思っています。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"確かに、これまでの話だとそういうことなんでしょうけれども、ただ結局は、今のご答弁だと、総務委員会で、これまでもいろいろな形でこういう意見が出されたけれども、そこは全然変わっていないし、変えようがないんだというとらえ方をしてもいいんですかね、私のほうは。","respondent":"宍戸施設担当課長","answer":"うちの区は見込みも含めてこうします、こういうふうな事態を踏まえて、国でどうするかということになります。一定の決まりがあるので、その枠の中でしか動けないという苦しさはあるものです。","id":"exchange-026"},{"speaker":"土井委員","kind":"質問","question":"そのかわり、ちゃんと責任を持った業者が入ってくる、目に見える業者がやるわけですから、むちゃくちゃなことはやらないと。ここのところは僕は悩むところなんですけれども、どうお考えでしょうか、ちょっと聞かせてください。","respondent":"阿部経理課長","answer":"先ほども説明がありましたが、第３グループにつきましては区内の業者という形で、区内業者の育成を図っているです。区内業者を優先しながら育成していくと考えておりまして、今後も、ＪＶについてはそういう形で取り組んでまいりたいと考えております。","id":"exchange-027"},{"speaker":"原委員","kind":"質問","question":"私なんかは、地域の方からよく伺うのが、工事は大丈夫なのかと。いろいろな問題があるエリアですから、その辺について、一言お話を伺いたいと思います。","respondent":"宍戸施設担当課長","answer":"区内でも３０位以内の、ランクとしては非常に高い会社で、技術力も確かなものがあると考えております。十分工事会社とも練って、十分な説明をしてご安心いただいた上で、実際の工事にかかればと考えております。","id":"exchange-028"},{"speaker":"武内副委員長","kind":"質問・要望","question":"それとも、単純に記入ミスなのか、それを教えていただきたい。ほかは大体８億円台なので、なぜこんなに安くできたのかがわかれば、その２点を説明を求めました。","respondent":"阿部経理課長","answer":"１点目、申しわけございません、記入ミスです。２点目の、電気設備工事ですけれども、積算等は変わりございませんので、落札者がどうしても工事を取りたいという意欲なのかなと思います。","id":"exchange-029"},{"speaker":"武内副委員長","kind":"質問・要望","question":"きっちり品川区のほうで考えている内容がちゃんと担保されて、履行されるようにお願いしたいと、これは要望させてほしいと求めました。ほかによろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"武内副委員長","kind":"意見","question":"これより、第３４号議案、第一日野小学校・幼保一体施設および（仮称）教育複合施設改築工事請負契約について、採決をいたします。〔「異議なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"武内副委員長","kind":"意見","question":"よって、本案は原案のとおり可決決定いたしました。〔「異議なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"武内副委員長","kind":"意見","question":"よって、本案は、原案のとおり可決決定いたしました。〔「異議なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"武内副委員長","kind":"意見","question":"よって、本案は、原案のとおり可決決定いたしました。〔「異議なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は、原案のとおり可決決定いたしましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"菊地委員","kind":"質問","question":"生徒数との関係で、これで回っていくものなのかどうかというのが、ちょっとわからないところなんです。生徒数なんかも、わかれば教えてほしいと求めました。","respondent":"宍戸施設担当課長","answer":"生徒数としては、現在、６４８人です。うまくきちっと一つで成立するという計算は、当然、教育委員会のほうでやっていると思っています。","id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"地域開放は重要な部分ですけれども、ずっと一貫校のプールをつくってきているんであれば、かなり無理が生じているのではないのかなと思うんです。夏休みだろうと何だろうと利用できる体制で考えるべきなのではないかなと、今のプールのあれを見て思うんですけれども、どうなんか尋ねました。","respondent":"宍戸施設担当課長","answer":"したがいまして、屋外のプールで、天候を気にしながら使うよりも非常に有効に使えていると聞いております。そういうふうに、そのほかの期間に非常に安定してカリキュラムが組める関係上、夏休みに開放しても全然支障がないと聞いております。","id":"exchange-037"},{"speaker":"菊地委員","kind":"意見","question":"やっぱり施設としてつくっていく以上、そこはやっぱり改善すべき部分ではないかなと思うんです。二つつくるのか、三つつくるのかは別としても、施設としてはやっぱり、そこは考えるべき部分ではないかなと思うんですとの意見を述べました。","respondent":"日下部企画財政課長","answer":"教育委員会のほうとしても、十分にそういうバランスをとりながら、施設の有効活用を図っていく。その辺の基本的な考え方というのは、そういうご意見があったということで受けとめていきたいと思います。","id":"exchange-038"},{"speaker":"菊地委員","kind":"質問・要望","question":"学校施設ですから、夏休みだろうと何だろうと、子どもたちがまず中心になって利用できて初めて有効活用なんだと思うんですよね。先ほどの施設担当課長ではないですけれども、そういう話を漏れ聞いておりますので、ぜひそこはよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これからつくっていくわけですから、そういうこともぜひ視野に入れて対処してくださいというお願いだけしておきます。それについては、ちょっと答弁をいただいておきましょうか、まだまだ検討の段階ですかね。","respondent":"福田企画部長","answer":"ご質問の趣旨につきましては、教育のあり方というふうに理解することができますので、私どもは私どもなりに、それから、教育委員会事務局にも、その旨をお伝えをして、どういうふうにできるのか検討させていただきたいと思います。","id":"exchange-040"},{"speaker":"菊地委員","kind":"質問","question":"この間、とりわけ学校施設をまず最初に住民の間でどうしていくかということも論議をされてきましたし、一定の特殊性のある地域なのかなと思います。ですから、果たしてどうなのかという検証を明確にすべきであると思いますし、この議案について賛成すると言えると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"武内副委員長","kind":"意見","question":"これより、第３８号議案、小中一貫校八潮学園建設建築工事請負契約について、採決をいたします。〔「異議なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"武内副委員長","kind":"意見","question":"よって、本案は原案のとおり可決決定いたしました。〔「異議なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"武内副委員長","kind":"意見","question":"よって、本案は、原案のとおり可決決定いたしました。〔「異議なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"武内副委員長","kind":"意見","question":"よって、本案は、原案のとおり可決決定いたしました。〔「異議なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"武内副委員長","kind":"意見","question":"よって、本案は、原案のとおり可決決定いたしました。以上で、議案審査を終了いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"武内副委員長","kind":"質問","question":"次に、予定表３の委員長報告についてですが、議案審査の結果報告については、正副委員長にご一任いただけますでしょうか。〔「異議なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325034?Template=document&Id=1784#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":27495,"voices":90}},{"id":"h20-20080602-6","meetingId":"h20-cm06","date":"2008年6月2日","dateIso":"2008-06-02","committee":"区民委員会","time":"午後１時０３分～午後４時４０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"の１、幹部職員紹介","agenda":"の１、幹部職員紹介","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"協議会を行って、地区別に４回ぐらい行うということですけれども、実際にどのような話し合いが行われているのかお伺いしたいと思います。それから、ここにどのように魂を入れていくのかということが大事になってくると思いますので、その辺の考え方もお伺いたいと思います。","respondent":"中山地域活動課長、高濱生活安全担当課長、金子産業振興課長","answer":"今回もご説明申し上げたような町会活動はさまざまありますけれども、区で支援策を考えてほしいというような、町会に関するものものあります。… サービスを続けるためには更新しなければならないということで、どうしても必要となってしまう経費と認識しております。… 中小企業ワークライフバランス支援事業ですけれども、この計画の中で中小企業に向けてどういったことができるのかという検討から始まりまして。…","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"去年１年課長もかかわっていて講習会も出られたと思うんですけれども、何か見えてきたことはどういうことなのかお伺いしいと思います。これは区として独自にやっていることなのか、それともやらなくてはいけないものなのか、お伺いしたいと思います。","respondent":"金子産業振興課長、小野区民課長","answer":"来年以降、私どもは常々事業展開している中で考えながら検討しておりますので、より効果のある事業を実施していこうと考えているところです。あくまでも店舗の周囲の環境の問題として調整していくという事務ですので… この事務について私どもと自衛隊東京地方連絡部五反田募集案内所と連携を取って実施しているものであります。激励会は毎年入隊者についてやっているわけですけれども、法定受託事務の一部と考えております。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問","question":"事務事業概要の地域活動課の中で２ページなんですが、１３地域センターの中で窓口事務が二通りに分けられているところの理由を教えてください。私が地域の方から「なぜ、どのような返事をすればいいのか、なぜ分かれているのか説明を求めました。","respondent":"中山地域活動課長","answer":"異動届については６地区のどこでも出せる。なおかつ本庁も出せるという中で見直したものです。","id":"exchange-003"},{"speaker":"渡部委員","kind":"意見","question":"仮に、それがわからないで行ってしまった人がいた場合は対応なさるのか。せっかく来ていただいたけれども、もう１回ご足労願うけれども、本庁に行ってくださいというような対応をされているのかとの意見を述べました。","respondent":"中山地域活動課長","answer":"結論から言うと、その地域センターでできない事務については、近隣の処理ができる地域センター、もしくは本庁に丁重にご案内するという形になっております。","id":"exchange-004"},{"speaker":"宮崎副委員長","kind":"質問","question":"例えば、平成２４年度は平成２０年度比１０％減少となっているんですけれども、この目標にいかないとどういう影響が出てくるのか。例えば、区民の保険料へのはね返り等がどのような感じになってくるのか、その辺の大まかな仕組みをお伺いしたいと思います。","respondent":"本城国保年金課長","answer":"特定健診の基本項目とその他詳細項目についてですが、従来の区民健診と同じように、同時にできるという形で実施いたします。今のところはそちらまでですが、それを踏まえた保険料の設定になる見込みだと思います。","id":"exchange-005"},{"speaker":"宮崎副委員長","kind":"質問","question":"やはり、受診率アップの１つの方法かなと思っているんですけれども、そこの考え方をお聞きしたいと思います。ウォーキングコースとかジョギングコースとか何かやったらどうだ」と言われて、「ああ、あったら聞かせてほしいと求めました。","respondent":"本城国保年金課長","answer":"特定保健指導につながるですので、それぞれの方の状況に合ったウォーキング等も含めたプログラムを提示して対応していくことになります。実際に、そういうところもあわせて工夫して、実際に結びつくような形でサポートしていくことを検討しています。","id":"exchange-006"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"例えば、大学３年生から就職活動が始まっていて、早いところですと大学３年生のうちから内定が来ていたりするんです。学生のほうに、その辺のところは何か工夫があるのか、考え方とか現状も含めて何かあったらお聞かせほしいと求めました。","respondent":"金子産業振興課長","answer":"特に産業技術高等専門学校を中心に品川区、大田区がかかわって、この問題の対策をさまざま検討しながら思考している段階です。そういう意味では、今後どういうことができるのかということを、具体的に城南地区で連携できていければと考えているところです。","id":"exchange-007"},{"speaker":"宮崎副委員長","kind":"意見","question":"もっと新卒獲得への働きかけというか、戦略というか、そういうものがあってもいいのかなという感じがしているんです。そこのところはもう少し考えたほうがいいという感想を持ったところですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"廃棄物減量等推進員が５２６人いらっしゃるということですけれども、これまで相談してきてどういう意見が上がってきたのかお伺いしたいと思います。ごみになるようなものをなるべくつくらないでほしいというような、そこに関しての区の姿勢といいますか、お考えを改めてお伺いしたいと思います。","respondent":"工藤環境課長、島袋品川区清掃事務所長、秋山資源循環推進課長","answer":"私どもは環境測定ということで、大気汚染に関しましては常時継続的に把握しています。当然環境基準も追加して項目等も測定していかなければいけないと考え… 現在も町会とか自治会に説明会をして、話のほとんどは分別の仕方をどうするか、プラスチックを燃やしてどうこうなるという意見はあまりありません。… 昔より１本当たりのペット樹脂の量を削減したりということで、ごみの発生抑制を事業者自身が行っているわけです。…","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"ごみにならないだろうかというところまで考えていただきたい面もあるんですけれども、その辺のお考えがあれば、ぜひお伺いしたいと思います。ＰＭ２.５の話は、考えているような話がないのか、もしあるとすればどのようにしていくのかということをお伺いしたいと思います。","respondent":"秋山資源循環推進課長、工藤環境課長","answer":"アルミ缶のアルミの使用の減ということで、最近ではしておりますので、そういう中で発生抑制が実現されていくものと考えております。今回実施するという形で考えておりまして、事業者についてもペットボトルの減量等しておりますので… ＰＭ２.５につきましての再質問ということもありますけれども、さまざまな新しい動きの情報を入手しています。引き続き委員がご質問をされた点につきましては、状況を把握しまして、対応していきたいと考えております。","id":"exchange-010"}]},{"id":"topic-02","title":"の学校の夏季休業中における地域食事サービス","agenda":"の学校の夏季休業中における地域食事サービス","exchanges":[{"speaker":"宮崎副委員長","kind":"意見","question":"細かいことですが、配食ボランティアには別のことをやってもらうとことですね。そのまま配ってもらえばいいのではないかという気がするんですけれども、その辺はなぜこうなるのかよくわからないんですけれどもとの意見を述べました。","respondent":"中山地域活動課長","answer":"ボランティア自身も夏休みの期間に頑張っていただいているわけですが、ボランティア自身もかなり高齢化等が進んでいる中でいろいろ考えたものです。すそ野を広げて、こういうものの検証を兼ねて、この夏に見直しを図っていこうです。","id":"exchange-011"},{"speaker":"宮崎副委員長","kind":"質問","question":"４回と２回のお知らせと名産品というのは、参加人数が少なくなっていくこともあるかなということですね。要するに、ボランティアが少なくなるかもしれないということか尋ねました。","respondent":"中山地域活動課長","answer":"ただ、新たなもののご協力という形になりますから、今後の展開というのはもう少しこれを踏まえて広く考えていきたいと思います。確かに、夏だけで見れば、２カ月は休みたいということになれば、従事者が減る可能性はあります。","id":"exchange-012"},{"speaker":"宮崎副委員長","kind":"意見","question":"状況はわかりましたけれども、私の知っているボランティアはやる気のある方なので、ボランティアの意見を聞いてからやっているのだろうと思うんですけれども、もしかして水を差すようなことにならないかと心配なので聞いてみたんですけれども、わかりましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"}]},{"id":"topic-03","title":"の緊急資金「景気対策経営サポート資金２００８」","agenda":"の緊急資金「景気対策経営サポート資金２００８」","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"商工相談員の段階でだめだったのか、それとも保証協会のほうでだめだと言われてしまったのか、主な理由があれば教えてください。それから、審査にどのぐらいの時間がかかるのか説明を求めました。","respondent":"金子産業振興課長","answer":"そのほかの経営指導をきちんとするということは、商工相談員の責務として課しているものですので、そういった形で対応しています。ただ、私どもに来る報告というのは、直ちに来ないということがありますので、そういう意味では私どもの掌握が遅れているということはあります。","id":"exchange-014"},{"speaker":"稲川委員","kind":"質問・要望","question":"緊急資金ということですから、その辺をもっと周知して、しっかりやってほしいと求めました。アフターケアではないですけれども、だめだった人にはどうすればいいか、しっかり経営指導してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"実態調査がどのような形で行われたのかということと、他区の取り組みも参考にしながら行うべきだと思うので、どうなのかということが１つ。例えばほかの自治体でこういうことをやっているところがあるとか、そういったことをつかんでいることがあれば伺いと思います。","respondent":"金子産業振興課長","answer":"２点のお尋ねで、緊急資金を実施するにあたりましては、それから先ほど事務事業概要でも申し上げました四半期ごとに景況調査を行っております。他区の新たな支援策ということなのか、城南５区の中では港区、実施しているところであります。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"大もとのところで異常なぐらいの原油高ですから、町場の人と話していても、どうなってしまうのだろうという感じがすごく伝わってくるんです。そっちでやっていかないと、やはり本当に大変になってしまうと思うんですけれども、そこに関する強い決意をお伺いしたいと思います。","respondent":"金子産業振興課長","answer":"例えば、建築基準法の改正によるもの、またサブプライムローンの問題等々がありまして、中でも最近一番大きいものは原油高だろうと考えています。２３区の区長会あるいは全国の市長会でまとめているところでありますので、それについては別途検討させていただきたいと思います。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひその要望の中に国に対して意見を言うときに、品川区も代表の人なわけですから、そこに関してはどうか尋ねました。","respondent":"金子産業振興課長","answer":"先ほども申し上げましたとおり、原因は一様ではないと認識しております。この先マスコミ等の報道のように、そういう意味では注視しながら予算要望等の機会にあわせて、要望を検討してまいりたいと考えております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、繰り返しになってしまいますけれども、行き過ぎた儲け第一主義というやり方に対してものすごく怒りを持っているわけです。ですから、その区民感情にぜひ寄り添っていただいて、何とか原因に対してきちんと改善していくという立場に立っていただきたいと強く思いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"確認","question":"確認しておきたいんですけれども、今回の目的は「原油、対象者のところでは「以下のすべての要件に該当することが必要です」ということです。原材料等の高騰ということが入ってくるのかどうか、その関係がよくわからないので、どうなんか尋ねました。","respondent":"金子産業振興課長","answer":"全体の業種で考えておりますので、限定的に考えているわけではないということで、ご理解いただければと思います。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/798229?Template=document&Id=2518#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":57826,"voices":117}},{"id":"h20-20080602-7","meetingId":"h20-cm06","date":"2008年6月2日","dateIso":"2008-06-02","committee":"厚生委員会","time":"午後１時０２分～午後３時４９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"阿部委員","kind":"質問・要望","question":"大変それが使いやすかったものですから、児童保健事業部のこの概要の中にも、それを書くことが可能なのか。もしあれば便利だなと思ったものですから、私としては、できればやっていただきたいと思っています。","respondent":"古川児童保健事業部長","answer":"貴重なご意見をありがとうございました。どこまでできるか、この後また冊子を製本いたしますので、可能な限り対応していきたいと考えております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"テレビなんかでも話題になっていますけれども、この辺の把握をどうされているのか、わかる範囲で教えていただきたいのが１点です。弾力化という言い方をしていいんでしょうか、その辺の数の考え方というんですか、算定の公式とかがあるのか。","respondent":"平澤品川区保健センター衛生課長、小林保育課長","answer":"１４５ベッドにかなり減っているわけですけれども、診療所につきましては、以前は時間的な４８時間以内の制限がございました。基準病床数が６,２０８床、既存病床数が１万４,３９４床ということで、こういう状況であるです。 この定数と弾力化の数の考え方というお尋ねですけれども、継続的、かつ安定的に維持すべき入所定員ということで考えております。待機児童を抱えている状況ですので、その地区の困難度に合わせて柔軟に弾力化枠を活用して…","id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"どこまで弾力化できるのか、するのかというあたりの線をどこに引いていらっしゃるのかを、一つお願いします。それからもう１点、３１ページにとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"全体的に聞けるお伺いできる機会ってあまりないので、これからいろいろ聞いていく基本になるところなので、ぜひよろしくお願いいたします。平成２０年度、平成２０年度は従来どおりに執行されるように聞いているんですけれども、お聞かせをほしいと求めました。","respondent":"小林保育課長","answer":"この指針に沿って、必要な対応をしてまいりたいと思っています。特に平成２０年度、１９年度を堺として前後、私立保育園の補助金に大きな影響が出ているとは聞いておりません。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"国の医療制度改革により、健診については、各医療保険者により行うものとされました。高齢事業課が実施しますが、委員会をまたがるこうした例や、他課とリンクした事業の審査はどのような取り扱いをするのか尋ねました。","respondent":"古川児童保健事業部長","answer":"常任委員会は５常任それぞれ所管事項を抱えてありますので、私どもは、その委員会の運営の中で対応します。ただ、後期高齢者につきましては、当然、こちらの所管ですから、当委員会での対応と考えております。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"病院のほうでも、病院そのものがベッドを閉鎖したというところが区内であるのかどうか、ちょっとわかったら教えてほしいと求めました。今後、そこら辺のところは、今後も続く方向で考えていいのかということだけ教えてほしいと求めました。","respondent":"平澤品川区保健センター衛生課長、小林保育課長","answer":"ちょっと表の見方が、若干ご説明不足だったかとも思うんですけれども、１１４ページの表８－１です。平成１８年度から１９年度にかけて一つ病院が減っているということでございまして、経営上の問題等… 私立保育園の助成の状況ですけれども、本年度につきましては、大きな変更を予定しておりません。必要な項目に助成を行うように検討していくところで、その水準については言及することは、ちょっと困難です。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"総括的な質疑というのはわかるんですが、もうちょっと緩やかに受けとめていただきたいなと思うのが、すごくたくさんの資料をいただきました。後で電話でお伺いしたり、率直に聞かせていただきたいと思うんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１ページの福祉改革担当主査というのがあるんですが、この仕事の中身がわからないので、ぜひこれを教えていただきたい。四期の検討が始まるということなので、いつ、どの辺で四期の検討がされるのかというところも教えていただけたらと思います。","respondent":"高橋障害者福祉課長、冨岡高齢福祉課長","answer":"私どもで自立支援法ができて、その前に支援費ができた、担当を置いているものです。 今までも委員会に報告をしていますので、今後も引き続き、その姿勢で臨ませていただきたいと考えています。まず、それから第四期の基本的な課題の整理といった形で進んでまいりますので…","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"(5)に長寿医療制度（後期高齢者）と書いてあるんですけれども、これは一般的に使われるようになったのでしょうか。保険料の通知が、７月に、これから届くということと、ちょっとその辺の徴収方法も教えていただきたい。","respondent":"永尾高齢事業課長","answer":"普通徴収の方につきましては、７月から来年３月までの９カ月間を１年分でお支払いいただくということで、納付書を送る予定です。納付書と決定通知については、７月中旬を予定しております。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"他区で独自の対策をとり始めている自治体が出てきているので、その辺のお考えがあるかどうか、お聞かせいただきたい。これは要望です。","respondent":"永尾高齢事業課長","answer":"他区の独自対策という点ですが、新聞等で幾つか見てはありますが、品川区としましては、国のほうが、今のところ６月１５日の天引きに向けて検討されているという情報が入っておりますので、そちらの動向をよく見ながら、うちのほうも考えてまいりたいと思います。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大体８割ぐらいという数字が出ているんですが、８割が妥当なのか、どうか。どういう状況なのかという点を説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"最初の数字の並べ方ですが、部は違うとはいえ、同じ委員会に属する所管ですので、調整の方向で検討します。３カ月の期間で入る方もいるので、３カ月の入所者数を書いておりますので、定数を満たしていると聞いております。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"２３ページには、これをまとめた形で介護保険の実態がわかるようなものにしていただけないかなと思うんですけれども、いかがでしょうか。それをまず第１点、説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"介護保険の給付実績等につきましては、一覧表等、わかりやすい表をつけるように検討させていただきたいと思います。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"実際に他の自治体の介護老人保健施設を利用されている方もたくさんいるわけですから、多分、ここにはほとんどないのではないかなと思うんです。今の時点で、そういうふうに言われたので、ちょっと個別の問題で申しわけないんですけれども、お聞かせほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"個々のケースで、ちょっとそれは私どもで調べさせていただきたいと思います。一般的にどうこうということはやっておりませんので。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"特に、課として大きな変化ということはないということであれば、またよろしくお願いしたいと思います。４月から始まって、品川区としてはどれぐらいあったのかについて、ちょっとお聞かせいただけないか尋ねました。","respondent":"永尾高齢事業課長","answer":"問い合わせの件数ですけれども、先ほどもピーク時で１００件ということで、毎日の苦情の件数は、実はトータルの計算はされていないんですけれども、これから納付書をお送りしたときに、もっとお問い合わせ等が来るのではないかと予想しております。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"数としてつかんでいただきたいと思うんですけれども、そのことが１点、お聞かせほしいと求めました。品川区内にあるか、どうか、把握をしていたら教えてほしいと求めました。","respondent":"永尾高齢事業課長","answer":"最初のお問い合わせ、苦情等の数としてつかむということにつきましては、今後、やっていきたいと考えています。ただ、東京都のほうでは、広域のほうでは、３割程度ということは聞いております。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"先ほど、平成２０年度竣工ということで報告があったと思うんですけれども、平成２１年４月から開設ということでいいんでしょうか。このことだけ、ちょっと確認をお願いしたいと思います。","respondent":"冨岡高齢福祉課長","answer":"今、副委員長のお話にありましたように、年度内に竣工して、予定ですけれども、４月から開設というふうに詰めております。","id":"exchange-016"},{"speaker":"阿部委員","kind":"質問","question":"もし品川区として何か見解があれば、あるいは、今後の対応があれば教えてください。なければ、結構です。","respondent":"永尾高齢事業課長","answer":"柔道整復の不正請求についてですけれども、現在、品川区ではそういう現状はございません。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993548?Template=document&Id=3204#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":49652,"voices":99}},{"id":"h20-20080602-8","meetingId":"h20-cm06","date":"2008年6月2日","dateIso":"2008-06-02","committee":"建設委員会","time":"午後１時０３分～午後２時４５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"の１番目、幹部職員紹介","agenda":"の１番目、幹部職員紹介","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"事業との関係があるので、事業部のほうがそこをどうとらえるのかというのがあるのかもしれませんけれども、もう少しその辺をお願いします。","respondent":"松澤委員長","answer":"八潮のまちづくりに関することについては、前年度の街づくり特別委員会の調査事項を継続する考えで、八潮地区に関することを調査項目とする。そのように仕切らせていただきました。","id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"その仕切りは必要なんですけれども、ただ、この建設委員会でやる質疑についても、どうしても関連してくるものがたくさん出てくるかと思うんです。どうしてもそこに入らざるを得ない部分があると思うので、その辺を委員長のほうでぜひ考慮しながら、お願いしたいと思っていますとの意見を述べました。","respondent":"松澤委員長","answer":"当然のことながら、かぶる部分はあると思いますので、こちらでも聞かなければいけないことは聞かなければいけない。あいまいな部分が残っていると考えておりますので、できる限り、原則的には質疑に生かしたいと思っています。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"事業のことで１つだけお聞かせいただきたいんです。環境問題というのをどういうふうに、新たな位置付けとしてあるのかどうか、そこだけお聞かせ願いたいと思います。","respondent":"青木都市開発課長","answer":"あるいは法令を遵守して、委員がご指摘いただきましたような環境問題等、当然現代的な課題としていろいろな所管で取り組まれているところです。そういった形では、個別具体のものをつくる段階で、どのように反映されていくのかというところをチェックいただければと考えています。","id":"exchange-003"},{"speaker":"菊地委員","kind":"意見","question":"そうした位置づけ、ハードとソフトの間の位置付けというのをきっちり持っていく必要性というのが、あるんだと私は思うんです。何かあったら、それと照らし合わせるみたいな感じに聞こえたんですけれども、その辺をもう一度お願いしますとの意見を述べました。","respondent":"岩田まちづくり事業部長","answer":"持続可能な成長を担保するような形で、環境問題をきちっと、対策をとっていくというのが世界的な規模での認識です。いわゆるＣＯ２対策として、持続可能な発展をする品川のまちとして再開発をとらえている、こういう考えです。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"学会で認められているかどうか、こうした状況が生まれる可能性を指摘しているわけですから、やっぱり温暖化との関係での集中豪雨だったわけですから。ぜひそういう問題についても、建設委員会で報告事項としてあれば、ぜひ取り上げてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"１つ、資料のつくり方でお伺いしたいんですけれども、記載に随分と違いがあるんです。この違いはどういうことなのかということをお伺いしたいと思います。","respondent":"松代管理工事課長","answer":"これも、基本的には毎年度、平成１９年度版、平成２０年度版ということでつくっております。管理工事課のほうでいいますと、平成２０年度予算額というところの数値が、ということでよろしいでしょうか。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"今後ぜひすべてにそういう記載の仕方をしていただければと思ったものですから、事業が終わったために、これを見てわかりたいんです。それがベストだと思うので、その辺を改良していただきたいと思ったんですが、いかがか尋ねました。","respondent":"松代管理工事課長","answer":"私どもは８課ございまして、統一的な資料をつくるように、いろいろと努めていきたいと考えています。数字の予算的な表示につきましても、なるべく事業それぞれの内容をわかりやすくする意味でも、ひとつ検討します。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"３７ページの街路灯建替えなんかで言えば、３７ページですね、すべてにぜひ記載をしてほしいと求めました。検討委託ほかというところで、これはどういう検討委託なのかとか、その辺のところをもう少し見える形で説明ほしいと求めました。","respondent":"藤田道路公園課長","answer":"今進めています長期基本計画の中で、今まで以上に地域の方々と連携を図りながら、それを形にしていくための事業です。いずれにしても、地域の方々と一緒にやっていくということが非常に大切だと考えておりますので、いろいろな形でご案内していきたいと考えています。","id":"exchange-008"},{"speaker":"井上委員","kind":"意見","question":"マンション紛争とか、地域の住環境を守っていくというような視点が、区としてはここに入っているものなのかどうなのかとの意見を述べました。","respondent":"藤田道路公園課長","answer":"その地域において、皆さんが望んでいることが、何が大切なのかというのをまず考えていくことが大切だと考えています。総合的に合わせることでいろいろできることがあると考えていますので、広い意味では中に取り込みながら、考えていくべきと考えております。","id":"exchange-009"},{"speaker":"井上委員","kind":"提案","question":"これは今後の提案になっていくんだと思うので、これは調査課題として、取り組んでいかなければいけない課題だと思っています。詳しくはいろいろな担当課にお伺いしたいと思いますけれども、特に事業として特殊なものがあってそうなっているのかどうか、説明を求めました。","respondent":"藤田道路公園課長","answer":"３４ページの高潮護岸の維持管理についてですが、平成２０年度、区に引き継ぐ予定になっております。街路灯の照明等については、港湾局では予算化できないということで、その部分は区が負担をしながらやっていくということになっております。","id":"exchange-010"},{"speaker":"藤原副委員長","kind":"質問","question":"事業部の組織についてお伺いしたいんですけれども、用地担当課長というポジションが紹介されましたが、前年度はなかったような気がするんですけれども、まず、何で新設をしたか、それと具体的にどのようなことをやるのか、その２点、まずお伺いします。","respondent":"岩田まちづくり事業部長","answer":"区で買う場合も、さまざまな公的な処理にきちっと対応するために、職として置いたということです。あるいは担当管理職では、こういう分野で経験の深い専門の方に来ていただこうということで、職を新たに設置したものです。","id":"exchange-011"},{"speaker":"藤原副委員長","kind":"質問","question":"委員会ですから、その辺はいかがですかということと、結果が出てこないとまずいと思うんです。効果といいますか、効果を判断する材料というのは、パーセンテージを上げたということになってくるんか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"今日の事務事業概要のご説明の中で、用地担当課長が職務を分掌している事業というのはないんです。土地収用法を適用させるのは、もうそれの最後の手段と考えておりますので、まずそこら辺で頑張ってまいりたいと思います。","id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"藤原副委員長から話が出たものですから、先にお聞きしておきたいんですけれども、私には理解できない。これは感覚的にはどうも専門職で、建設委員会ですから、教えてほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"公社で代行取得していただいて、それで区が翌年度にきちっと予算をつけた上で買い戻す、こういう形になります。国庫補助のもらい忘れといいますか、漏れがないように、きちっと財源を補填していくという手法にも使われるです。","id":"exchange-013"},{"speaker":"原委員","kind":"質問・要望","question":"公益性を持って公社となっているということの確認をさせていただきたいのと、これは品川区だけではないんでしょうけれども、公社が買い上げる。そこだけ、ご説明がなかったので、ちょっと教えてほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"買ったものはすべて区に引き取ってもらうというのが目的の会社です。当然金融機関からの借入に当たっては、担保は当然区が保証をつけてやっているです。","id":"exchange-014"},{"speaker":"三上委員","kind":"質問","question":"１カ月分、今の課長たちの平成２０年度の予算の中で予想されている予算すべてにわたって、どういうふうに考えていったらいいんか尋ねました。","respondent":"梶都市計画課長","answer":"１つ目の補助事業に関しては、５月１４日段階で内示がございまして、ほぼ内示があったという形です。１億円弱ほど下るのではないかと思いますけれども、国のほうから対応が出てくるのかが今議論されているところなので、こちらは未定という形です。","id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"そうすると、国の補助事業については、ほぼ１００％出てくるということが確約されていると。そうすると、多少なりとも、１億円近くなる地方税収の分については影響があるということ、それはどういう事業になるんか尋ねました。","respondent":"梶都市計画課長、岩田まちづくり事業部長","answer":"経常的に行う道路の維持管理ですとか、あと街路灯の事業、そういったものに関連してまいります。具体的にどういった形で出てくるのかわからないんですけれども、こちらのほうは私どもは、注視している段階です。 したがって、２カ月分の工事費は減になります。２カ月おくれで出発するということになりますので、国庫補助ケースでは出なかった、こういう説明です。","id":"exchange-016"},{"speaker":"三上委員","kind":"質問・要望","question":"区長会でも、しっかりお金をもらえるような、そういう算段を整えていただきたい。国債発行でという話になると困るんだけれども、そうならないような形で、財源確保については、努力していただきたい、お願いしたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"松澤委員長","kind":"提案","question":"委員の皆様のご意見、ご要望をお聞きして、今後の委員会運営の参考にさせてほしいと求めました。ご提案していただき、できる限り調査・研究をしていきたいと考えておりますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759088?Template=document&Id=3912#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":31776,"voices":87}},{"id":"h20-20080602-9","meetingId":"h20-cm06","date":"2008年6月2日","dateIso":"2008-06-02","committee":"文教委員会","time":"午後１時０５分～午後２時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"山内副委員長","kind":"意見","question":"副委員長の山内です。どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"川西委員","kind":"確認","question":"それから確認ですが、マイスクール八潮に教育相談機能があるという説明でしたね。日常的な細かい相談というのは、教育委員会の窓口としてはどこが一番分かりやすく教えていただけるところか尋ねました。","respondent":"富田学務課長、河野指導課長、小川品川図書館長","answer":"就学援助についてお答えいたします。したがいまして、小学校から中学校に上がる時点で、結果として全体の児童・生徒数に対する割合が高くなる結果になって… それから２点目の教育相談センターのマイスクール八潮の跡地への移転ですが、基本的には、すべてマイスクールの方で継続して行う予定です。… 五反田図書館臨時窓口に関するお問い合わせですが、株式会社ＴＯＣと建物の賃貸借の契約を結びまして、月額、税込みで３１万２,０１０円です。…","id":"exchange-002"},{"speaker":"川西委員","kind":"質問","question":"指導主事のことなんですけど、６ページの組織図に「指導主事（１０）」と。この１０と書いてあるのは、中学校担当、それの一覧表というのはどこに行けばいただけるのか説明を求めました。","respondent":"河野指導課長","answer":"こちらの指導主事のところに「１０」と入っておりますが、いわゆる学校経営指導員という、その方たちも含めて１０名というふうに記載しています。なお、そういう役割分担表については、指導課の方にお越しいただければさしあげます。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"概要というか、全体的な考え方を伺いたいなと思ったんですが、この「精神に基づき」というのはどんなふうな理解なのか伺いたいなと思います。具体的なことを伺いたいと思います。","respondent":"市川教育次長","answer":"教育目標と基本方針、当然のことながら公教育として実施しているわけで、教育目標の上段のところに二つの○印で示しています。下の「自ら学び実践することができる」、これが主に憲法と教育基本法の志向するところというふうに受けとめています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"意見","question":"ほかに、児童の権利に関する条約の趣旨と、教育改革プラン２１の趣旨、それぞれどういうふうなことなのかというのを説明を求めました。","respondent":"河野指導課長","answer":"子どもの人権をきちんと、教員、大人も守りながら子どもの教育にかかわるです。私は先ほど８ページのところで説明いたしましたように、プラン２１の目的そのものは、そういう学校教育を実現していこうという趣旨です。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"多くの保護者の方が町中の学校はどうなるのかという心配の声がよく聞かれるもので、今までの経過も含めて、現状を教えていただけたらと思うんですね。中学校が１３校あって、幼稚園は９園あって、小学校は３５校あるわけですよね。","respondent":"田村庶務課長","answer":"校舎の改築計画対象の改築工事を実施しているですので、現在小学校は６校やっておりますので、３８校中３１校ということで８２％。平成２１年度以降、あるいは単独で改築の学校ということで、順次残りの学校についても計画的に進めていくというような考えでおります。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"今、お話があった中では、今年改築しますよという学校があるけれども、まだ契約議案としては上がってきていない。大体夏行うということを伺っているんですけれども、あと、そういうところというのはどういうふうに考えていらっしゃるのか教えていただけますか。","respondent":"田村庶務課長","answer":"平成１７年度にすべての学校について耐震診断を実施したということで、老朽度だとか、緊急度の高いものから順に実施していくというような形で。平成２１年度以降の事業調査についても、順次、必要性に応じて進めていくというような状況です。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは新規事業になるんでしょうか、理解が間違っていたら教えてください。援助対象費目に「小中一貫校標準服費（小１）、これはどういう意味なのかということと、一貫校だと５年生も制服がかかってきますよね。","respondent":"富田学務課長","answer":"今年度開設した学校というのは八潮学園１校でありますが、こちらにつきましては、今年度のみ１年生から６年生までを対象とする。今年度購入する方についてのみ対象とするです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"じゃあ、今年度のみということは、来年は対象ではないということなのでしょうか。それとも、常に小学校１年生のところは続けていくという考えなのか、教えていただけますか。","respondent":"富田学務課長","answer":"既設の小中一貫校と同様に、新１年生を対象とするです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"給食調理代行のところで、今後、全校で計画というお話で、現状何校だというお話がありましたけれども、今年、来年、再来年、いつまでに全校をという計画のところだけ教えていただけますか。","respondent":"富田学務課長","answer":"平成２０年度、今年度から給食調理代行を導入したのは６校であります。来年度以降につきましては、今後、計画を策定してまいります。","id":"exchange-010"},{"speaker":"西本委員","kind":"確認","question":"幼保ですから厚生委員会の方になってしまうのか、この議論の中では、行政サイドとしてはどういう仕切りを考えているのかをお聞きしたいと思います。総合型スポーツということで動き始めていると思うんですが、今後の流れで、年内にどういう方向づけをして動くのかを伺いたいと思います。","respondent":"市川教育次長、富田学務課長、和氣小中一貫教育担当課長、堀越生涯学習課長","answer":"確かに他課との連携事業、あるいは教育委員会全体として他の事業部と連携して取り組んでいくということがあります。それからまた… 校務システムの検討に当たりましては、検討委員会を立ち上げまして、会議を重ねてきているところであります。既に一部、別途に… 今年度特に強化をしてまいりたいと思っておりまして、そこの調査と、教育課程内容の方でどれだけ連携していけるかが重要であろうと考えております。… こちらは平成１９年度に設立支援協議会を設置いたしまして、クラブ設立に向けての検討…","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"どこからどこまで、どこでどういうふうにしているのかというのは仕切りをお願いしたいと考えていますので、よろしくお願いします。ただ、親同士の関係を深めていきましょうという流れをつくっていただきたいなと考えていますので、その辺の考えをもう一度お聞きしたいと思います。","respondent":"富田学務課長","answer":"それはそれとして、それぞれの学校のＰＴＡなりが自分たちとしてその辺をどう考えていくのかというようなことも内容としては出てくるんだと。これについて教育委員会として、電話連絡網を残すべきであるとか何とか、そういったことを申し上げていくことはないということです。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"確かに要望はいろいろあると思います。なくなってしまうものが当然出てくるわけですから、もう少しきちんと構築していただきたいなということで要望として出しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"山元委員","kind":"質問・要望","question":"教えていただきたいんですが、教えていただきたいということと、そういう意味で変えたのかということ。何分にも流れがよくわかっていないので、教えてほしいと求めました。","respondent":"河野指導課長","answer":"小学校でスクールカウンセラーを配置するという事業は、平成１８年度から実施してまいりました。大体２週間に１回ぐらい、すべての小学校に週１回ずつスクールカウンセラーを配置するということで、倍増という表現にしたものです。","id":"exchange-014"},{"speaker":"山元委員","kind":"質問・要望","question":"今度は１７ページのところなんですが、シルバー人材の方と、また地域の方にお願いをするというお話がありました。特に地域の方が気になるんですが、どのぐらいの方が携わっていらっしゃるのか、わかれば教えていただきたいんですけれども。","respondent":"田村庶務課長","answer":"１７ページの下段の通学安全監視委託ですけれども、シルバー人材センターとほぼ同等の有償ということで、お支払いしているということです。細かい内訳につきましては、今、ちょっと手元の方にはございませんので、必要であれば後ほど調べてお出しします。","id":"exchange-015"},{"speaker":"市川委員","kind":"質問","question":"１２ページの理科支援員等の配置事業ということで、この支援員の配置というのはどういうふうに。その辺を伺いたいということと、米飯給食を現在週２回から３回実施というふうになっているんですけれども、その辺を説明を求めました。","respondent":"河野指導課長、富田学務課長","answer":"理科支援員の配置事業ですが、これは支援員が学校を巡回するのではなく、学校が支援員を指定して、ある一定の期間、実験や観察の準備等のお手伝いをしていただくという制度です。 これは、平成１９年度の状況ということで書いておりまして、特に米飯は何回とするというような定めのようなものはなかったと思います。実際には米飯の回数はもう少し増えていっており、パンが週に１回程度…","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"どうしてそういうことを聞くかというと、５０ページのところに中・高生体験学習講座なんていうのが生涯学習の中にこういう講座があるけれども。もちろん事務局がいらっしゃるわけだから、そうすると、我々はどういう仕分けをしておけばいいのかということだけは教えておいていただければと。","respondent":"市川教育次長、河野指導課長、田村庶務課長","answer":"区の、事務局次長ということで配置しているわけでございまして、文教委員会で席につかせていただいております。… 品川区立の学校では市民科で指導をし、繰り返し実践に結びつけるということのほかに、日常的に大勢の地域の方が出入りしている。… 委員ご指摘のとおりの学校はさまざま、地域とも、各種団体とも連携しています。どういう記載の仕方にするかは今後の検討にして…","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問","question":"前の委員会でちょっとだけ私も伺ったんだけれども、教員の独自採用というようなことにも、考えてみればなるのかな。数のことも含めて品川区が独自にやっていこうということなんですけれども、それはどんどん拡大というか、評価していく気持ちでいるのかどうか。","respondent":"河野指導課長","answer":"再任用管理職ですが、この制度ができたのが平成１９年度からということで、今年が２年目ということになります。再任用管理職が１人いるということは、希望、それと実績等を踏まえて慎重に検討しています。","id":"exchange-018"},{"speaker":"川西委員","kind":"質問","question":"これは６月になりますと契約時期になって、７月以降に工事日程が決まるんですけれども、大体短いところで何カ月ですか。これは金額的に、ほとんど指名競争入札ではないですよね。","respondent":"田村庶務課長","answer":"額も、耐震補強工事でも大きな工事だと１億円を超える工事になることもあります。大体平均すると８,０００万円から１億円ぐらいの工事になりますので、指名競争入札ということで処理したいと考えています。","id":"exchange-019"},{"speaker":"川西委員","kind":"質問","question":"ここでやめておきますけど、後ほどお話をお伺いできれば、もう実施設計等はわかっているんですね。わかりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"工事が最低でも１カ月半、長くて３カ月というところで、体育の授業の場所の確保というのが何とかできないものなのかなと。そういうところの工夫というのはどんなふうになっているのかということを説明を求めました。","respondent":"田村庶務課長、武内委員長","answer":"あるいは連携しながら、空きのあるところを利用してやっているということで、学校の方の調整にお任せしているということです。若干不便はかけますけれども… ほかにご質疑等がないようですので、予定表２の事務事業概要を終了いたします。 次に予定表３のその他を行います。〔「なし」と呼ぶ者あり〕","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/612972?Template=document&Id=4634#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":30418,"voices":83}},{"id":"h20-20080602-5","meetingId":"h20-cm06","date":"2008年6月2日","dateIso":"2008-06-02","committee":"総務委員会","time":"午後１時０３分～午後２時５８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"その辺だけでもちょっと教えていただきたいというのが１つと、伺いたいと思っているんですけれども、新聞折り込みで入ってきますね。平成１９年度から実施ということなので、今のようなやり方でいいのかどうかというのは、見解を伺っておきたいなと思います。","respondent":"宍戸施設担当課長、中川原広報広聴課長","answer":"手元に細かいスケジュールがないんですけれども、本体工事につきましては、平成２１年２月末までの予定となっています。外溝工事がそれに引き続いて、平成２０年度中にある予定です。 月３回やっているということと、そういった日にちの設定をさせていただいている関係上、このやり方でやらせていただきたいと考えています。周知とかは、口コミも含めまして、努めていきたいというふうに思っております。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"１点だけ伺いたいと思いますけれども、どういう手法を通じてやっていくという方向での、改めてその辺をお伺いしておきたいと思うし。必要か、必要じゃないかの見解も含めて、伺えればと思いますが。","respondent":"中川原広報広聴課長","answer":"広報紙はやはり一番、区の情報をお届けするのに、大事な媒体と考えています。広報紙をお届けできるように、また個別にご相談も受けておりますので、よろしくお願いしたいと思います。","id":"exchange-002"},{"speaker":"山路副委員長","kind":"質問","question":"総務課の２４ページ、施設担当。この辺について簡単に説明していただけますか尋ねました。","respondent":"阿部経理課長","answer":"もう一つが、インフレのときの対応という、３つを規定しています。そういう手続に、それに従って、今申し上げた東京都あるいは２３区の検討に入るということになろうかなというふうに思っています。","id":"exchange-003"},{"speaker":"山路副委員長","kind":"質問","question":"非常に、この資材の「単品スライド条項」というんですかね、今説明していただいたの。その辺の、国交省と区との考えというのはどういうふうになっていくのか。","respondent":"阿部経理課長","answer":"今申し上げましたとおり、今の単品スライドですけれども、どういうルールを適用していくかというのはまだ私どもには明らかになっておりません。既に契約したものに適用するわけですけれども、どういうふうな形で適用できるのかどうか…","id":"exchange-004"},{"speaker":"金野委員","kind":"質問・要望","question":"２点ほど教えてほしいと求めました。今後も含めて教えていただきたいことと、今までのやってきた流れというんですか、今後の計画等も教えてほしいと求めました。","respondent":"中川原広報広聴課長","answer":"これも隔年実施していまして、もう１８回迎えておりますので３６年になるんですけれども、大きく分けると２つの目的があります。品川区のひな型をつくって実施するものですので、全域的にお聞きする項目、調査の強みを生かした内容で実施する予定です。","id":"exchange-005"},{"speaker":"金野委員","kind":"質問・要望","question":"基本、確認なんですが、まだまだここを知らないで持っていらっしゃらない方というのは意外に多いんだなというのを感じました。この世論調査の中でも少数意見というところを取り入れていくことを一つ要望しながら、今年実施というものに対して進めていただきたいと要望して。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"南委員","kind":"意見","question":"漏れてしまっている人がいるという、そこについてはどういう見解を区として持っているのか、そこをちょっと聞きたいんです。その１点ですとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"７ページにも書いてありますが、日刊６紙、広報スタンド、全駅です。公的な施設には全部置いてありますので、ちょっと歩けばあるところにはありますので、そこら辺でいかがでしょうかということで考えております。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"こういう時代ですから、生活をしていく上で、情報を提供していく。歩いていただきたいということでは持ち帰れないなというふうに思うので、検討していただきたいというふうに思います。","respondent":"福田企画部長","answer":"お答えをしますが、できる限りの方策を尽くしていると、このようにお伝えいただければと思います。","id":"exchange-008"},{"speaker":"南委員","kind":"提案","question":"どういう形かは今つぶさに、具体的な提案はできませんけれども、届ける努力というのはしていくという立場に立つべきだと思うんです。その点についてはどうか尋ねました。","respondent":"福田企画部長","answer":"これは税金をお預かりしてやっているわけですから、費用対効果を軽んじる中での施策展開ということは、これは到底できません。身近なものとして扱っていただく、このような基本的な考えによりまして、広報紙の配布事務を行っているところです。","id":"exchange-009"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問","question":"長期基本計画の検討委員会の中で審議されるものですから、基本的な姿勢として伺いたいと思っているんですけれども、それなりの質問とか。検討委員はそれぞれの会派から５人ですか、そういうことができるのかどうかというのは、その辺を知りたいところなんですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"南委員","kind":"確認","question":"その意見を例えば反映させてほしいみたいなことがあった場合には、とんでもない、検討委員会の中でどういうふうに。ちょっとその辺の確認をしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"文教委員会にいたときにいろいろと伺ったところでは、１０校じゃなくて今回は小学校３校なわけで、学校のこういう工事ですから。特に山中ですか、保護者への説明はどういうふうに予定されているのかということも、４点目として伺っておきたいと思います。","respondent":"阿部経理課長、宍戸施設担当課長","answer":"３校という話ですけれども、契約予定価格が９,０００万円以上のものを報告していますので、それが３校だです。１１校は計画どおりやる予定です。 予定されているものも含めまして、耐震化率については８１.８％、それからその他の建築物については６０.５％というような状況です。保護者への説明ですが、庶務課と連携いたしまして、工事に臨みたいというふうに考えております。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"あれば、どういうものなのかというのをこの際、伺っておきたいと思います。学校とは併設していない単独の園舎の幼稚園、あるいは児童福祉施設についても伺ったんですけれども、そこについても教えてほしいと求めました。","respondent":"日下部企画財政課長、宍戸施設担当課長","answer":"それが、３分の２という方向で、今検討がなされているという段階です。ただ、財政調整交付金のほうの算定対象として、取り扱いをしているというものです。 幼稚園につきましては、今年、浜川幼稚園をやることによりまして、全園、耐震化が図られます。今年度、９施設耐震化工事をやる予定になっておりまして、平成２０年度中に完了させる予定となっています。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"それ以外の、あと残っているところの１２校というのは、どういう計画になっているのかというのを教えていただきたいんです。そういう点で、どういう計画になっているかということを、改めてこの際教えていただきたいと思うんです。","respondent":"宍戸施設担当課長","answer":"それから、すべて平成２０年度中に完了させる予定というふうに申し上げましたけれども、これにつきましては耐震診断がまだの状況です。学校のほうの平成２１年度以降に予定されている施設につきましても、計画的に耐震化を図っていくというふうに考えているところです。","id":"exchange-014"},{"speaker":"南委員","kind":"確認","question":"そういう方向で検討していると、予算も含めて検討していきたいということなんですか。その辺を確認したいと思って。","respondent":"日下部企画財政課長","answer":"これは平成２０年度に予定していたものを平成２１年度にしてほしいという地元の要望を受けて、来年に回したというようなケースもあります。それで、それをもとにして速やかに耐震、それから改築ということで進めていきたいと、このように考えております。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"しかし、何というんでしょうか、大間窪と荏原三中が一貫校計画にありますね。４年先ということになりますので、くどく質問しちゃって恐縮なんですけれども、そういう点ではどうなんか尋ねました。","respondent":"市岡総務部長","answer":"その都度、要求水準の高いところまで、順次計画的に耐震化を進めております。着実に計画を実施していると、こういう方針は区のほうは明確に持っておりますので、そういうご懸念はないのではないかなというふうに思います。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"今、耐震改修工事のところなんですが、品川区、この、今、３つを見ましても、ほぼ耐震補強工事の方法ですか、方法がみんな同じだと思うんです。この工法を積極的に採用しているのか、工事内容を指定して進めているのか、その辺を説明を求めました。","respondent":"宍戸施設担当課長","answer":"そのほかにつきましては、本当にどこの工事会社でも対応できるような内容で。ある程度の補強量が見込まれるような場合につきましては、ＳＲＣブレースの工事の最大のメリットは、外側からの外づけの工法なんです。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"すると、その中の、金額として、箇所にもよると思うんですが、大体１カ所当たりどれぐらいの経費というのは、それは出てこないですか。そうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"そのほかにもあるんでしょうかということが１つと、それから、ここだけ、浜川小学校だけ「他１施設」という表現になっているんです。浜川小学校が幾つ施設があって、わかりませんので、その工夫をしたらどうですかということのお話を一つ。","respondent":"宍戸施設担当課長","answer":"それから、「他１」という部分ですが、今回、浜川幼稚園についても耐震補強工事を行うということで、それが「他１」という表現になってあります。委員から今お話しがあったとおり、耐震診断結果に基づき耐震補強工事をやっているために、内容が違ってきているという意味です。","id":"exchange-019"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"須藤委員長","kind":"質問・要望","question":"６月１３日、来週の金曜日までに、文書にて事務局のほうに提出をしてほしいと求めました。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325034?Template=document&Id=1786#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":40140,"voices":98}},{"id":"h20-20080603-14","meetingId":"h20-cm06","date":"2008年6月3日","dateIso":"2008-06-03","committee":"行財政改革特別委員会","time":"午後１時０３分～午後３時１３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件整理しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"区内業者、区内中小業者支援という観点というのは、どのように位置づけられておられるのかというところをひとつお聞きしたいなというふうに思います。入札方法、これはちょっと私全く知識がないものですから、これはどういう内容のものであったのかをまずお聞かせを願いたいと思います。","respondent":"阿部経理課長","answer":"現場説明会の廃止ですけれども、先ほど申しましたとおり、参加希望者が全員集まるですので、だれが参加しているかはっきりするわけですね。そうしますと、談合の機会が発生するというおそれがありますので、そういう観点から現場説明会を廃止しているというものです。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"その辺を抜きにして、こういう現場説明の廃止とかということで今の状況が生まれている部分というのは考えられないんでしょうかね。その辺をちょっともう少し。","respondent":"阿部経理課長","answer":"現場説明は廃止いたしましたけれども、例えば設計図書の中で質問等があれば、ファクシミリになりますけれども、当然受けております。現場説明会を廃止したことによって、先ほど委員がおっしゃったような事態とか、そういうものにつながっているという認識は持ってございません。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"１３０万円以下のいろんな物品の発注とか、１３０万円以下の随意契約の部分では、区内業者がほとんどだというふうに考えてよろしいんでしょうか。ちょっとその辺の件数を前年度ので結構ですので、件数やその辺の発注先についてちょっともう少し教えてほしいと求めました。","respondent":"阿部経理課長","answer":"物品につきましては、随意契約の割合が８９％、指名競争入札が１０％、制限付き一般競争入札が１％です。受託につきましては、随意契約が８２％、指名競争入札が１７％、制限付き一般競争入札が１％です。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"全部の数字を教えていただきましたけれども、区内業者に実際にどの程度どういうふうに仕事が回っているのかというところを、そうしたところもぜひこれからの委員会の審議の中でわかるようにしておいていただければなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"先ほどに関連して、工事案件の現場説明の廃止というところで、教育委員会のほうでプロポーザルでやるところは、そういう現場説明というのがあったように思ったんですけれども、そちらと両方同じなのか、全然こちらと教育委員会は違う契約のものを持っているのかということについて説明を求めました。","respondent":"阿部経理課長","answer":"たぶん委員がおっしゃった現場説明があったというのは、その場合には業者の説明の場、今申し上げたとおり現場説明というのは廃止をしております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"何点かお伺いしたいんですが、そういうのは、どの程度業者に対して行われているものなのか。変遷のところで、去年１年の中で試行実施した中で、これを拡大していこうというふうに至った論議の経緯をちょっとお伺いしたいなと思います。","respondent":"阿部経理課長","answer":"これは平成１９年度から試行実施をいたしまして、平成２０年度から本格実施、本格実施をしているものです。委託契約におきましては簡易型総合評価を本格実施していいという判断をいたしましたので、平成２０年度からは本格実施をしておるです。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"そこをちょっと簡単でいいんですけどもお伺いしたいのと、その後公告というのはどういうやり方でやっているのかなというのを突っ込んで聞きたいのと、そこら辺の判断はどのようにされているのかというのをお伺いしたいと思います。","respondent":"阿部経理課長","answer":"そういう面で価格だけではなく、この方式を進めていくべきだという結論に至りましたので、平成２０年度からは本格実施をしているというものです。あるいは参加できないとか、そういう判断をして、参加する工事を選んで検索しているです。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"すみません、あまりインターネットと縁がないような業者とかというのは、そういうことでそういう機会を逃している業者とかもまだまだいるんじゃないかなというのが私の心配なのかどうなのかということを実態としてはどうなんでしょうかというのをちょっと専門部署の立場からお伺いしたいんですけど。","respondent":"阿部経理課長","answer":"ネットとともに掲示もしていますけども、そもそも入札するためには登録をしなきゃいけないということになっております。東京電子自治体の中では、そういう中で登録をしなきゃいけませんので、ネットを見られないという業者はいないというふうに思っています。","id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"２点ほどお伺いしたいと思います。この(2)、一体この５,０００平米以上のものという条件にはまって議決が必要になったことというのは、そういったことをお伺いしたいと思います。","respondent":"阿部経理課長、市岡総務部長","answer":"具体的に今まで、ちょっと私今年の４月からなったものですから、これは提案があれば当然検討して取り入れていくということになろうかなと。ただ、具体的にどういうふうなものがあるかということまでは把握しておりません。 こういう物の考え方が地方自治法の考え方ですから、品川区で変えられるものではありませんので、政令で一律に決まっております。そういう趣旨で先ほど課長がご説明したです。","id":"exchange-009"},{"speaker":"阿部委員","kind":"質問・要望","question":"ぜひ早急に俎上に乗せていただければと、これも要望でよろしいです。何か答えがあれば。","respondent":"市岡総務部長","answer":"先ほど総合評価方式というのをご説明申し上げましたけれども、この要素の中に一つ加えるとか、こういう可能性があります。それから、現に施設の管理業務を委託するような場合に、全体としてそういう趣旨は取り入れつつあるというのが現状です。","id":"exchange-010"},{"speaker":"浅野委員","kind":"提案","question":"この点について１点お伺いしたいのと、こちらから提案要求仕様書ですか、ここら辺についてちょっとお伺いしたいと思いますとの意見を述べました。","respondent":"阿部経理課長","answer":"それによりまして、そういう積算基準に基づいた価格を参考にしながら、予定価格の事前公表を行っているというものです。それを参考にして予定価格を公表するという考えに基づきましてやっておりますので、これは変更するというような考えは今のところ持っておりません。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"３,０００万円以上の案件についてですけれども、同じ考え方に基づいて積算をしているということが前提になっているから、あとは価格だけのある意味では勝負というところでいいのかどうかということをお伺いしたいと思います。","respondent":"阿部経理課長、市岡総務部長","answer":"東京都のほうとそうは違わないような形になっているというふうに聞いておりますので、工事内容、こちらの見積もりの工事内容と入札に参加なさっている方の見積もりの工事の内容にそんなに大きな相違はないというふうに思っております。 それから業者の市場での競争関係、それからその資材の調達がその業者にとって非常に得意な分野なのか、そうではないのか。公正な競争をする意義であるというふうに考えてありますので…","id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"先ほどのＪＶ案なんですけど、これはその工事ごとに必ず品川区、要するにＢランクと言われているところの業者を確実にいつも入れて出しているのか。そんなような業者がＡランクのところから教えてもらいつつ、そういうことなのかどうなのかということをちょっとまずお返事をいただきたいんですが。","respondent":"阿部経理課長","answer":"ＪＶには先ほど申し上げましたけれども、親が区外の業者であった場合でも、子には必ず区内の業者を入れるというふうにしております。区内業者の活性化というか、仕事を回していくという意味合いも大きいものですので、今申し上げたような方法をとっています。","id":"exchange-013"},{"speaker":"原委員","kind":"質問","question":"今のお話は非常によくわかりましたので、ありがとうあります。今日スタートなものですから、前回の委員の中で個人の企業名を出せというような話が出たものですから、要は守秘義務の問題。","respondent":"阿部経理課長","answer":"私ども経理課の前に、どういう契約をだれがしているのかというものを閲覧できるようにしていますので、基本的には今申し上げたどの工事をどこの業者が落札したのかというようなことがわかるようにはしています。","id":"exchange-014"},{"speaker":"原委員","kind":"質問","question":"そういうふうなお話を聞いたりするものですから。これは買い戻しの話が出たんですけれども、こういった開発公社と区との間の問題も同じような形になっているんか尋ねました。","respondent":"阿部経理課長","answer":"開発公社は、区から委託を受けて土地を購入しているというものです。ちょっと情報提供というのは私どもには来てございませんので、ちょっとお答えのしようがないという状況です。","id":"exchange-015"},{"speaker":"原委員","kind":"質問","question":"そうすると、区のほうではそういったことはやっていない、行政のほうではそういった紙はないよという解釈で理解してよろしいか尋ねました。","respondent":"阿部経理課長","answer":"情報提供というのは、例えばどういう情報を提供するということでございましょうか。","id":"exchange-016"},{"speaker":"原委員","kind":"質問","question":"要はさっきの入札参加じゃないですけれども、区民のためになるためのいろんな方策があるというふうに承っているんですけど、それについて。ですから、区がしているのではなくて、一般から区に対してという意味合いです。","respondent":"阿部経理課長","answer":"私、ちょっと以前のことは承知しておりませんけれども、私が４月から来てからは情報提供されるという事例はございません。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"このあたりが問題だよというようなことが考えられるかどうか教えてもらいたいのと、どういうふうに、そのあたりを説明を求めました。","respondent":"阿部経理課長、市岡総務部長","answer":"１点目の資材の高騰のお話を含めてですけれども、予想以上に上がっている場合には、契約をスムーズに行うということはなかなか難しい場合があります。今後としては… それから、私ども品川区の部分にかかる事務システムについては、これは直営でやっております。かなり所管では苦労したというふうに聞いておりますが、私どもはそのように理解しております。","id":"exchange-018"},{"speaker":"須藤委員","kind":"意見","question":"正副にお願いしたいんだけど、どういうところを絞って、そのあたりを皆さんと１回整理をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"須藤委員","kind":"確認","question":"今日は説明をいただくけども、本来こういうところで今期は特別委員会としてやっていくんだということをもう一度皆さんで確認しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"それをちょっと紹介していただきたいというのと、どういうものなのかという、それをちょっと説明を求めました。","respondent":"阿部経理課長","answer":"建物の実施設計をした業者に工事の監理、実際工事に入りますから、工事の監理を行います。実施設計をしたものが引き続き行うことが望ましいので、実施設計をした業者をお願いしますというような形で上がってくる場合があります。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"こういう団体が能力というか、そういうノウハウを持っているからというようなことも広くとらえて、そういう随意契約が可能であるというふうに考えていいんか尋ねました。","respondent":"阿部経理課長","answer":"１３０万円未満であっても、３０万円以上のものについては、見積合わせというものが基本的にあります。経理課の前のところでやっていますので、そういう形で競争性が確保されるような形を取り入れております。","id":"exchange-022"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっと１点だけ教えていただきたいんです。そういった観点というのは、行政が入札あるいは契約を進める際にどういう位置づけになっているのか、そこだけ教えてほしいと求めました。","respondent":"阿部経理課長","answer":"今おっしゃった下請けのところを具体的にどう書いているかというところまでは、私ちょっと申しわけございませんが十分に把握しておりませんので、できれば次回以降にちょっと調査をしてお答えできるようにしたいと思います。","id":"exchange-023"},{"speaker":"原委員","kind":"確認","question":"８番、９番でちょっとここのところですが、これは街づくり特別委員会のほうということなのかな、いいですね。確認事項なんですけど。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"阿部委員","kind":"質問","question":"それぞれ建物があるわけですが、築年数は書いてあるんですけれども、耐震基準なんかの関係で今後このまま使えそうなものと、ちょっときついなというものとをそれぞれ教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"こちらの建物につきまして、それぞれまだこれから用途の検討とかもしなければなりませんので。よろしくお願いします。","id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"かなり特殊な構造の建物だったかと思うんですけれども、ああいったものというのは、転用のしやすさというのはどうなんでしょうか。ちょっとお伺いします。","respondent":"久保田行財政改革担当課長","answer":"先ほどの耐震診断の件ですけど、大崎第二地域センターと西大井シルバーセンターにつきましては、今年耐震診断をする予定です。東京都と調整しながら検討していく必要があるのかなということで、地域にふさわしいものを検討していますけれども、そういう制限がありますので。","id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"都との調整は今後の時間的なめどというのは、ある程度でもわかっていれば説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"大変申しわけないんですけども、時間的にいつまでという形ではちょっとまだ調整がついておりませんで、これから、前からも言っているんですけど、まだこれから、当面は調整が必要かなというふうに考えています。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"もちろん区の土地なので区民の財産であるわけですから、住民合意というか総意で決めたのかというところがちょっとわからない部分があるんですよ。今区が考えている、どうやって地域要求を取り入れていくかというようなお考えをちょっとお伺いしたいと思います。","respondent":"久保田行財政改革担当課長、福田企画部長","answer":"委員からお話がございましたけれども、私どものほうもこういう跡地の活用につきましては、地域の要望というか意見というのは大切だと考えています。それぞれの施設の使い道、施設ごとに… 公有地の活用に関する基本的なことだろうというふうに思いますので、私のほうからもお答えをします。広く区民のご要望に区は耳をかさなければならないというふうにも考えておりますし、また…","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"２回も移転、地域性という点では確かにこんなご時世ですから、特に地域の方の思い入れが強い施設だと思うんですね。もう少し具体的にそこに住んでいる方々の声をどう区としてまずは聞くかというところのそういうお考えをちょっともう少し突っ込んでお伺いしたいなと…","respondent":"久保田行財政改革担当課長","answer":"具体的には、随時広聴という形で区民の方の意見を聞く場というものを設けてありますので、そういうところで広く聞いていくことも可能だと思います。地域のほうに入っていって、説明会なりいろいろやる場面も出てきますので…","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"これまでずっとあった施設なわけですから、積極的に声を集めるという努力を引き続き全力を傾けていただければと思い、要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ついているものがあるかどうか、１から７の中でそういう跡地があるのかどうか伺いたいのと、あるいは区全体も地域ですから。そういう場所があるかどうか伺いたいのと、その辺の考え方ですね、地域というとらえ方をどのように考えていらっしゃるのか伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"につきましては、現在まだ検討中ということで具体的にこういう方向性というのはまだ定まっておりません。多角的な検討を行うとともに、品川区として中・長期的にどういう施設がふさわしいのかということも踏まえまして検討を進めていきたいと考えています。","id":"exchange-031"},{"speaker":"石田（慎）委員","kind":"質問","question":"その３年間というのは、何も活用しなかったらむだになってしまいますし、そういった考え方をお聞きしたいと思います。行政としてはそういった空白期間というものの考え方というのはどのような考え方をお持ちなのか、その２点をちょっとお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"委員おっしゃるように、私どものほうも既にあくという期限が決められておりますので、できるだけそういうあいた後、むだな期間がないように計画的に活用について検討を進めて、むだのないようにやっていきたいというふうに考えております。","id":"exchange-032"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうすると、基本的には空白期間はできる限りつくらないで、跡地活用の案を進めていきたいというのが区としての考えという理解でよろしいのか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"繰り返しになりますけども、期限が決まっておりますので、基本的にはあくことのないように、むだのないように、できるだけそういう形で話を進めていきたいなというふうに思っております。","id":"exchange-033"},{"speaker":"阿部委員","kind":"質問","question":"先ほどから地域の財産か区の財産かというようなことでお話があったのでお伺いしたいんですけれども、品川区、区内の公共施設というのは。区内の公共施設の全体像というのをきちんとどうしたらよりバランスがよくなるかという全体像を考えた上で、そういうお考えはありますか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"機能とか、そういうものも踏まえながら、いろいろと地域に必要なものをつくって活用していきたいなというふうに考えております。","id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"ごめんなさい。要は、この７カ所、最終的にどのようにしていくかというところまで突っ込んで話をしていくということでよろしいか尋ねました。","respondent":"福田企画部長","answer":"こうした用地はもちろんでありますけれども、例えば施設のあり方ですとか、そういうことにつきましても、私どもでは今検討を進めているところです。その一方で、それから用途制限…","id":"exchange-035"},{"speaker":"井上委員","kind":"提案","question":"資料の提案の仕方についてちょっとお伺いをしたいんですが、５番のところで、そういうところも含めて資料を提供していただきたいと思うんですが。この資料をつくるに当たっては、どういう判断でこういう資料になっているのかというのは、ちょっと先に確認をさせてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"あくまでも私どものほうの素案ということでご説明させていただきましたので、口頭でのご説明という形にさせていただきました。それがすべての地域でそういう形がいいのかどうかというのは、できるだけ地域の声を聞きながら活用策について検討を進めていきたいと考えております。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"仮の大崎在宅支援センターだとか、その辺はやっぱり情報の開示というところをもう少し広くとらえていただきたいというのは要望しておきます。再開発の中のエリアに入っているとしても、区有施設だと思うんですけど、その辺の考え方はどのようなお立場か尋ねました。","respondent":"日下部企画財政課長","answer":"大崎の東口の五丁目第一地区という再開発のエリアの中に入っておりまして、ちょっとほかのあいている土地と同列に位置づけていいものなのかどうかといったことで、そういうご提案をさせていただいたということでご理解をいただきたいというふうに思います。","id":"exchange-037"},{"speaker":"井上委員","kind":"質問・要望","question":"区有財産としてあるこういったものをどう考えるかという資料策定にしてほしいという前提があっての要望なんですけれども、そういう意味でこういう考え方をここには持っているよということを明らかにしてほしいというふうに思うんですが、いかがか尋ねました。","respondent":"福田企画部長","answer":"したがいまして、我々はこの資料の作成に対して、決して消極的ではないんですけれども、相当神経を使わなければならないというふうに思っております。したがいまして、ご意見の趣旨は理解をするところですけれども、やはり１件１件…","id":"exchange-038"},{"speaker":"須藤委員","kind":"質問","question":"長期基本計画の絡みが出てくるので、計画の策定委員会は策定委員会としてできているわけですから、そのあたりはどういうふうにお考えでしょうか。そうじゃないと、公有地の活用というのはもう少し広い意味で議会運営委員会のときには決められたと思うんですが、そのあたりはいかがですかね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"須藤委員","kind":"質問","question":"今委員長がお話しのようにこういう２点で今年度やっていくよ、これだけだと、それ以上のものは何もない話になってきちゃうと思うんだよね。ですから、ですから、それから跡地利用についてという２点で今年度はやっていきますよという考え方で理解していいのかな。","respondent":"飯沼委員長","answer":"跡地利用と施設の有効活用についてという２点で調査研究をしていきたいと考えていますけれども、正副で調整をしていきたいと考えておりますので、よろしくお願いいたします。","id":"exchange-040"},{"speaker":"須藤委員","kind":"意見","question":"いろんな考え方ができようかと思うんだけど、そういうことも我々の中で研究していく、調査していくということでいいのかなとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の公有地をどう使うかというのは、徹底をする、医療や福祉に使ってほしいんだという声が大きく今政治を動かす時代にもなっているわけですよ。そこにもどこまで区民の声を反映できるかという視点がどうしてもそちらにも必要だと思いますので、極端に言えば、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"今委員の皆さんの意見を伺いながら考えていることなんですけれども、または建物を使ってやらなければならないことというのがあると思うんですね。区民の皆さんのご意見を伺うということも非常に重要なことだと思いますけれども、伺う中でも、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"井上委員","kind":"提案","question":"その課題についてどういうふうにということが特別委員会なので一々行政にこれはどうですかああですかという話のものではないと思うんですね。で、区民がどういうものが必要であるかというのが本来私たちがここで提案すべきことなので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"阿部委員","kind":"質問","question":"ですから、２時間でやっていくと、また１年間終わってしまうんではないかというちょっと危惧があります。これは意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"菊地委員","kind":"質問","question":"あわせて足りない部分というのがしっかりとこの委員会で指摘をされるということが必要なんだろうなというふうに思っています。ですから、そういうことに対するきっちりした意見、調査をしていくべきなんだろうなというふうに思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"須藤委員","kind":"質問","question":"随意契約ですか、そのあたりを出して、皆さんで議論していかれたらどうか。１番目についてはある程度絞られてきていますので、そこを中心に課題をみんなで検討していかれたらと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"金野委員","kind":"提案","question":"２日前ぐらいですか、ここでも少し提案させていただけたら、そんなふうにも思います。どうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"間接民主主義の考え方としては自分が住民の代表としてここに来ているわけですから、それが区民の意見だということもあるんですよね。やはり区民の声をいかにやっぱり反映させるかということだと思いますので、ちょっと難しいかもしれないんですが、意見なので言わせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"阿部委員","kind":"質問","question":"委員長に質問といいますか、そのときどきの審査のテーマというのが、この資料が出てきたときに初めてわかる。少しその辺を頭に入れて、流れで審査ができるような形でやっていただけるとありがたいなと思うんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"井上委員","kind":"提案","question":"やっぱりこの中で、絞るというのはなかなか難しいんじゃないかなというふうに私としては感じています。いつどういうふうに提案したらいいのとか、どういうふうに区民が提案をしていけばいいの、ここで検討できればなというふうに思うのでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/817079?Template=document&Id=5840#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":40160,"voices":139}},{"id":"h20-20080604-16","meetingId":"h20-cm06","date":"2008年6月4日","dateIso":"2008-06-04","committee":"街づくり特別委員会","time":"午後１時０２分～午後２時４８分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この扱いについて改めてちょっと伺いたいと思いますし、そのあたりの説明がちょっとなかったので、大枠でいいですから教えてほしいと求めました。この説明だけではなかなか厳しいのだろうなと思いますので、経済的な状況が今大変な中ですから、ちょっとそのあたりのことを伺いたいと思います。","respondent":"日下部企画財政課長、青木都市開発課長","answer":"地域の皆様方が一生懸命になって検討された、区としてはそれを最大限尊重してまいりたいというふうには考えてあります。そういったことの整理も含めて、それぞれのところで検討を今進めている、そういう状況です。 資料の９ページのところで検討されています地区計画の内容で、生活関連地区というくくりにしていることの説明ですけれども、現在。ほかの転用ということも考えられますので、現在、生活関連地区というくくりで整理しています。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"住民の要求との関係で、どういうふうに見て、全体的に視点として検討していくかということをちょっと改めてもう１回伺いたいと思います。もう１つは、具体的に生活の続いているところですから、持っていないのかということをちょっと伺っておきたいと思います。","respondent":"青木都市開発課長、日下部企画財政課長","answer":"私からは、地区計画に関連します２点のご質問にお答えいたします。地区計画というのは都市計画制度ですので、具体的な施設の維持補修ということの観点では検討から外れております。 そういうような観点というのも必要だろうと、そういうことで申し上げておりますので、ご理解をいただきたいと思います。","id":"exchange-002"},{"speaker":"中塚委員","kind":"意見","question":"これで行くと１０ページの今後の流れの中で、何を言っているのか、上位計画も含めてちょっとそこの辺をご説明いただけたらなと思いますとの意見を述べました。","respondent":"青木都市開発課長","answer":"廃止された後も機能がちゃんと維持される、環境が維持されるということを東京都としてははっきり見定めておかないと廃止できないというスタンスです。区としてのスタンスをはっきり示してほしい、現在…","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう思いがあるのかなと思うんですけれども、そういう住民の方の思いをぜひ受けとめる方向でやっていただきたいなと思うんです。そういうところをどんなふうに思っているのか、基本的な姿勢を改めて伺いたいなと思います。","respondent":"青木都市開発課長","answer":"昭和５０年代に建設された都営住宅については、現在のところ、全く建て替え等は想定していないというふうに今回のおつき合いの中で確認しております。これ以上詳しくなりますと所管委員会のほうでご議論いただく内容かなと思っています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"区の基本的な考えを伺えたらと思うんですけれども、責任を果たしていこうとお考えなのか、基本的なスタンスをご説明いただけますか。","respondent":"片田建築課長","answer":"地震の被害の半減を目指すという考え方に基づいて、国のほうも含めて９０％以上を達成することが望ましいという方針が立てられてきた経過があります。耐震化を進めるに当たっては、区としては、その実現に向けて最大限のいろいろな方法を使いまして努力していきたいと考えていま…","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"どうも後退しているなというふうにも、そこをもうちょっと教えていただきたいのと、それこそ区の責任ですよね。そこはどう思っているんか尋ねました。","respondent":"片田建築課長、岩田まちづくり事業部長","answer":"今回は計画の前段の概要の事務事業概要に沿って、今、こういうところになっていますというスタンスで説明させていただいてありますので、改めて概要版をお示ししながら、区の考え方についてご説明させていただきたいと考えています。 これは耐震改修促進計画の中に明確に示しておりまして、平成２８年度までに防災上重要な公共施設については１００％完了させる。先ほどちょっと説明がありましたけれども、木造密集エリアについては、建て替えをお願いしている。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"１つだけ、個別訪問のことをちょっと説明ありましたけれども、２月ぐらいに終わるという話だったのでしょうか。そういう報告というのはあってしかるべきではないのかなと思うんですけれども、今どんなふうに思っているのか、そこだけ教えていただけますか。","respondent":"片田建築課長、岩田まちづくり事業部長","answer":"個別訪問の件ですけれども、基本的には先ほど申し上げましたように、８町丁目行ったところがありますので、その状況等については、次回以降の当委員会のほうにご報告をさせていただきたいと思います。 防災というのは、行政と区民とがともに災害に強いまちづくりプラス起きたときの対応を両輪としてやっていきましょうというのが防災対策ですから。ですから、１軒１軒今…","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"１点だけ確認させてください。確認をさせてほしいと求めました。","respondent":"日下部企画財政課長","answer":"確かに高齢者が安心して元気に暮らし続けることができるということで、検討委員会の構成を見ますと、確かに比較的高齢の方が多かったことは事実です。３の交流拠点部会では、その辺も含めて…","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"これは１つの参考資料という形になるのでしょうけれども、ぜひもっと広い視野を持って進めていただきたいということで、要望でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"前年の６月６日にこの街づくり特別委員会と同様の委員会が開かれたわけですけれども、先ほどの明晴学園が４月開設予定ということで、その４点についてお伺いしたい。","respondent":"日下部企画財政課長","answer":"八潮のまちづくりについていろいろ地域と一緒になって検討を進めてきたのかというような、また、そういったこの間の検討経過等も含めて。いろいろ連携をとりながら、できるだけいい方策をこれから少し考えていかなければいけないなと、このように考えている段階です。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"今、パトリアを私企業が経営している、私企業ですから、行政が入り込むというのは、これは非常に難しいこと。区のスタンスで、パトリア経営をしている会社に対して、例えば何かの施設の誘致を提言するというようなスタンスはとれるものなのか尋ねました。","respondent":"日下部企画財政課長","answer":"誘致について、行政側としてというのはなかなか難しい面がありますが、ただ、やはり地元の声としてそういうものを受けとめて、誘致という形で直接できるかどうかはわかりませんが、いろいろその辺また工夫の余地もあるのかなと、そのようには考えております。","id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"で、そういう施設ができるという状況をどういうふうに見ているのかというのは、ちょっと見解として伺っておきたいなと思っているんです。全然知らないことなのか、そこも含めて。","respondent":"岩田まちづくり事業部長","answer":"まだまだ元気な方たちが７割、８割いらっしゃるわけで、おそらく勝島にできるショッピングセンターみたいなものは大歓迎だろうと思うんです。どうしていくんだろうという、今お答えできるようなものは何ひとつ持ち合わせておりません。","id":"exchange-012"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"ハード面もあるけれども、地震後の区民の生活も踏まえて議論ができたらなというふうに思っているんですけれども、そういうつもりでいいのかなということを１点確認できたらと。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"風化させてはいけないわけですから、所管から説明がある促進計画も進むのかなというように感じるんです。阪神・淡路大震災、まずそこへ立ち戻って進められたらなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"街づくり特別委員会ですから、大所高所に立っていろいろな角度から検討していく質疑や意見交換が大事だというように思うんです。それはそれで商業施設の問題ではあったけれども、八潮住民のまちの全体の問題ですから、それはちょっと改めて言っておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"特別委員会ですので、八潮の問題は、私は２０年議員をやっていますけれども、ほとんど荏原なものですから、詳しいことは本当によくわからないんです。こうあるべきではないのと、南委員もいろいろ発言して、違うよと言えるわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"この２つの項目はいろいろなところにまたがっていってしまうので、議論するほうもなかなかわかりづらいと思うんです。ですから、事前に他の所管との調整をお願いして、きちっとこういう形でやっていきましょうねということでのスタートでお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"消防団ならどうだ、これはいろいろ広がって、むしろそっちのほうが議論としては深まると思うんですよね。報告事項に対する質問ではなくて、せっかく特別委員会を開いた意味を生かしていけたらなというふうに私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"そこは難しいでしょうが、委員長、副委員長のほうに仕切りをしっかりお願いしたいと。いろいろな方向に行くときは調整してくださいというだけですから、よろしく仕切りをお願いしたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"それは西本委員がそういうふうに思ってこの委員会に臨んで質問すればいいことだと思うんです。だから、改めてそういう整理をする必要はないと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"川西副委員長","kind":"質問・要望","question":"私、副委員長の立場ですけれども、伺っていまして、それぞれのご意見もっともだと思いますので、委員会運営の中で生かさせていただきたい。委員長、それでいかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/183026?Template=document&Id=6366#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":34340,"voices":89}},{"id":"h20-20080623-6","meetingId":"h20-cm06","date":"2008年6月23日","dateIso":"2008-06-23","committee":"区民委員会","time":"午前１０時０２分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"確認の意味も含めまして、ちょっと細かく何点か質問します。改めて今回、これまで区で行ってきたものがすべて網羅されているのかという確認と、加えられたものを教えてほしいと求めました。","respondent":"上川内戸籍住民課長","answer":"よその区ではそういうことを聞かれなかったとか、１つの自治体だけの条例でない付加価値といいますか、そういうものが出てきていると思います。中身も確認条例と同様なものです。","id":"exchange-001"},{"speaker":"若林委員","kind":"質問・要望","question":"本人確認と関係あるのかないのかちょっと意味がわからなかったので、もう１回ご説明いただきたいということ。3)のほうで、それでもなりすましてというんでしょうか、不正な手段を使って本人以外の方が悪意を持ってというのか尋ねました。","respondent":"上川内戸籍住民課長","answer":"聴聞等をするんですけれども、今までは過料であった、行政罰というのはお金を払ってしまえば何も残らない。今度、刑罰にすることによって刑法が適用されますので前科がつくという、そういう抑止力をねらって刑罰化をしたというものです。","id":"exchange-002"},{"speaker":"若林委員","kind":"質問・要望","question":"裁判所云々というのがあれば、ちょっと違うかなと思いましたので、もう１回ご説明をほしいと求めました。では、そこだけ確認します。","respondent":"上川内戸籍住民課長","answer":"依頼人が加害者である弁護士である場合もありますので、お話を聞きながら、そういう場合は直接家庭裁判所に出すとか。全然公証をする証明書を全然出さないというわけではなくて、加害者には触れないような形で公証の証明書の運用はしておりますという意味です。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"戸籍法および住民基本台帳のほうの改正内容のほうで確認したいんですけれども、例えば本人が行けなくて委任状とかで請求したりするのだと思うんですが、その限定というところを確認させていただきたい。","respondent":"上川内戸籍住民課長","answer":"自分だけが知っているだけではなくて、外に出すというのが目的でありますので、法としては何人でもというふうに長い間法律でも書かれていました。職務上の代理人に、それがこういう場合には出していいよというふうに細かく細分化…","id":"exchange-004"},{"speaker":"安藤委員","kind":"確認","question":"本人確認というのを、先ほど質疑のほうにも聴聞なども行うみたいな話もあったんですが、具体的には窓口ではどのような本人確認が行われるのか尋ねました。","respondent":"上川内戸籍住民課長","answer":"本人であると推定されるものの提示を求めます。それで、ちょっとそれでは弱いかなと窓口で判断をしたら、家族構成とか、ご本人の生年月日とか、そういう聴聞をして本人確認をしています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"顔で確認できませんから、どういう方だという情報をある程度お調べ、わかった上で生年月日は何日ですかと聞くということが必要になる。手元に細かい具体的な手続きがどうなっているのか、もう少しイメージを持ちたいなと思います。","respondent":"上川内戸籍住民課長","answer":"かなり現場、いろいろな審議会にもやりとりがありまして、そういう形になりました。そのような形で全国的に流れていて、今のところはスムーズに動いているということで、トラブルも聞いておりません。","id":"exchange-006"},{"speaker":"渡部委員","kind":"質問","question":"もう本当に基本的なことをお伺いしたいと思っているんですが、僕の妻が住民票が必要だからということでもらう場合、代理人になってもらうわけです。これ、全く代理人は、赤の他人が何かの関係であればとることはできるんか尋ねました。","respondent":"上川内戸籍住民課長","answer":"ただ、同じ家に住んでいても、世帯が別だと委任状をいただきます。何かトラブルがあったときには、来た方の、本人確認していますからこっちに追いかけられるというふうな方向性になるわけです。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"その代理人の範囲というのは、もうすべて赤の他人、例えば稲川委員におれの住民票をとってくれと、委任状が、要するに、この人に対して僕の住民票を渡してくれというような記載のものがあれば、それは出せるわけか尋ねました。","respondent":"上川内戸籍住民課長","answer":"委任状があれば出せます。","id":"exchange-008"},{"speaker":"渡部委員","kind":"確認","question":"取りに来た本人確認もあれば、委任状を書いていないのに住民票は出てしまうということなんですけれども、これはもう出てしまうということになってしまうんか尋ねました。","respondent":"上川内戸籍住民課長","answer":"そういう場合、その事件が明らかになった時点で、さっきの刑罰というところに行く。それからもう１つは、来た人は必ず本人確認していますから、この人が来てとっていったという証拠も残るということで、犯罪を担保しようという。","id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"２点聞きたいんですけれども、品川区の場合、どんな事例があったのかというのをわかったら教えてほしいと求めました。本人の利害関係があった、どこでどういうふうに判断するのかというのが、そこのところがよくわからないので説明してほしいと求めました。","respondent":"上川内戸籍住民課長","answer":"例えば説明する中でトラブルになったことはありますけれども、個人情報を守るためにやっているんですよと説明するしかないですよね。債務者とみなすとか、ただこの人にお金を貸したから住所を知りたいんだというだけでは、うちのほうではお出しできません。","id":"exchange-010"},{"speaker":"宮崎副委員長","kind":"意見","question":"借用書もないし、何もないので口約束で貸した、それが相手がいなくなってしまって調べたいという。そうすると、今のケースだと、全くそれは対応できないということになるんですねとの意見を述べました。","respondent":"上川内戸籍住民課長","answer":"そういう事例が日々窓口からこちらに来る悩みのあれで、じゃあ、どこまでそれに信憑性があるか。一面だけでやってしまうと、ちょっと危ない部分もありますので、それはよく話を伺って判断をさせていただいているところです。","id":"exchange-011"},{"speaker":"宮崎副委員長","kind":"質問","question":"そうすると、今みたいなケースは、一律にだめというふうにはなっていないというふうに理解すればよろしいか尋ねました。","respondent":"上川内戸籍住民課長","answer":"ただ、それだけの話でしたら、多分だめでしょうね。ここは残っていないですかとか、そういう中で判断しますが、今のその話だったらちょっと難しいかと思います。","id":"exchange-012"}]},{"id":"topic-02","title":"第４４号議案、平成２０年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第４４号議案、平成２０年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"それともう１つ、商店街連合会ということですが、商店街振興組合連合会というのはまた違うものなのか確認させてほしいと求めました。要するに、お金の流れとしてどういうふうになるのかということを確認ほしいと求めました。","respondent":"金子産業振興課長","answer":"この事業の概要が東京都から説明があったときに、特に４番目にあります商店街の規約であるとか、当初予算には間に合わなかったという経緯があります。事務局のほうは同一に活動しようという傾向が多いものですが、なかなかきちっと分けることは難しい部分もあります。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"実態、組織的に大丈夫でしょうか。どういう実態になっているか尋ねました。","respondent":"金子産業振興課長","answer":"こういった定款とか規約というものが実態に合わなくなっていても、なかなか見直しできないという現状があります。こういった認識は持っているわけですけれども、そういったところを専門家の助言を入れながらサポートしていこうというのがこの事業の趣旨です。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"この４８０万円が、例えばどういうふうに配分されて、それはあくまでも商店街のほうで全部割り振るのでしょうか。これにはこのぐらい使いましょうと、講師にはこのぐらいかかるからこうしましょうとかという、ある程度の方向性を相談しながらやるのか尋ねました。","respondent":"金子産業振興課長","answer":"専門家に見ていただいて助言をいただくということから、単価としては、予定としては３万円程度を考えているところであります。そういう作成、なおかつ印刷物、こういったものがどうしても多くかかるというふうに予定としては考えているというふうに見ておるところです。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問","question":"それからもう１つは、品川区商店街連合会のホームページを品川ポータルサイトというのでしょうか、品川区商連の紹介があります。これはどういう指導をされるのかということをお聞かせほしいと求めました。","respondent":"金子産業振興課長","answer":"申しわけありませんけれども、おそらく修正というか、カウントの仕方がちょっと違っている部分があって修正もし切れていないのかなと思います。先ほど申し上げ６７と６９という数字が公式で正しいはずなんですけれども、きちっと指導していきたいと思っています。","id":"exchange-016"},{"speaker":"若林委員","kind":"意見","question":"要するに、年に１回、２回、総会をやられて、大変盛大にやられているご様子を。これは直接区商連に言うことなのかもしれませんが、今回こういう補正予算が出てまいりましたので、ご指導いただければなと思いましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"本多委員","kind":"質問・要望","question":"例えば都の補助金が区商連の事業費の２分の１ということで歳入があるんですけれども、これ以上、こういう補助金について教えていただきたいんです。区が３分の１だから１６０万円出しているわけですけれども、この先、こういう都の補助金のあり方について説明を求めました。","respondent":"金子産業振興課長","answer":"今、ここ近年、私が経験した中では、東京都の対応というよりも、例えば４月に２３区あるいは市のほうから全部申請が上がってくるわけですね。この事業自体が東京都と区と協調しながら商店街を支援していこうということなので、できる限り支援していこうと考えているところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"どういうような中身でやるのか、ぜひ中身もすごく興味があるので見せていただきたいなと思うんですけれども、それが可能なのか。その商店街の役割に対する区の認識をちょっとお伺いしたいのと、そういう原因というのはどのように区は認識しているのかということをお伺いします。","respondent":"金子産業振興課長","answer":"今回の対象は１０商店街を予定しているということなんですけれども、予定としては、どこの商店街ということは。私どものほうとしては対象にしていきたいというふうには思っていますが、その辺を当然加味しながら実施には留意していきたいと考えています。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"本部ですか、本店ですか、そういったところにはどのように加入を促進していくというお考えなんか尋ねました。","respondent":"金子産業振興課長","answer":"本部の、これは建前と言われてはしようがないところがありますけれども、本部の方針としてはそういう方向を持っているところが非常に多うあります。そういう意味では…","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"先ほどの質問のあれなんですけれども、今のでよくわかりました。区の立場ではどのようにつかんでいる、現時点でいいんですけれども、考えておられるのかということがありましたら。","respondent":"金子産業振興課長","answer":"規約の明確、そういった現状があることも事実なので、そういったところも大きな原因の１つかなというふうには思っております。きちっとさせていこうというのが非常に、先ほどちょっとご意見をいただきましたけれども、大きな事業の要素として考えているところです。","id":"exchange-021"},{"speaker":"渡部委員","kind":"確認","question":"１つ確認なのは、あくまでもこれは助成対象者が品川区商店街連合会なので、１つ１つの商店街に出すべきものではないわけですね。その辺の確認をしたいのと、大儀的にというんですか、大きな枠のものを１つ何か考える。","respondent":"金子産業振興課長","answer":"事業の実施主体は確かに商店街連合会ですけれども、希望がある限り、予定は１０商店街となっていますけれども。そういう意味で、商店街連合会にただ単に助成するだけではなくて、区としてもきちっと協議しながら進めていくようにしていきたいと考えています。","id":"exchange-022"},{"speaker":"井桁委員","kind":"質問","question":"１つ質問なんですけれども、事業内容の３番のセミナー等専門家派遣の謝礼とあるんですが、商店街に対してということでしょうか。商店街に対して、商店に対してというセミナーではなく、商店街に対しての専門家を派遣するという考えでよろしいのか尋ねました。","respondent":"金子産業振興課長","answer":"そういったこともあり得ると思いますけれども、ちょっと細かいところはまだ詰めておりませんが、その両方が今のところはあり得るかなというふうに考えるところです。","id":"exchange-023"},{"speaker":"井桁委員","kind":"質問・要望","question":"これが１回で終わるとか、単発で終わらないようにやっていっていただきたいなと思っているんですが、そういった方向性はお考えなのか尋ねました。","respondent":"金子産業振興課長","answer":"現在の予算の中でも、講師を派遣するという予算は確保しております。今回はたまたまこの商店街組織力強化支援事業の中で講師の派遣についても予算が認められているのでここに載せておりますけれども。","id":"exchange-024"},{"speaker":"宮崎副委員長","kind":"質問","question":"この予算と１０との関係はどういうふうに考えているのかということを聞きたいのと、そういうところは実際にこういう予算の自己負担の分の用意はできているのかどうなのか、どうなっているか尋ねました。","respondent":"金子産業振興課長","answer":"あるいは条件としてそういったものも乗せていけば、これは商店街連合会としてもこれをしていくべきことというふうになるだろうと思います。商店街連合会にとってもプラスになるわけですから、そういう意味では、支障はないというふうに考えております。","id":"exchange-025"},{"speaker":"宮崎副委員長","kind":"質問","question":"今の区商連自体に加盟するというのが増えていくという、それはそれで必要なことだと思うんですけれども、そうすると、今回は区商連に助成する。今、加盟していない商店というのは加盟が条件になるということになるのか、そこら辺はどうなんか尋ねました。","respondent":"金子産業振興課長","answer":"今、商店街連合会に加盟していない商店街が商店街連合会に加盟するのが条件になるかどうかというお尋ねだと思いますけれども、それを条件にするのは、ちょっと区としては難しいかなというふうには思っております。","id":"exchange-026"},{"speaker":"宮崎副委員長","kind":"質問","question":"もう１つは、そんなことを感じるものですから、もうちょっと一歩も二歩も踏み込んだ対応なんかも考えていただければなと常々感じております。これは意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"}]},{"id":"topic-03","title":"専決処分の報告について、報告第１４号","agenda":"専決処分の報告について、報告第１４号","exchanges":[{"speaker":"稲川委員","kind":"質問・要望","question":"報告事項なので確認だけさせていただきたいんですが、多分、トラックが今どういう状況になっているのか。ドライバーはもちろん責任があると思うんですけれども、誘導をちゃんと、その責任というのはどういう形でとられているのか。","respondent":"島袋品川区清掃事務所長","answer":"うちのほうには損傷はありませんでした。我々は毎日朝礼をやっていますので、そのときに報告して、安全運転の対策委員会もやっております。","id":"exchange-028"},{"speaker":"本間委員長","kind":"質問","question":"所管質問をなさりたい委員がいらっしゃいましたら、その基礎となる一般質問の項目と、それに関する質問内容をこの場でお願いします。所管質問がございましたら、ご発言をお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう１つは、健保の扶養家族の健康診断がどうなるのかということで、そこら辺についてお伺いしたいなと。そこの項目について、より伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"安藤委員","kind":"意見","question":"それが区民健診がなくなったもので、どうなってしまうのだろうという不安があります。そこに関しての現状がどうなっているのかということを深められればと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/798229?Template=document&Id=2520#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":24875,"voices":82}}]);
